// Geocode a set of postal codes (fills db.geocodeCache) and return their real
// coordinates — the client calls this before route generation so the map and
// the distances use building-accurate points, not district centroids. Before
// the :id routes (Express ordering).
app.post('/api/transport/geocode', express.json(), async (req, res) => {
  const zips = Array.isArray(req.body?.zips) ? req.body.zips : [];
  try {
    await ensureGeocoded(zips);
    const cache = readDb().geocodeCache || {};
    const out = {};
    for (const z of zips) { const pc = String(z || '').replace(/\D/g, ''); if (cache[pc]) out[pc] = { lat: cache[pc].lat, lng: cache[pc].lng }; }
    res.json({ coords: out, geocoded: Object.keys(out).length, total: zips.length });
  } catch (e) { res.status(500).json({ error: e.message }); }
});
// Real road distance + drive time between two postal codes (OneMap routing,
// cached; straight-line×factor fallback). For a single leg or a UI check.
app.get('/api/transport/road-distance', async (req, res) => {
  const from = String(req.query.from || ''), to = String(req.query.to || '');
  if (!from || !to) return res.status(400).json({ error: 'from and to postal codes are required' });
  try { res.json(await roadLegKm(from, to)); }
  catch (e) { res.status(500).json({ error: e.message }); }
});
// OneMap routing credentials (for road distance). Admin-or-master (same guard
// as the geofence save beside it in the Zones & Drivers modal); env wins.
app.get('/api/master/onemap/config', (req, res) => {
  if (!requireTransportAdmin(req, res)) return;
  const db = readDb(); const c = db.config || {};
  const now = Math.floor(Date.now() / 1000);
  res.json({
    hasCreds: !!((process.env.ONEMAP_EMAIL || c.onemapEmail) && (process.env.ONEMAP_PASSWORD || c.onemapPassword)),
    fromEnv: !!(process.env.ONEMAP_EMAIL && process.env.ONEMAP_PASSWORD),
    tokenValid: !!(c.onemapToken && c.onemapToken.expiry - 300 > now),
    tokenExpiresAt: c.onemapToken?.expiry ? new Date(c.onemapToken.expiry * 1000).toISOString() : null,
    canRefresh: !!((process.env.ONEMAP_EMAIL || c.onemapEmail) && (process.env.ONEMAP_PASSWORD || c.onemapPassword)),
    tokenError: c.onemapTokenError || null,
    geocodeCached: Object.keys(db.geocodeCache || {}).length,
  });
});
app.post('/api/master/onemap/config', express.json(), (req, res) => {
  if (!requireTransportAdmin(req, res)) return;
  const db = readDb(); if (!db.config) db.config = {};
  let credsChanged = false;
  if (typeof req.body.email === 'string' && req.body.email.trim()) { db.config.onemapEmail = req.body.email.trim(); credsChanged = true; }
  if (typeof req.body.password === 'string' && req.body.password.trim()) { db.config.onemapPassword = req.body.password.trim(); credsChanged = true; }
  // A DIRECTLY-PASTED token works immediately (routing needs it now); its
  // expiry is read out of the JWT so onemapToken() knows when it goes stale.
  // Without email+password it cannot auto-refresh, so we say so on screen.
  if (typeof req.body.token === 'string' && req.body.token.trim()) {
    const tok = req.body.token.trim();
    let expiry = 0;
    try { expiry = Number(JSON.parse(Buffer.from(tok.split('.')[1] || '', 'base64').toString('utf8')).exp) || 0; } catch (_) {}
    // Not a decodable JWT → treat as a STATIC key: give it a far-future expiry
    // so onemapToken() actually uses it (expiry 0 read as already-expired and
    // silently ignored the paste). Whether it genuinely authorises routing is
    // proven by the Test-distance button, not assumed here.
    const isStatic = !expiry;
    if (isStatic) expiry = Math.floor(Date.now() / 1000) + 180 * 24 * 3600;
    db.config.onemapToken = { access_token: tok, expiry, static: isStatic };
    _onemapTokenMem = db.config.onemapToken;
  } else if (credsChanged) {
    db.config.onemapToken = null;   // new creds → refetch on next use
    _onemapTokenMem = null;
  }
  writeDb(db);
  logAudit('onemap_config', { by: req.userId || _tokenUserId(req) || 'master', creds: credsChanged, token: !!req.body.token });
  const now = Math.floor(Date.now() / 1000);
  res.json({
    ok: true,
    tokenValid: !!(db.config.onemapToken && db.config.onemapToken.expiry - 300 > now),
    tokenExpiresAt: db.config.onemapToken?.expiry ? new Date(db.config.onemapToken.expiry * 1000).toISOString() : null,
    canRefresh: !!((process.env.ONEMAP_EMAIL || db.config.onemapEmail) && (process.env.ONEMAP_PASSWORD || db.config.onemapPassword)),
  });
});

// ── Geofence assignments — which driver(s) cover which zone, which days ─────
// db.geofence.assignments = [{ id, region, driverId, days:[0-6] }]. Multiple
// drivers per zone = multiple rows with the same region; a driver on two zones
// = two rows. Days are 0=Sun..6=Sat. Used BEFORE the AI route generation to
// steer each zone's stops to the driver(s) who cover it that day. Before :id.
app.get('/api/transport/geofence', (req, res) => {
  const db = readDb();
  res.json({
    regions: SG_REGION_NAMES,
    regionDistricts: (() => {
      const out = {}; for (const [d, r] of Object.entries(REGION_BY_DISTRICT)) (out[r] ||= []).push(d); return out;
    })(),
    assignments: transportGeofence(db).assignments || [],
  });
});
app.post('/api/transport/geofence', express.json(), (req, res) => {
  if (!requireTransportAdmin(req, res)) return;
  const incoming = Array.isArray(req.body?.assignments) ? req.body.assignments : [];
  const clean = incoming
    .filter(a => SG_REGION_NAMES[a.region] && a.driverId)
    .map(a => ({
      id: a.id || uuidv4(),
      region: a.region,
      driverId: String(a.driverId),
      days: (Array.isArray(a.days) ? a.days : []).map(Number).filter(n => n >= 0 && n <= 6),
    }));
  const db = readDb();
  transportGeofence(db).assignments = clean;
  writeDb(db);
  logAudit('transport_geofence_saved', { by: req.userId || _tokenUserId(req) || '', count: clean.length });
  res.json({ ok: true, assignments: clean });
});

