// Generic transport record endpoints — must come after specific routes
app.get('/api/transport/:id', (req, res) => {
  const db = readDb();
  const req_data = (db.transport || []).find(r => r.id === req.params.id);
  if (!req_data) return res.status(404).json({ error: 'Transport request not found' });
  res.json(req_data);
});

app.delete('/api/transport/:id', (req, res) => {
  if (!requireTransportAdmin(req, res)) return;
  const db = readDb();
  const idx = (db.transport || []).findIndex(r => r.id === req.params.id);
  if (idx === -1) return res.status(404).json({ error: 'Transport request not found' });
  const victim = db.transport.splice(idx, 1)[0];
  writeDb(db);
  logAudit('transport_deleted', { jobs: 1, mode: 'single', id: victim.id, client: victim.clientName || '', by: req.userId || '' });
  res.json({ success: true, deleted: 1 });
});

app.post('/api/transport/:id/update', (req, res) => {
  const db = readDb();
  const request = (db.transport || []).find(r => r.id === req.params.id);
  if (!request) return res.status(404).json({ error: 'Transport request not found' });

  const updates = req.body || {};
  if (updates.status) request.status = updates.status;
  if (updates.clientName) request.clientName = updates.clientName;
  if (updates.shipping) request.shipping = { ...request.shipping, ...updates.shipping };
  if (updates.notes !== undefined) request.notes = updates.notes;
  if (updates.podRemarks !== undefined) request.podRemarks = String(updates.podRemarks || '');
  if (updates.packages !== undefined) request.packages = Number(updates.packages) || 1;
  if (updates.routeNum !== undefined) request.routeNum = updates.routeNum === null ? null : Number(updates.routeNum);
  if (updates.stopSeq  !== undefined) request.stopSeq  = updates.stopSeq  === null ? null : Number(updates.stopSeq);
  // Assigning a driver outside the planner (bulk assign / edit modal) —
  // moves the job to preplanned unless a status was explicitly given,
  // and never regresses a confirmed/delivered job.
  if (updates.assignedDriver !== undefined) {
    request.assignedDriver = updates.assignedDriver || '';
    request.assignedDriverName = updates.assignedDriverName || '';
    if (!updates.status && updates.assignedDriver &&
        request.status !== 'confirmed' && request.status !== 'delivered') {
      request.status = 'preplanned';
      request.plannedAt = new Date().toISOString();
    }
  }

  request.updatedAt = new Date().toISOString();
  writeDb(db);
  logAudit('transport_updated', { id: request.id, status: request.status, by: req.userId || '' });
  res.json(request);
});

app.post('/api/scan/learn-barcode', (req, res) => {
  const { orderNumber, barcode, sku } = req.body;
  if (!orderNumber || !barcode || !sku) return res.status(400).json({ error: 'orderNumber, barcode and sku required' });
  const bc = String(barcode).trim();
  if (!isTeachableBarcode(bc)) return res.status(400).json({ error: 'That scan does not look like a product barcode.' });

  const db    = readDb();
  const batch = findBatchForOrder(db, orderNumber);
  if (!batch) return res.status(404).json({ error: 'Order not found' });
  const ord  = batch.orders.find(o => o.order_number === orderNumber);
  const item = uniqueSkuLines(ord).find(l => l.sku === sku);
  if (!item) return res.status(404).json({ error: `SKU "${sku}" not in this order` });

  // Two teaching modes:
  //  - barcode unknown to the official listing → learn barcode → SKU
  //  - barcode officially maps to a DIFFERENT code than the order file uses
  //    (e.g. listing says 9005, order says BC010) → learn a SKU alias pair.
  //    The official listing itself is never modified.
  const official = officialResolveCode2(bc);
  let learnedKind;
  if (official && official !== item.sku) {
    if (!db.learnedSkuAliases) db.learnedSkuAliases = [];
    const exists = db.learnedSkuAliases.some(al =>
      (al.a === official && al.b === item.sku) || (al.a === item.sku && al.b === official));
    if (!exists) {
      const alias = { a: official, b: item.sku, learnedBy: req.userId || '', learnedAt: new Date().toISOString(), order: orderNumber };
      db.learnedSkuAliases.push(alias);
      _learnedSkuAliases.push(alias);
      logAudit('sku_alias_learned', { official, orderSku: item.sku, barcode: bc, order: orderNumber, by: req.userId || '' });
    }
    learnedKind = 'alias';
  } else if (!official) {
    if (!db.learnedBarcodes) db.learnedBarcodes = {};
    const entry = {
      sku: item.sku,
      description: item.description || _skuDescMap[item.sku] || '',
      learnedBy: req.userId || '',
      learnedAt: new Date().toISOString(),
      order: orderNumber,
    };
    db.learnedBarcodes[bc] = entry;
    _learnedBarcodeMap[bc] = entry;
    logAudit('barcode_learned', { barcode: bc, sku: item.sku, order: orderNumber, by: req.userId || '' });
    learnedKind = 'barcode';
  } else {
    learnedKind = 'none'; // official mapping already points at this line — just count
  }

  // Count the piece the packer is holding
  if (!batch.orderStates) batch.orderStates = {};
  const state = batch.orderStates[orderNumber] || { status: 'pending', scanned: {} };
  const holder = claimBlocker(state, req.userId);
  if (holder) return res.status(409).json({ error: `Order is being packed by ${holder} at another station.` });
  refreshClaim(state, req.userId);
  state.status = 'processing';
  state.scanned[item.sku] = (state.scanned[item.sku] || 0) + 1;
  addToActiveCarton(state, item.sku, 1);
  reconcileBinConsumption(db, batch, ord, state, item.sku); // live per-scan bin decrement
  state.updated_at = new Date().toISOString();
  appendScanLog(state, { kind: 'teach', raw: bc, sku: item.sku, qty: state.scanned[item.sku], by: req.userId || '' });
  batch.orderStates[orderNumber] = state;
  journalOrderState(orderNumber, state);
  writeDb(db);
  res.json({ ok: true, sku: item.sku, scanned_qty: state.scanned[item.sku], ordered_qty: item.qty, barcode: bc, learned: learnedKind, cartonNum: activeCarton(state).num, cartonCount: state.cartons.length });
});

app.get('/api/master/learned-barcodes', (req, res) => {
  if (!checkMaster(req, res)) return;
  const db = readDb();
  const barcodes = Object.entries(db.learnedBarcodes || {}).map(([barcode, e]) => ({ barcode, ...e }));
  barcodes.sort((a, b) => new Date(b.learnedAt) - new Date(a.learnedAt));
  const aliases = [...(db.learnedSkuAliases || [])].sort((a, b) => new Date(b.learnedAt) - new Date(a.learnedAt));
  res.json({ barcodes, aliases });
});

// Export learned entries as XLSX — send this to the client (Betime) so their
// official listing gets corrected at the source; learned entries are meant to
// be a stop-gap, not a second source of truth.
app.get('/api/master/learned-barcodes/export', (req, res) => {
  if (!checkMaster(req, res)) return;
  const db = readDb();
  const barcodes = Object.entries(db.learnedBarcodes || {}).map(([barcode, e]) => ({ barcode, ...e }));
  const aliases  = db.learnedSkuAliases || [];
  const wb = XLSX.utils.book_new();
  XLSX.utils.book_append_sheet(wb, XLSX.utils.aoa_to_sheet([
    ['Barcode', 'SKU', 'Description', 'Taught By', 'Taught At', 'On Order'],
    ...barcodes.map(e => [e.barcode, e.sku, e.description || '', e.learnedBy || '', e.learnedAt || '', e.order || '']),
  ]), 'Missing Barcodes');
  XLSX.utils.book_append_sheet(wb, XLSX.utils.aoa_to_sheet([
    ['Listing SKU', 'Order-File SKU', 'Taught By', 'Taught At', 'On Order'],
    ...aliases.map(e => [e.a, e.b, e.learnedBy || '', e.learnedAt || '', e.order || '']),
  ]), 'SKU Name Differences');
  const buf = XLSX.write(wb, { type: 'buffer', bookType: 'xlsx' });
  res.setHeader('Content-Type', 'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet');
  res.setHeader('Content-Disposition', `attachment; filename="Learned_Barcodes_${new Date().toISOString().slice(0, 10)}.xlsx"`);
  res.end(buf);
});

app.delete('/api/master/learned-aliases/:a/:b', (req, res) => {
  if (!checkMaster(req, res)) return;
  const { a, b } = req.params;
  const db = readDb();
  const match = al => (al.a === a && al.b === b) || (al.a === b && al.b === a);
  const idx = (db.learnedSkuAliases || []).findIndex(match);
  if (idx < 0) return res.status(404).json({ error: 'Alias not found' });
  db.learnedSkuAliases.splice(idx, 1);
  const idx2 = _learnedSkuAliases.findIndex(match);
  if (idx2 >= 0) _learnedSkuAliases.splice(idx2, 1);
  writeDb(db);
  logAudit('sku_alias_removed', { a, b, by: req.userId || 'master' });
  res.json({ ok: true });
});

app.delete('/api/master/learned-barcodes/:barcode', (req, res) => {
  if (!checkMaster(req, res)) return;
  const bc = req.params.barcode;
  const db = readDb();
  if (!db.learnedBarcodes?.[bc]) return res.status(404).json({ error: 'Mapping not found' });
  const removed = db.learnedBarcodes[bc];
  delete db.learnedBarcodes[bc];
  delete _learnedBarcodeMap[bc];
  writeDb(db);
  logAudit('barcode_unlearned', { barcode: bc, sku: removed.sku, by: req.userId || 'master' });
  res.json({ ok: true });
});

app.post('/api/scan/setqty', (req, res) => {
  const { orderNumber, sku, qty } = req.body;
  if (!orderNumber || !sku) return res.status(400).json({ error: 'orderNumber and sku required' });
  const db    = readDb();
  const batch = findBatchForOrder(db, orderNumber);
  if (!batch) return res.status(404).json({ error: 'Order not found' });
  const ord  = batch.orders.find(o => o.order_number === orderNumber);
  const item = uniqueSkuLines(ord).find(l => l.sku === sku);
  if (!item) return res.status(404).json({ error: `SKU "${sku}" not found` });
  // Sanity cap: a barcode "typed" into the qty field by a slow-bursting gun
  // arrives here as a gigantic number. No real count is ever this large.
  const qn = Math.max(0, parseInt(qty, 10) || 0);
  if (qn > 99999) {
    return res.status(400).json({
      error: `"${qty}" looks like a scanned barcode, not a quantity — nothing was counted. Scan the item again, or type the real count.`,
    });
  }
  if (!batch.orderStates) batch.orderStates = {};
  const state = batch.orderStates[orderNumber] || { status: 'pending', scanned: {} };
  const holder = claimBlocker(state, req.userId);
  if (holder) return res.status(409).json({ error: `Order is being packed by ${holder} at another station.` });
  refreshClaim(state, req.userId);
  state.status = 'processing';
  const prevQty = state.scanned[item.sku] || 0;
  state.scanned[item.sku] = qn;
  addToActiveCarton(state, item.sku, qn - prevQty); // manual correction — nudge the open carton by the delta
  reconcileBinConsumption(db, batch, ord, state, item.sku); // sync bins to the corrected count (up or down)
  state.updated_at = new Date().toISOString();
  appendScanLog(state, { kind: 'count', raw: '', sku: item.sku, qty: state.scanned[item.sku], by: req.userId || '' });
  batch.orderStates[orderNumber] = state;
  journalOrderState(orderNumber, state);
  writeDb(db);
  res.json({ sku: item.sku, scanned_qty: state.scanned[item.sku], ordered_qty: item.qty, cartonNum: activeCarton(state).num, cartonCount: state.cartons.length });
});

// SHORT-PICK — the packer physically found an allocated bin empty. Clear this
// SKU's phantom lots at that bin and re-allocate the order's pick to the next
// FEFO/FIFO bin, so the pick list stops pointing at an empty shelf. Audit-logged
// (a bin that reads stock but is empty is a discrepancy worth a cycle count).
app.post('/api/scan/report-bin-empty', (req, res) => {
  const { orderNumber, sku, location_id } = req.body || {};
  if (!orderNumber || !sku || !location_id) return res.status(400).json({ error: 'orderNumber, sku, location_id required' });
  const db = readDb();
  const batch = findBatchForOrder(db, orderNumber);
  if (!batch) return res.status(404).json({ error: 'Order not found' });
  const ord = batch.orders.find(o => o.order_number === orderNumber);
  if (!ord) return res.status(404).json({ error: 'Order not found' });
  const cid = batch.inventory_client || invClientId(batch.client_name);
  const strat = batch.pick_strategy || 'fefo';
  let removed = 0;
  const lines = (ord.lines || []).filter(l => l.sku === sku);
  if (inventory.available()) {
    try { removed = inventory.zeroBinLot(cid, sku, location_id, req.userId || ''); } catch (e) { console.warn('[bin-empty] zero failed', e.message); }
    // Re-allocate every line of this SKU fresh (carton-aware) — allocatePick now
    // skips the emptied bin automatically (it only picks from lots with qty > 0).
    const upc = Number((inventory.get(sku, cid) || {}).units_per_carton) || 1;
    // One ledger across every line of this SKU — re-allocating them
    // independently would point them all at the same replacement bin.
    const claim = inventory.newPickClaim();
    for (const l of lines) {
      try {
        const a = inventory.allocatePick(cid, l.sku, Number(l.qty) || 0, strat, upc, claim);
        const byLoc = []; const idx = {};
        for (const p of a.picks) { if (idx[p.location_id] === undefined) { idx[p.location_id] = byLoc.length; byLoc.push({ location_id: p.location_id, qty: 0, expiry_date: p.expiry_date || null, kind: p.kind }); } const e = byLoc[idx[p.location_id]]; e.qty += p.qty; if (p.expiry_date && (!e.expiry_date || p.expiry_date < e.expiry_date)) e.expiry_date = p.expiry_date; }
        l.pick_locations = byLoc;
        l.pick_shortfall = a.shortfall;
        l.units_per_carton = upc;
      } catch (_) {}
    }
    // Re-freeze the consume plan from the new allocation on the next scan.
    const st = batch.orderStates && batch.orderStates[orderNumber];
    if (st && st.bin_plan) delete st.bin_plan[sku];
  }
  // A bin that READ stock but was physically empty is a real discrepancy: the
  // sellable total (stock_qty) may now overstate reality → overselling risk on
  // ZORT. Open a discrepancy so someone must investigate and resolve it
  // (recount / found elsewhere / write off) — it never dies quietly in a log.
  if (removed > 0) {
    (db.stockDiscrepancies = db.stockDiscrepancies || []).unshift({
      id: uuidv4().slice(0, 8), clientId: cid, sku, location: location_id,
      qty: removed, order: orderNumber, reportedBy: req.userId || '',
      reportedAt: new Date().toISOString(), status: 'open',
    });
    if (db.stockDiscrepancies.length > 500) db.stockDiscrepancies.length = 500;
  }
  writeDb(db);
  logAudit('bin_reported_empty', { order: orderNumber, sku, location: location_id, removed, by: req.userId || '' });
  res.json({ ok: true, removed, lines: lines.map(l => ({ sku: l.sku, pick_locations: l.pick_locations || [], pick_shortfall: l.pick_shortfall || 0 })) });
});

app.post('/api/scan/save', (req, res) => {
  const { orderNumber } = req.body;
  if (!orderNumber) return res.status(400).json({ error: 'orderNumber required' });
  const db    = readDb();
  const batch = findBatchForOrder(db, orderNumber);
  if (!batch) return res.status(404).json({ error: 'Order not found' });
  if (!batch.orderStates) batch.orderStates = {};
  const state = batch.orderStates[orderNumber] || { status: 'pending', scanned: {} };
  if (state.status !== 'done' && state.status !== 'unprocessed') state.status = 'processing';
  state.updated_at = new Date().toISOString();
  batch.orderStates[orderNumber] = state;
  writeDb(db);
  res.json({ ok: true });
});

// ── The ONE completion implementation ───────────────────────────────────────
// Everything "this order is finished" entails: state flip, carton close-off,
// journal, transport confirm, stock deduction + reservation release, auto
// pickup settle, audit, ZORT push-back, stock-change fan-out, alert email.
// Called by /api/scan/complete (the normal path) AND the Administrator-gated
// mass-complete below — one implementation, because a second copy is exactly
// how the two paths would drift.
function completeOrderCore(db, batch, ord, state, { startTime, endTime, operator } = {}) {
  const orderNumber = ord.order_number;
  state.status     = 'done';
  delete state.claimedBy;
  delete state.claimedAt;
  if (state.cartons && state.cartons.length) {
    const last = state.cartons[state.cartons.length - 1];
    // A stray "New Carton" tap with nothing scanned into it yet (e.g. the
    // packer's last action before Complete) shouldn't leave a phantom
    // empty carton on the slip — drop it rather than close it.
    if (state.cartons.length > 1 && Object.keys(last.scans).length === 0) {
      state.cartons.pop();
    }
    // Close every carton still open — covers the normal case (last one)
    // AND a packer who switched back to an earlier carton to edit it and
    // completed the order without switching forward again.
    const closeTime = new Date().toISOString();
    for (const c of state.cartons) if (!c.closedAt) c.closedAt = closeTime;
  }
  state.updated_at = new Date().toISOString();
  if (startTime) state.startTime = startTime;
  if (endTime)   state.endTime   = endTime;
  if (operator)  state.operator  = operator;
  batch.orderStates[orderNumber] = state;
  journalOrderState(orderNumber, state);
  updateTransportOnOrderCompletion(db, ord, state);

  // The order shipped — deduct physical stock and release its reservation
  // (deductOrder does both). Guarded so a re-fire (e.g. offline replay) can
  // never double-deduct. Only for inventory-tracked batches. Records the
  // SKUs whose availability changed so we can notify ZORT below.
  let deductedSkus = [];
  if (batch.inventory_tracked && !state.inventory_deducted && inventory.available()) {
    const cid = batch.inventory_client || invClientId(batch.client_name);
    try {
      inventory.deductOrder(cid, { id: orderNumber, items: (ord.lines || []).map(l => ({ sku: l.sku, qty: l.qty })) });
      state.inventory_deducted = true;
      deductedSkus = [...new Set((ord.lines || []).map(l => l.sku).filter(Boolean))];
      // Bin lots are decremented LIVE per-scan (reconcileBinConsumption). Here we
      // just do a final reconcile per SKU to catch any gap — e.g. an order marked
      // done without scanning every unit — so bins always match the final count.
      for (const sku of new Set((ord.lines || []).map(l => l.sku).filter(Boolean))) {
        reconcileBinConsumption(db, batch, ord, state, sku);
      }
    } catch (e) { console.warn('[scan/complete] inventory deduct failed for', orderNumber, e.message); }
  }

  // Finished on a day we drive to the drop-off point ourselves? Then it has
  // already left as part of being finished — settle it now rather than
  // leaving Saturday's work to be closed by hand on Monday.
  applyAutoPickups(db);
  writeDb(db);
  logAudit('order_completed', completionAuditData(batch, ord, state));
  // Zort-sourced order? Push the completion back to the client's store
  // (async, never blocks completion; failures are audit-logged).
  pushZortCompletion(db, ord, state);
  // Shipped stock changed availability → notify ZORT stock-sync stores.
  if (deductedSkus.length) zortNotifyStockChange(db, batch.inventory_client || invClientId(batch.client_name), deductedSkus);
}

app.post('/api/scan/complete', (req, res) => {
  const { orderNumber, startTime, endTime, operator } = req.body;
  if (!orderNumber) return res.status(400).json({ error: 'orderNumber required' });
  const db    = readDb();
  const batch = findBatchForOrder(db, orderNumber);
  if (!batch) return res.status(404).json({ error: 'Order not found' });
  const ord   = batch.orders.find(o => o.order_number === orderNumber);
  if (!batch.orderStates) batch.orderStates = {};
  const state = batch.orderStates[orderNumber] || { status: 'pending', scanned: {} };
  const mismatches = uniqueSkuLines(ord).map(item => {
    const s = state.scanned[item.sku] || 0;
    return s !== item.qty ? { sku: item.sku, description: item.description, ordered: item.qty, scanned: s, gap: s - item.qty } : null;
  }).filter(Boolean);

  const holder = claimBlocker(state, req.userId);
  if (holder) return res.status(409).json({ error: `Order is being packed by ${holder} at another station.` });
  if (!mismatches.length) {
    completeOrderCore(db, batch, ord, state, { startTime, endTime, operator });
    sendCompletionAlert(orderNumber, ord, operator).then(result => {
      const db2    = readDb();
      const batch2 = findBatchForOrder(db2, orderNumber);
      if (batch2) {
        if (!batch2.orderStates) batch2.orderStates = {};
        const s2 = batch2.orderStates[orderNumber] || {};
        s2.alert_email_sent   = result?.sent ?? false;
        s2.alert_email_at     = new Date().toISOString();
        batch2.orderStates[orderNumber] = s2;
        writeDb(db2);
      }
    }).catch(err => {
      console.error(`[IdealOne] Completion alert FAILED for order ${orderNumber}:`, err.message);
      const db2    = readDb();
      const batch2 = findBatchForOrder(db2, orderNumber);
      if (batch2) {
        if (!batch2.orderStates) batch2.orderStates = {};
        const s2 = batch2.orderStates[orderNumber] || {};
        s2.alert_email_sent  = false;
        s2.alert_email_error = err.message;
        batch2.orderStates[orderNumber] = s2;
        writeDb(db2);
      }
    });
    return res.json({ ok: true, mismatches: [] });
  }
  res.json({ ok: false, mismatches });
});

// ── Mass complete — bypass scanning, Administrator password ONLY ────────────
// Per the user: complete selected orders in one action without the scan step,
// gated on the Administrator password (checkMaster), not any admin's own —
// skipping the physical check is a management override, and the trail says so.
// A MASS COMPLETE IS NOT A COUNT (same honesty rule as inbound mass-receive):
// nobody scanned these pieces. Quantities are set to the ordered figures so
// totals reconcile, and the bypass is recorded on the order (scan log +
// mass_completed stamp) and in the audit trail. Runs the SAME
// completeOrderCore as a scanned completion — stock deducts, reservations
// release, transport confirms, and a synced order still reports back to its
// store — so a bypassed order is indistinguishable downstream except for the
// honest markers. Completion alert emails are deliberately NOT sent per order
// (a bulk backfill would spam the client with N mails at once).
app.post('/api/master/orders/mass-complete', (req, res) => {
  if (!checkMaster(req, res)) return;
  const wanted = [...new Set((req.body?.orders || []).map(String))];
  if (!wanted.length) return res.status(400).json({ error: 'No orders listed' });
  const db = readDb();
  // Master-key routes never get req.userId populated (the standing gotcha the
  // PII routes hit) — resolve the signed-in staff user from the token, or the
  // trail names nobody.
  const who = req.userId || _tokenUserId(req) || '';
  const now = new Date().toISOString();
  const completed = [], refused = [];
  for (const orderNumber of wanted) {
    const batch = findBatchForOrder(db, orderNumber);
    if (!batch) { refused.push({ order: orderNumber, why: 'not found' }); continue; }
    const ord = batch.orders.find(o => o.order_number === orderNumber);
    if (!batch.orderStates) batch.orderStates = {};
    const state = batch.orderStates[orderNumber] || { status: 'pending', scanned: {} };
    if (state.status === 'done')        { refused.push({ order: orderNumber, why: 'already completed' }); continue; }
    if (state.status === 'unprocessed') { refused.push({ order: orderNumber, why: 'cancelled' }); continue; }
    // Someone mid-pick at a station keeps their order — an override must not
    // yank work out of a packer's hands. Refused by name; retry after.
    const holder = claimBlocker(state, req.userId);
    if (holder) { refused.push({ order: orderNumber, why: `being packed by ${holder} right now` }); continue; }
    if (!state.scanned) state.scanned = {};
    for (const item of uniqueSkuLines(ord)) state.scanned[item.sku] = item.qty;
    appendScanLog(state, { kind: 'mass_completed', by: who, note: 'completed without scanning (Administrator override)' });
    state.mass_completed = { by: who, at: now };
    completeOrderCore(db, batch, ord, state, { startTime: state.startTime || now, endTime: now, operator: who });
    completed.push(orderNumber);
  }
  logAudit('orders_mass_completed', { count: completed.length, orders: completed.slice(0, 100), refused: refused.slice(0, 30), by: who });
  res.json({ ok: true, completed, refused });
});

// ── "THESE ARE NOT OURS TO FULFIL" — the sticky way to say it ──────────────
// Reported from the floor: a client's orders were being DELETED because the
// client fulfils them at their own end, and they came straight back on the
// next pull. Of course they did — the pull skips order numbers it already
// holds, so deleting an order is precisely how you make it look new again.
// Marking it CANCELLED keeps the record (so the dedup still sees it), takes it
// off the packers' list, and releases anything it had reserved. That is the
// primitive this needs, in bulk, with the reason on the trail.
app.post('/api/orders/bulk-cancel', express.json(), (req, res) => {
  const wanted = [...new Set((req.body?.orders || []).map(String))];
  const reason = String(req.body?.reason || '').trim();
  if (!wanted.length) return res.status(400).json({ error: 'No orders listed' });
  if (reason.length < 6) return res.status(400).json({ error: 'Give a reason — it goes on the trail and is the only record of why these were not fulfilled.' });
  const db = readDb();
  const who = req.userId || _tokenUserId(req) || '';
  const now = new Date().toISOString();
  const cancelled = [], refused = [];
  for (const orderNumber of wanted) {
    const batch = findBatchForOrder(db, orderNumber);
    if (!batch) { refused.push({ order: orderNumber, why: 'not found' }); continue; }
    if (!batch.orderStates) batch.orderStates = {};
    const st = batch.orderStates[orderNumber] || { status: 'pending', scanned: {} };
    // COMPLETED WORK IS NEVER UNDONE — the standing rule everywhere else.
    if (st.status === 'done') { refused.push({ order: orderNumber, why: 'already completed' }); continue; }
    if (st.status === 'unprocessed') { refused.push({ order: orderNumber, why: 'already cancelled' }); continue; }
    const holder = claimBlocker(st, req.userId);
    if (holder) { refused.push({ order: orderNumber, why: `open at ${holder}'s station` }); continue; }
    st.status = 'unprocessed';
    st.unprocessed_reason = reason;
    st.unprocessed_at = now;
    st.updated_at = now;
    delete st.claimedBy; delete st.claimedAt;
    batch.orderStates[orderNumber] = st;
    cancelled.push(orderNumber);
  }
  // Give back whatever they had promised — same reconciler every other
  // removal path uses.
  try { releaseOrphanReservations(db); } catch (e) { console.error('[bulk-cancel]', e.message); }
  try { closeSettledBackorders(db); } catch (_) {}
  writeDb(db);
  logAudit('orders_bulk_cancelled', { count: cancelled.length, orders: cancelled.slice(0, 100), reason, refused: refused.slice(0, 20), by: who });
  res.json({ ok: true, cancelled, refused });
});

// THE MOVE ITSELF, shared by the single-order route and the bulk one — a second
// copy would drift, and the first thing to drift would be whether the stock
// followed the order. Returns {ok:false,status,error} instead of touching res,
// so the bulk caller can report per-order outcomes and carry on.
function refileOneOrder(db, orderNumber, clientRaw, reason, who) {
  const batch = findBatchForOrder(db, orderNumber);
  if (!batch) return { ok: false, status: 404, error: 'Order not found.' };
  const from = String(batch.client_name || '').trim();
  // Adopt the spelling this client is already known by rather than imposing
  // another case-variant — "Mayer2026" and "MAYER2026" must stay one account.
  const target = canonicalClientName(db, String(clientRaw || '').trim());
  if (!target) return { ok: false, status: 400, error: 'Name the client this order belongs to.' };
  if (from.toLowerCase() === target.toLowerCase()) {
    return { ok: false, status: 400, error: `Already filed under ${from}.` };
  }
  const st = (batch.orderStates || {})[orderNumber] || { status: 'pending', scanned: {} };
  const done = st.status === 'done';
  // A half-picked order underneath somebody is the one case still refused: the
  // stock they are picking against would move mid-pick.
  const holder = done ? null : claimBlocker(st, who);
  if (holder) return { ok: false, status: 409, error: `Open at ${holder}'s station.` };

  const order = (batch.orders || []).find(o => o.order_number === orderNumber);
  if (!order) return { ok: false, status: 404, error: 'Order not found in its batch.' };
  const now = new Date().toISOString();
  const oldCid = batch.inventory_client || invClientId(from);
  const newCid = invClientId(target);
  const items = (order.lines || []).filter(l => l.sku).map(l => ({ sku: l.sku, qty: Number(l.qty) || 0 }));

  let releasedUnits = 0, gaveBack = 0, tookOff = 0;
  const notInMaster = [];
  if (done) {
    // A COMPLETED ORDER'S GOODS HAVE ALREADY LEFT. Per the user these must be
    // reclassifiable too, and what is wrong is the ATTRIBUTION, not the
    // shipment. So the deduction is MOVED at account level: given back on the
    // account it was wrongly taken from, and taken on the one that really
    // shipped it, as `adjustment` movements that name the refile on both sides.
    //
    // BIN-LEVEL POSITIONS ARE NOT REWRITTEN, and cannot honestly be: the pieces
    // physically came out of the old client's bins, and inventing a bin
    // movement on the new client would be a claim about where stock sat that
    // nobody can support. The answer says so, because it means the two accounts
    // now need a cycle count to line their bins up with their balances.
    if (st.inventory_deducted && inventory.available()) {
      for (const it of items) {
        try {
          inventory.adjust(it.sku, oldCid, it.qty, 'adjustment',
            `Refiled ${orderNumber} to ${target} — this account never shipped it`);
          gaveBack += it.qty;
        } catch (e) { /* the SKU is not on that account — nothing was taken off it */ }
      }
    }
    if (clientStockTracked(newCid) && inventory.available()) {
      for (const it of items) {
        try {
          inventory.adjust(it.sku, newCid, -it.qty, 'adjustment',
            `Refiled ${orderNumber} from ${from} — shipped against this account`);
          tookOff += it.qty;
        } catch (e) { notInMaster.push(it.sku); }   // named, never silently created
      }
      if (tookOff) st.inventory_deducted = true;
    }
  } else if (inventory.available()) {
    // GIVE THE UNITS BACK on the account they were wrongly promised against.
    // Derived from the ledger (what this order still actually holds), never
    // assumed from its lines — releasing a quantity it never reserved would
    // free somebody else's units on the same SKU.
    try {
      const open = inventory.openReservations(oldCid).filter(r => String(r.order_id) === orderNumber);
      if (open.length) {
        inventory.releaseOrder(oldCid, { id: orderNumber, items: open.map(r => ({ sku: r.sku, qty: r.open_qty })) });
        releasedUnits = open.reduce((n, r) => n + Number(r.open_qty || 0), 0);
      }
    } catch (e) { console.warn('[refile] release failed:', e.message); }
  }

  // MOVE IT. A batch holding only this order is simply renamed; otherwise the
  // order is split into its own batch, which KEEPS the job code, filename,
  // upload time and uploader — the order really did arrive on that job, and
  // rewriting its provenance to tidy away a filing mistake would be worse than
  // the mistake. `contentHash` is deliberately NOT copied: that is the
  // same-file re-upload fingerprint, and two batches answering to it would make
  // that check ambiguous.
  let newBatch = batch, split = false;
  if ((batch.orders || []).length === 1) {
    batch.client_name = target;
  } else {
    split = true;
    newBatch = {
      id: uuidv4(),
      idealscan_code: batch.idealscan_code || '',
      filename: batch.filename || '',
      uploaded_at: batch.uploaded_at || now,
      uploaded_by: batch.uploaded_by || '',
      client_name: target,
      orders: [order],
      orderStates: { [orderNumber]: st },
      order_count: 1,
      row_count: (order.lines || []).length,
      refiled_from: batch.id, refiled_at: now, refiled_by: who, refiled_reason: reason,
    };
    batch.orders = (batch.orders || []).filter(o => o.order_number !== orderNumber);
    if (batch.orderStates) delete batch.orderStates[orderNumber];
    batch.order_count = batch.orders.length;
    batch.row_count = batch.orders.reduce((n, o) => n + (o.lines || []).length, 0);
    // NEWEST BATCH WINS in globalOrdersWithState (first seen for an order
    // number), and db.batches is newest-first — so the new batch must be
    // unshifted or the order would keep resolving through the old one.
    db.batches.unshift(newBatch);
  }

  // RESERVE ON THE NEW ACCOUNT, if that client's stock is tracked here. This
  // also re-runs pick allocation, which matters more than it looks: the pick
  // list was pointing at the OLD client's bins. A shipped order has nothing to
  // reserve and nothing left to pick.
  let tracked = done ? !!st.inventory_deducted : false;
  if (!done && clientStockTracked(newCid)) {
    try {
      const rr = reserveIntakeOrders(db, newCid, target, [order], newBatch.id, 'fefo', 'wait');
      tracked = !!rr.tracked;
    } catch (e) { console.warn('[refile] reserve failed:', e.message); }
  }
  newBatch.inventory_tracked = tracked;
  newBatch.inventory_client = tracked ? newCid : '';

  // A SHORTFALL ON THE NEW ACCOUNT IS REPORTED, NEVER A BLOCK. The order is real
  // and already on the floor; a backorder keeps it visible instead of stranding
  // it under the wrong client.
  const shortfall = (db.backorders || [])
    .filter(b => String(b.order_number) === orderNumber && b.status === 'open')
    .map(b => ({ sku: b.sku, short: Number(b.shortfall) || 0 }));

  // RECORDS THAT STAMPED THE CLIENT rather than deriving it. Backorders carry
  // it; transport jobs deliberately do NOT get rewritten — their `clientName`
  // is the CONSIGNEE (who receives the parcel), not whose account it bills to.
  for (const bo of db.backorders || []) {
    if (String(bo.order_number) === orderNumber) { bo.client_name = target; bo.client_id = newCid; }
  }
  // The catalogue learns from what passes through, so the new client's item
  // master picks up this order's wording too.
  try { harvestCatalogueFromOrders(db, target, [order], 'refile'); } catch (_) {}

  // THE "SKUs → …" FLAG IS ANSWERED NOW. It is stamped at pull time to say
  // attribution could not decide and the filing fell back — and its tooltip
  // tells you to fix the item master and re-pull. Once a person has said where
  // this order belongs, both halves of that are wrong: the row is settled, and
  // re-pulling would do nothing (the sync skips numbers it already holds). A
  // warning that outlives the decision it asked for trains people to ignore
  // warnings. It is kept on the audit entry, so what it said is not lost.
  const wasHinted = order.attribution_hint || null;
  if (wasHinted) delete order.attribution_hint;

  // A LIVE WAVE'S PICK LIST WAS BUILT AGAINST THE OLD CLIENT'S BINS. Saying so
  // is the honest move — silently leaving it would send a picker to a bin that
  // belongs to another account.
  const wave = (db.waves || []).find(w => w.status !== 'completed' && w.status !== 'cancelled'
    && (w.order_numbers || []).includes(orderNumber));

  logAudit('order_refiled', {
    order: orderNumber, from, to: target, reason, by: who,
    batchId: newBatch.id, fromBatchId: batch.id, split, completed: done,
    releasedUnits, gaveBack, tookOff, notInMaster: notInMaster.slice(0, 20),
    reservedOn: tracked ? newCid : '', shortfall: shortfall.slice(0, 20),
    wave: wave ? (wave.code || wave.id) : '', wasHinted,
  });

  const note = `${orderNumber} now belongs to ${target}.`
    + (releasedUnits ? ` ${releasedUnits} unit(s) released back to ${from}.` : '')
    + (done
        ? (gaveBack ? ` ${gaveBack} unit(s) given back to ${from}.` : '')
          + (tookOff ? ` ${tookOff} unit(s) deducted from ${target} instead.` : '')
          + ((gaveBack || tookOff)
              ? ' Bin positions are NOT rewritten — the pieces physically left the old bins — so both accounts want a cycle count on these SKUs.'
              : ' Its stock was never deducted here, so nothing moved.')
        : (tracked ? ` Reserved against ${target}.` : ` ${target}'s stock is not tracked here, so nothing was reserved.`))
    + (notInMaster.length ? ` Not in ${target}'s item master, so nothing was deducted for: ${notInMaster.join(', ')}.` : '')
    + (shortfall.length ? ` ${shortfall.length} line(s) could not be covered and are on backorder.` : '')
    + (wave ? ` It is in wave ${wave.code || wave.id} — regenerate that wave so its pick list points at ${target}'s bins.` : '');

  return {
    ok: true, order: orderNumber, from, to: target, split, completed: done,
    releasedUnits, gaveBack, tookOff, notInMaster, tracked, shortfall,
    wave: wave ? { id: wave.id, code: wave.code || '' } : null, note,
  };
}

// ── FILED UNDER THE WRONG CLIENT — move it ───────────────────────────────────
// Reported live: a Lazada order whose SKUs are registered in TWO item masters
// could not be attributed, fell back to the channel map, and landed under a
// "client" called LAZADA — a sales channel, not an account. The order was in
// IdealOne all along; it was invisible from everywhere scoped to the client it
// actually belongs to (their portal, their stock, their billing, the sidebar
// filter), which reads exactly like a missing order.
//
// THE BATCH IS WHAT CARRIES THE CLIENT, so the fix is to move the order into a
// batch that names the right one. Every reader — portal, billing, reports,
// sidebar, stock — resolves an order's client through `batch.client_name`; a
// per-order override would mean editing dozens of read sites and silently
// missing one, which is the same class of mistake that misfiled this order to
// begin with.
//
// Re-pulling cannot fix it: the sync skips order numbers it already holds (that
// is what makes re-pulls idempotent), so the misfiled copy would simply stay.
app.post('/api/orders/:orderNumber/refile', express.json(), (req, res) => {
  if (!requireInboundAdmin(req, res, 'refile an order under a different client')) return;
  const reason = String(req.body?.reason || '').trim();
  // A reason is the only record of why an order changed accounts, and this
  // moves whose stock, billing and portal it sits on.
  if (reason.length < 6) {
    return res.status(400).json({ error: 'Give a reason — moving an order between accounts changes whose stock, billing and portal it sits on, and this is the only record of why.' });
  }
  const db = readDb();
  const who = req.userId || _tokenUserId(req) || '';
  const out = refileOneOrder(db, String(req.params.orderNumber || ''), req.body?.client, reason, who);
  if (!out.ok) return res.status(out.status).json({ error: out.error });
  writeDb(db);
  res.json(out);
});

// ── THE SAME THING FOR A SCREENFUL ───────────────────────────────────────────
// One misattributed SKU misfiles every order that carries it, so these arrive in
// batches, not one at a time. ONE db write for the lot, and a per-order outcome
// so a single refusal reports itself instead of stopping the rest.
app.post('/api/orders/bulk-refile', express.json(), (req, res) => {
  if (!requireInboundAdmin(req, res, 'refile orders under a different client')) return;
  const wanted = [...new Set((req.body?.orders || []).map(String).filter(Boolean))];
  const reason = String(req.body?.reason || '').trim();
  const client = String(req.body?.client || '').trim();
  if (!wanted.length) return res.status(400).json({ error: 'No orders listed.' });
  if (!client) return res.status(400).json({ error: 'Name the client these orders belong to.' });
  if (reason.length < 6) {
    return res.status(400).json({ error: 'Give a reason — moving orders between accounts changes whose stock, billing and portal they sit on, and this is the only record of why.' });
  }
  if (wanted.length > 500) return res.status(400).json({ error: 'Refile at most 500 orders at a time.' });
  const db = readDb();
  const who = req.userId || _tokenUserId(req) || '';
  const moved = [], refused = [];
  for (const orderNumber of wanted) {
    const out = refileOneOrder(db, orderNumber, client, reason, who);
    if (out.ok) moved.push(out);
    else refused.push({ order: orderNumber, why: out.error });
  }
  writeDb(db);
  logAudit('orders_bulk_refiled', {
    to: client, reason, by: who, count: moved.length,
    orders: moved.map(m => m.order).slice(0, 200),
    refused: refused.slice(0, 50),
  });
  const completed = moved.filter(m => m.completed).length;
  const waves = [...new Set(moved.map(m => m.wave?.code || m.wave?.id).filter(Boolean))];
  const notInMaster = [...new Set(moved.flatMap(m => m.notInMaster || []))];
  res.json({
    ok: true, to: client, moved, refused,
    note: `${moved.length} order(s) now belong to ${client}.`
      + (completed ? ` ${completed} of them were already completed — their stock deduction was moved too, but bin positions are NOT rewritten, so both accounts want a cycle count.` : '')
      + (notInMaster.length ? ` Not in ${client}'s item master, so nothing was deducted for: ${notInMaster.slice(0, 15).join(', ')}.` : '')
      + (waves.length ? ` Regenerate wave(s) ${waves.join(', ')} — their pick lists were built against the old client's bins.` : '')
      + (refused.length ? ` ${refused.length} could not be moved.` : ''),
  });
});

app.post('/api/scan/cancel', (req, res) => {
  const { orderNumber, startTime, endTime, operator, mismatches } = req.body;
  if (!orderNumber) return res.status(400).json({ error: 'orderNumber required' });
  const db    = readDb();
  const batch = findBatchForOrder(db, orderNumber);
  if (!batch) return res.status(404).json({ error: 'Order not found' });
  if (!batch.orderStates) batch.orderStates = {};
  const prevState = batch.orderStates[orderNumber] || { scanned: {} };
  batch.orderStates[orderNumber] = {
    status:     'unprocessed',
    scanned:    prevState.scanned || {},
    mismatches: Array.isArray(mismatches) ? mismatches : [],
    updated_at: new Date().toISOString(),
    ...(startTime && { startTime }),
    ...(endTime   && { endTime }),
    ...(operator  && { operator }),
  };
  writeDb(db);
  logAudit('order_cancelled', {
    order: orderNumber, batchId: batch.id, client: batch.client_name || '',
    operator: operator || '', mismatches: Array.isArray(mismatches) ? mismatches : [],
  });
  res.json({ ok: true });
});

app.post('/api/scan/reset', (req, res) => {
  const { orderNumber } = req.body;
  if (!orderNumber) return res.status(400).json({ error: 'orderNumber required' });
  const db    = readDb();
  const batch = findBatchForOrder(db, orderNumber);
  if (!batch) return res.status(404).json({ error: 'Order not found' });
  if (!batch.orderStates) batch.orderStates = {};
  batch.orderStates[orderNumber] = { status: 'pending', scanned: {}, updated_at: new Date().toISOString() };
  writeDb(db);
  res.json({ ok: true });
});

app.post('/api/scan/resend-completion-alert', async (req, res) => {
  const { orderNumber } = req.body;
  if (!orderNumber) return res.status(400).json({ error: 'orderNumber required' });
  const db    = readDb();
  const batch = findBatchForOrder(db, orderNumber);
  if (!batch) return res.status(404).json({ error: 'Order not found' });
  const ord = batch.orders.find(o => o.order_number === orderNumber);
  const state = (batch.orderStates || {})[orderNumber] || {};
  try {
    await sendCompletionAlert(orderNumber, ord, state.operator);
    if (!batch.orderStates) batch.orderStates = {};
    const s = batch.orderStates[orderNumber] || {};
    s.alert_email_sent  = true;
    s.alert_email_at    = new Date().toISOString();
    delete s.alert_email_error;
    batch.orderStates[orderNumber] = s;
    writeDb(db);
    res.json({ ok: true });
  } catch (err) {
    res.status(500).json({ error: err.message });
  }
});

app.post('/api/scan/keyfields-close', (req, res) => {
  const { orderNumber } = req.body;
  if (!orderNumber) return res.status(400).json({ error: 'orderNumber required' });
  const db    = readDb();
  const batch = findBatchForOrder(db, orderNumber);
  if (!batch) return res.status(404).json({ error: 'Order not found' });
  if (!batch.orderStates) batch.orderStates = {};
  const state = batch.orderStates[orderNumber] || { status: 'pending', scanned: {} };
  state.keyfields_closed    = true;
  state.keyfields_closed_at = new Date().toISOString();
  batch.orderStates[orderNumber] = state;
  writeDb(db);
  res.json({ ok: true });
});

// ── Auth / session enforcement ───────────────────────────────────────────────
// One active session per user. Sessions are persisted in the DB so they
// survive server restarts and Railway redeploys.
const activeSessions = new Map(); // userId → token

// Restore sessions from the GLOBAL db on startup (sessions are cross-tenant —
// the token is what tells us which user, and hence which tenant, this is).
(function restoreSessions() {
  try {
    const db = readGlobalDb();
    for (const [userId, token] of Object.entries(db.sessions || {})) {
      activeSessions.set(userId, token);
    }
    console.log(`[IdealOne] Restored ${activeSessions.size} session(s) from DB`);
  } catch {}
})();

function persistSessions() {
  const db = readGlobalDb();
  db.sessions = Object.fromEntries(activeSessions);
  writeGlobalDb(db);
}

// requireAuthOrToken: accepts token in header OR ?token= query param (for PDF iframes)
// Same as requireAuth, but ALSO accepts ?token= — for <img src> and <embed>,
// which cannot send a header. It is used by the PDF and photo viewers.
//
// IT MUST SKIP NAMESPACED SESSIONS FOR THE SAME REASON requireAuth DOES, and
// for a long time it did not: a client-portal (or driver) token was accepted
// here, so any signed-in client could fetch ANY order's waybill, any label
// import page, any inbound photo — including other clients'. Found by a test
// asserting a portal token could not reach the staff label route; it could.
// The portal has its own ownership-checked label route.
function requireAuthOrToken(req, res, next) {
  const token = req.headers['x-auth-token'] || req.query.token;
  if (!token) return res.status(401).json({ error: 'Unauthorised' });
  for (const [userId, t] of activeSessions) {
    if (userId.startsWith('driver:') || userId.startsWith('portal:')) continue;
    if (t === token) { req.userId = userId; return next(); }
  }
  res.status(401).json({ error: 'Session expired' });
}

function requireAuth(req, res, next) {
  const token = req.headers['x-auth-token'];
  if (!token) return res.status(401).json({ error: 'Unauthorised' });
  for (const [userId, t] of activeSessions) {
    // Namespaced sessions (driver app / client portal) are NOT staff — their
    // tokens must never unlock staff APIs. Each has its own middleware.
    if (userId.startsWith('driver:') || userId.startsWith('portal:')) continue;
    if (t === token) { req.userId = userId; return next(); }
  }
  res.status(401).json({ error: 'Session expired' });
}

// Client info for the login audit trail
function clientInfo(req) {
  return {
    ip: String(req.headers['x-forwarded-for'] || req.socket?.remoteAddress || '').split(',')[0].trim(),
    device: String(req.headers['user-agent'] || '').slice(0, 160),
  };
}

app.post('/api/auth/login', (req, res) => {
  const { id, password } = req.body;
  if (!id || !password) return res.status(400).json({ error: 'User ID and password required' });
  // Case-insensitive ID match — "MASTER", "Master" and "master" are the same
  // account (passwords remain case-sensitive)
  const idNorm = String(id).trim().toLowerCase();
  const wait = loginBlockedFor(req, idNorm);
  if (wait) {
    logAudit('login_throttled', { user: String(id).trim().slice(0, 60), retryAfter: wait, ...clientInfo(req) });
    res.setHeader('Retry-After', String(wait));
    return res.status(429).json({ error: `Too many failed attempts. Try again in ${wait}s.`, retryAfter: wait });
  }
  const user = readUsers().find(u => String(u.id).trim().toLowerCase() === idNorm);
  if (!user || hashPass(password, user.salt) !== user.passwordHash) {
    loginFailure(req, idNorm);
    logAudit('login_failed', { user: String(id).trim().slice(0, 60), ...clientInfo(req) });
    return res.status(401).json({ error: 'Invalid credentials' });
  }
  // Defense in depth: a 'driver' row should never exist in db.users[] at all
  // (see POST /api/master/users and PUT .../role — driver rows only ever go
  // to db.drivers[]), so this should be unreachable in practice. Still
  // refused explicitly rather than trusting that invariant blindly — a
  // driver must only ever reach /driver on mobile, never this desktop app.
  if (user.role === 'driver') {
    logAudit('login_failed', { user: user.id, reason: 'driver_role_desktop_blocked', ...clientInfo(req) });
    return res.status(403).json({ error: 'Drivers use the Driver App at /driver — this login is for office/warehouse staff only.' });
  }
  loginSuccess(req, idNorm);
  const token = uuidv4();
  const kickedOther = activeSessions.has(user.id);
  activeSessions.set(user.id, token); // replaces any existing session for this user
  persistSessions();
  logAudit('login', { user: user.id, replacedSession: kickedOther, ...clientInfo(req) });
  res.json({ id: user.id, name: user.name || user.id, role: user.role || 'admin', token });
});

app.post('/api/auth/logout', (req, res) => {
  const token = req.headers['x-auth-token'];
  if (token) {
    for (const [userId, t] of activeSessions) {
      if (t === token) {
        activeSessions.delete(userId);
        logAudit('logout', { user: userId, ...clientInfo(req) });
        break;
      }
    }
    persistSessions();
  }
  res.json({ ok: true });
});

// ── Profile — per-user settings (printer, label size) ───────────────────────
const VALID_LABEL_SIZES = ['100x160', '100x150', '4x6'];

app.get('/api/profile', requireAuth, (req, res) => {
  const user = readUsers().find(u => u.id === req.userId);
  if (!user) return res.status(404).json({ error: 'User not found' });
  res.json({
    id:          user.id,
    name:        user.name,
    role:        user.role || 'admin',
    printerName: user.printerName || '',
    labelSize:   user.labelSize   || '100x160',
    tablePrefs:  user.tablePrefs  || null,
    features:    user.features    || null,
  });
});

// Per-user orders-table layout: column widths (px) and hidden columns
app.put('/api/profile/table-prefs', requireAuth, (req, res) => {
  const users = readUsers();
  const idx   = users.findIndex(u => u.id === req.userId);
  if (idx < 0) return res.status(404).json({ error: 'User not found' });
  const { widths, hidden } = req.body || {};
  const clean = { widths: {}, hidden: [] };
  if (widths && typeof widths === 'object') {
    for (const [k, v] of Object.entries(widths)) {
      const px = Math.round(Number(v));
      if (/^[a-z_]{2,20}$/.test(k) && px >= 40 && px <= 800) clean.widths[k] = px;
    }
  }
  if (Array.isArray(hidden)) {
    clean.hidden = hidden.filter(h => /^[a-z_]{2,20}$/.test(h)).slice(0, 12);
  }
  users[idx].tablePrefs = clean;
  writeUsers(users);
  res.json({ ok: true, tablePrefs: clean });
});

app.put('/api/profile/printer', requireAuth, (req, res) => {
  const { printerName, labelSize } = req.body || {};
  const users = readUsers();
  const idx   = users.findIndex(u => u.id === req.userId);
  if (idx < 0) return res.status(404).json({ error: 'User not found' });
  users[idx].printerName = String(printerName || '').trim().slice(0, 120);
  users[idx].labelSize   = VALID_LABEL_SIZES.includes(labelSize) ? labelSize : '100x160';
  writeUsers(users);
  res.json({ ok: true, printerName: users[idx].printerName, labelSize: users[idx].labelSize });
});

// ── Public stats (no auth needed) ──────────────────────────────────────────
// /api/stats already has no auth — it's used on page load before login.

// /api/public/orders — legacy alias of /api/orders. It is NO LONGER PUBLIC:
// it returned every order with customer name, phone, delivery address, waybill
// and client name to any unauthenticated caller (a PDPA/PII breach, and it was
// referenced by nothing in the front-end). Kept only as an authenticated alias
// so any old integration still works after adding a token.
app.get('/api/public/orders', requireAuth, (_req, res) => res.json(globalOrdersWithState()));

// Public: non-sensitive config (default recipient address only — no credentials)
app.get('/api/public/config', (_req, res) => {
  const conf = readEmailConfig();
  res.json({ default_email: conf.to_email || '' });
});

// ── Master endpoints (password-protected) ───────────────────────────────────
// The fallback is DELIBERATELY still here: making MASTER_KEY mandatory would
// take a running deployment down on the next restart if the env var isn't set
// yet. Instead we run, but say so loudly at boot and expose it on the health
// snapshot so it shows up as a warning banner in the Administrator UI until
// someone sets a real key in Railway. Once MASTER_KEY is set in production the
// fallback can be deleted safely.
const MASTER_KEY_IS_DEFAULT = !process.env.MASTER_KEY;
const MASTER_PASS = process.env.MASTER_KEY || '201432547E';
if (MASTER_KEY_IS_DEFAULT) {
  console.warn('[IdealOne] ⚠ SECURITY: MASTER_KEY is not set — falling back to the built-in default, which is present in the source. Set MASTER_KEY in the deployment environment.');
}

// The inventory store resolves its own DATA_DIR. If it ever disagrees with
// this file's, its SQLite database lands somewhere else — on Railway that
// meant inventory.db sat on the container's EPHEMERAL disk while db.json was
// on the volume, so bin locations and stock silently vanished on every
// redeploy while orders survived. Assert they match, loudly, at boot.
// NOTE: the actual check runs in assertInventoryPath(), called immediately
// after `inventory` is required further down this file — `const inventory`
// is in its temporal dead zone up here, so checking now would only ever
// throw and be swallowed, silently disabling the very warning that matters.
let INVENTORY_PATH_MISMATCH = null;
function assertInventoryPath() {
  try {
    const invDir = inventory.dataDir && inventory.dataDir();
    if (invDir && path.resolve(invDir) !== path.resolve(DATA_DIR)) {
      INVENTORY_PATH_MISMATCH = { server: path.resolve(DATA_DIR), inventory: path.resolve(invDir) };
      console.error('[IdealOne] ⚠ DATA LOSS RISK: the inventory store is writing to a DIFFERENT directory than the main database.');
      console.error(`[IdealOne]    main db  : ${INVENTORY_PATH_MISMATCH.server}`);
      console.error(`[IdealOne]    inventory: ${INVENTORY_PATH_MISMATCH.inventory}`);
      console.error('[IdealOne]    Inventory data (bin locations, stock) will NOT survive a restart. Set DATA_DIR explicitly.');
    } else {
      console.log(`[IdealOne] Inventory store path verified: ${path.resolve(invDir || DATA_DIR)}`);
    }
  } catch (e) { console.warn('[IdealOne] could not verify inventory store path:', e.message); }
}

// Verify an Administrator key WITHOUT the client having to know it in advance.
// The browser used to hold a hardcoded copy of the default key and compare
// locally, which meant (a) the key was readable by anyone who opened the page
// source, and (b) setting a real MASTER_KEY in the deployment BROKE the whole
// Administrator panel — the unlock prompt still only accepted the old built-in
// value, and every admin request kept sending it. Now the typed key is checked
// here and the client simply uses whatever the operator typed, so any
// MASTER_KEY works and no key ships in the bundle.
// Logged-in staff only (the global middleware already enforces that); admin
// role only, so a warehouse login can't sit and guess.
const _masterVerifyFails = new Map();   // userId -> {n, until}
app.post('/api/master/verify-key', express.json(), (req, res) => {
  // A request that already carries a valid master key is trivially verified.
  const viaHeader = req.headers['x-master-key'] === MASTER_PASS;
  if (!viaHeader) {
    const role = readUsers().find(u => u.id === req.userId)?.role || 'warehouse';
    if (role !== 'admin') return res.status(403).json({ error: 'Administrator role required' });
  }

  const gate = _masterVerifyFails.get(req.userId || 'anon');
  if (gate && gate.until > Date.now()) {
    return res.status(429).json({ error: `Too many attempts — try again in ${Math.ceil((gate.until - Date.now()) / 1000)}s` });
  }
  const key = String(req.body?.key || '');
  if (key && key === MASTER_PASS) {
    _masterVerifyFails.delete(req.userId || 'anon');
    logAudit('master_unlocked', { by: req.userId || 'master', ...clientInfo(req) });
    return res.json({ ok: true, isDefaultKey: MASTER_KEY_IS_DEFAULT });
  }
  const n = (gate?.n || 0) + 1;
  _masterVerifyFails.set(req.userId || 'anon', { n, until: n >= 5 ? Date.now() + 60_000 : 0 });
  logAudit('master_unlock_failed', { by: req.userId || 'master', attempt: n, ...clientInfo(req) });
  res.status(403).json({ ok: false, error: 'Incorrect Administrator key' });
});

function checkMaster(req, res) {
  if (req.headers['x-master-key'] !== MASTER_PASS) {
    res.status(403).json({ error: 'Forbidden' }); return false;
  }
  return true;
}

app.get('/api/master/inspect-descriptions', (req, res) => {
  if (!checkMaster(req, res)) return;
  const db = readDb();
  const results = [];
  for (const batch of (db.batches || []).slice(0, 3)) {
    for (const order of (batch.orders || []).slice(0, 5)) {
      for (const line of (order.lines || []).slice(0, 3)) {
        results.push({
          batch: batch.filename,
          order: order.order_number,
          sku: line.sku,
          description: line.description,
          desc_equals_sku: line.description === line.sku,
          desc_empty: !line.description,
        });
      }
    }
  }
  res.json(results);
});

app.get('/api/master/export-status', (req, res) => {
  if (!checkMaster(req, res)) return;
  const db   = readDb();
  const rows = [['Batch File','Uploaded By','Client','Uploaded At','Order No','Customer','Carrier','Waybill','Total Qty','Status','Scanned Qty','Start Time','End Time','Operator']];
  for (const batch of db.batches) {
    const states  = batch.orderStates || {};
    const dateStr = new Date(batch.uploaded_at).toLocaleString();
    for (const ord of (batch.orders || [])) {
      const state        = states[ord.order_number] || {};
      const scannedTotal = Object.values(state.scanned || {}).reduce((s, v) => s + v, 0);
      rows.push([
        batch.filename, batch.uploaded_by || '', batch.client_name || '', dateStr,
        ord.order_number, ord.customer_name || '', ord.carrier || '', ord.waybill_number || '',
        ord.total_qty || 0, state.status || 'pending', scannedTotal,
        state.startTime || '', state.endTime || '', state.operator || '',
      ]);
    }
  }
  const wb  = XLSX.utils.book_new();
  XLSX.utils.book_append_sheet(wb, XLSX.utils.aoa_to_sheet(rows), 'Status');
  const buf = XLSX.write(wb, { type: 'buffer', bookType: 'xlsx' });
  res.setHeader('Content-Type', 'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet');
  res.setHeader('Content-Disposition', `attachment; filename="IDEALONE_Status_${new Date().toISOString().slice(0,10)}.xlsx"`);
  res.end(buf);
});

// ── Live activity — Master dashboard ────────────────────────────────────────
// Aggregates the same orderStates data every scan endpoint already writes
// into a monitoring view: who is actively packing right now, which claimed
// orders went idle without being released (packer walked away / station
// died — the CLAIM_STALE_MS window already governs when this fires elsewhere),
// and recent scan throughput. Nothing new is persisted; this is a read-only
// projection recomputed on each request.
const LIVE_IDLE_WARN_MS = 5 * 60 * 1000; // flag an active packer as "idle" after 5 min with no scan

app.get('/api/master/live-activity', (req, res) => {
  if (!checkMaster(req, res)) return;
  const db      = readDb();
  const now     = Date.now();
  const nameFor = (() => {
    const byId = new Map(readUsers().map(u => [u.id, u.name || u.id]));
    return id => byId.get(id) || id || '(unknown)';
  })();

  const activePackers = [];
  const stuckOrders   = [];
  let scans5m = 0, scans15m = 0, scans1h = 0;

  for (const batch of db.batches || []) {
    const states = batch.orderStates || {};
    for (const ord of (batch.orders || [])) {
      const state = states[ord.order_number];
      if (!state) continue;
      const settled = state.status === 'done' || state.status === 'unprocessed';
      const scannedQty = Object.values(state.scanned || {}).reduce((s, v) => s + v, 0);
      const log = state.scanLog || [];
      const lastEvt = log.length ? log[log.length - 1] : null;

      for (let i = log.length - 1; i >= 0; i--) {
        const evt = log[i];
        if (evt.kind !== 'scan' && evt.kind !== 'teach' && evt.kind !== 'count') continue;
        const age = now - new Date(evt.at).getTime();
        if (age > 3600000) break; // scanLog is chronological — nothing older matters
        if (age <= 300000)  scans5m++;
        if (age <= 900000)  scans15m++;
        if (age <= 3600000) scans1h++;
      }

      const holder = claimHolder(state); // non-stale claim, per existing claiming logic
      if (holder && !settled) {
        const lastActivityAt = lastEvt ? new Date(lastEvt.at).getTime() : new Date(state.claimedAt || 0).getTime();
        activePackers.push({
          userId:        holder,
          userName:      nameFor(holder),
          orderNumber:   ord.order_number,
          client:        batch.client_name || '',
          scannedQty,
          totalQty:      ord.total_qty || 0,
          claimedAt:     state.claimedAt || null,
          idleMs:        now - lastActivityAt,
          idle:          (now - lastActivityAt) > LIVE_IDLE_WARN_MS,
        });
      } else if (state.claimedBy && !holder && !settled) {
        // Was claimed, claim is now stale (CLAIM_STALE_MS elapsed) — abandoned mid-pick
        stuckOrders.push({
          orderNumber:   ord.order_number,
          client:        batch.client_name || '',
          lastPacker:    state.claimedBy,
          lastPackerName: nameFor(state.claimedBy),
          scannedQty,
          totalQty:      ord.total_qty || 0,
          claimedAt:     state.claimedAt || null,
          idleMinutes:   Math.round((now - new Date(state.claimedAt || 0).getTime()) / 60000),
        });
      }
    }
  }

  activePackers.sort((a, b) => b.idleMs - a.idleMs);
  stuckOrders.sort((a, b) => b.idleMinutes - a.idleMinutes);

  res.json({
    generatedAt:   new Date().toISOString(),
    activePackers,
    stuckOrders,
    throughput:    { last5m: scans5m, last15m: scans15m, lastHour: scans1h },
  });
});

// ── Activity Overview / Station Throughput dashboards ───────────────────────
// Both read from db.auditLog's 'order_completed' events (via
// completionAuditData() at order-completion time) — the same deletion-proof,
// ≥12-month-retained source every other Administrator report already uses.
// Calendar days are bucketed in SGT (Asia/Singapore), matching sgDateStr()
// used everywhere else timezone-sensitive in this file (nightly backup, etc).
// Returns the 3 full calendar days immediately BEFORE today, oldest first —
// "today" is still in progress, so it's excluded rather than shown partial.
function previousSgDays(n) {
  const days = [];
  for (let i = n; i >= 1; i--) days.push(sgDateStr(new Date(Date.now() - i * 86400000)));
  return days;
}
function completedOrderEventsForDays(db, days) {
  const from = days[0], to = days[days.length - 1];
  const log  = readAuditLogForRange(db, from, to);
  const set  = new Set(days);
  return log
    .filter(e => e.type === 'order_completed')
    .map(e => ({ ...e, sgDay: sgDateStr(new Date(e.endTime || e.at)) }))
    .filter(e => set.has(e.sgDay));
}

app.get('/api/master/dashboard/activity-overview', (req, res) => {
  const isMaster = req.headers['x-master-key'] === MASTER_PASS;
  if (!isMaster) {
    const role = readUsers().find(u => u.id === req.userId)?.role || 'warehouse';
    if (role !== 'admin') return res.status(403).json({ error: 'This dashboard requires Administrator access' });
  }
  const db     = readDb();
  const days   = previousSgDays(3);
  const events = completedOrderEventsForDays(db, days);

  const byDay = new Map(days.map(d => [d, []]));
  for (const e of events) byDay.get(e.sgDay).push(e);

  const result = days.map(d => {
    const dayEvents  = byDay.get(d);
    const totalOrders = dayEvents.length;
    const totalLines  = dayEvents.reduce((s, e) => s + (e.lines || []).length, 0);
    let largestBySize = null, largestByLines = null;
    for (const e of dayEvents) {
      const size = e.pieces || 0;
      const lineCount = (e.lines || []).length;
      if (!largestBySize || size > largestBySize.value) largestBySize = { order: e.order, client: e.client || '', value: size, date: d };
      if (!largestByLines || lineCount > largestByLines.value) largestByLines = { order: e.order, client: e.client || '', value: lineCount, date: d };
    }
    return { date: d, totalOrders, totalLines, largestBySize, largestByLines };
  });
  res.json({ days: result });
});

app.get('/api/master/dashboard/station-throughput', (req, res) => {
  const isMaster = req.headers['x-master-key'] === MASTER_PASS;
  if (!isMaster) {
    const role = readUsers().find(u => u.id === req.userId)?.role || 'warehouse';
    if (role !== 'admin' && role !== 'warehouse') return res.status(403).json({ error: 'Forbidden' });
  }
  const db     = readDb();
  const days   = previousSgDays(3);
  const events = completedOrderEventsForDays(db, days);
  const byId   = new Map(readUsers().map(u => [u.id, u.name || u.id]));
  const nameFor = id => byId.get(id) || id || '(unassigned)';

  // "Station" = the packer/user who completed the order (operator on the
  // completion event) — this system has no separate physical-station ID;
  // one logged-in packer is the closest available proxy for one station.
  const totalsByDay = Object.fromEntries(days.map(d => [d, 0]));
  const stationsMap = new Map();
  for (const e of events) {
    totalsByDay[e.sgDay]++;
    const stationId = e.operator || '(unassigned)';
    if (!stationsMap.has(stationId)) {
      stationsMap.set(stationId, {
        station: stationId, stationName: nameFor(stationId),
        byDay: Object.fromEntries(days.map(d => [d, { orders: 0, lines: 0 }])),
      });
    }
    const s = stationsMap.get(stationId).byDay[e.sgDay];
    s.orders++;
    s.lines += (e.lines || []).length;
  }
  const stations = [...stationsMap.values()].sort((a, b) => a.stationName.localeCompare(b.stationName));
  res.json({ days, totalsByDay, stations });
});

// Full JSON backup — DB (batches, orders, scan states, users, sessions) plus
// the small config files. WMS XLSX / waybill PDF binaries are excluded: they
// are regenerable from the batch data and would bloat the download.
function buildBackupObject() {
  const readJson = f => { try { return JSON.parse(fs.readFileSync(f, 'utf8')); } catch { return null; } };
  return {
    kind:       'idealone-backup',
    version:    1,
    created_at: new Date().toISOString(),
    db:         readDb(),
    // The inventory store is a SEPARATE SQLite database. It was missing from
    // every backup until now, so bin locations and stock had no backup at
    // all — the thing this whole feature exists to prevent.
    inventory:  (() => { try { return inventory.exportAll(); } catch (e) { return { error: e.message }; } })(),
    config: {
      keyfields_template: readJson(KEYFIELDS_TEMPLATE_FILE),
      label_templates:    readJson(LABEL_TEMPLATES_FILE),
      sku_descriptions:   readJson(SKU_DESC_FILE),
      email:              readJson(EMAIL_CONFIG_FILE),
    },
  };
}

app.get('/api/master/backup', (req, res) => {
  if (!checkMaster(req, res)) return;
  try {
    const name = `idealone-backup-${new Date().toISOString().slice(0, 10)}.json`;
    res.setHeader('Content-Type', 'application/json');
    res.setHeader('Content-Disposition', `attachment; filename="${name}"`);
    res.send(JSON.stringify(buildBackupObject()));
  } catch (err) {
    res.status(500).json({ error: err.message });
  }
});

// Browse / download / restore the archived backups. Every nightly file stays
// on the volume; this is how an operator gets one onto their own machine.
app.get('/api/master/backups', (req, res) => {
  if (!checkMaster(req, res)) return;
  let files = [];
  try {
    files = fs.readdirSync(BACKUP_DIR)
      .filter(f => f.startsWith('idealone-backup-') || f.startsWith('idealscan-backup-'))
      .map(f => {
        const st = fs.statSync(path.join(BACKUP_DIR, f));
        const day = (f.match(/(\d{4}-\d{2}-\d{2})/) || [''])[0];
        return { file: f, day, bytes: st.size, modified: st.mtime.toISOString() };
      })
      .sort((a, b) => b.day.localeCompare(a.day));
  } catch { /* directory may not exist until the first backup runs */ }
  // flag which ones are the permanent month-end archives
  const byMonth = {};
  for (const f of [...files].sort((a, b) => a.day.localeCompare(b.day))) if (f.day) byMonth[f.day.slice(0, 7)] = f.file;
  const perm = new Set(Object.values(byMonth));
  res.json({
    dir: BACKUP_DIR,
    dailyKeep: BACKUP_DAILY_KEEP,
    files: files.map(f => ({ ...f, permanent: perm.has(f.file) })),
  });
});

app.get('/api/master/backups/:file', (req, res) => {
  if (!checkMaster(req, res)) return;
  const name = path.basename(String(req.params.file || ''));   // no traversal
  if (!/^ideal(one|scan)-backup-[\d-]+\.json\.gz$/.test(name)) return res.status(400).json({ error: 'Not a backup file' });
  const full = path.join(BACKUP_DIR, name);
  if (!fs.existsSync(full)) return res.status(404).json({ error: 'Backup not found' });
  res.setHeader('Content-Type', 'application/gzip');
  res.setHeader('Content-Disposition', `attachment; filename="${name}"`);
  fs.createReadStream(full).pipe(res);
});

// Restore the INVENTORY portion of a backup (bin locations, stock, lots,
// serials, bundles, suppliers, counts). Deliberately scoped to inventory:
// restoring orders/batches wholesale would clobber live scanning state, so
// that stays a manual, considered operation.
app.post('/api/master/backups/:file/restore-inventory', express.json(), (req, res) => {
  if (!checkMaster(req, res)) return;
  const name = path.basename(String(req.params.file || ''));
  if (!/^ideal(one|scan)-backup-[\d-]+\.json\.gz$/.test(name)) return res.status(400).json({ error: 'Not a backup file' });
  const full = path.join(BACKUP_DIR, name);
  if (!fs.existsSync(full)) return res.status(404).json({ error: 'Backup not found' });
  if (!inventory.available()) return res.status(503).json({ error: 'Inventory store unavailable' });
  const mode = req.body?.mode === 'replace' ? 'replace' : 'merge';
  try {
    const obj = JSON.parse(zlib.gunzipSync(fs.readFileSync(full)).toString());
    if (!obj.inventory || !obj.inventory.tables) {
      return res.status(400).json({ error: 'This backup predates inventory backups — it contains no inventory data.' });
    }
    const result = inventory.importAll(obj.inventory, { mode });
    logAudit('inventory_restored_from_backup', { file: name, mode, restored: result.restored, by: req.userId || 'master' });
    res.json({ ok: true, mode, ...result });
  } catch (e) { res.status(400).json({ error: e.message }); }
});

// Force today's archive backup now instead of waiting for the 02:00 SGT run —
// the thing to press before a risky change. Writes the same immutable
// per-day file the scheduler writes (so the scheduler then skips the night).
app.post('/api/master/backups/run-now', (req, res) => {
  if (!checkMaster(req, res)) return;
  runNightlyBackup('manual')
    .then(() => res.json({ ok: true, file: `idealone-backup-${sgDateStr()}.json.gz` }))
    .catch(e => res.status(500).json({ error: e.message }));
});

// ── Nightly automatic backup ─────────────────────────────────────────────────
// Every night (after 02:00 Singapore time) the full backup is gzipped to the
// volume (last 14 kept) and emailed to the configured recipient. The manual
// Download Backup button remains; this just removes the "remembering" part.
const BACKUP_DIR = path.join(DATA_DIR, 'backups');
// Keep this many recent DAILY backups; on top of that the last backup of
// every month is retained permanently (see runNightlyBackup).
const BACKUP_DAILY_KEEP = 30;
// Most mail servers cap attachments around 25 MB; stay well under it.
const BACKUP_EMAIL_MAX_BYTES = 15 * 1024 * 1024;
// PERF: toLocaleDateString/toLocaleString with a timeZone option builds a fresh
// Intl formatter on EVERY call (~0.18ms each). sgDateStr is the day-bucketing
// primitive for /api/stats, the /api/orders range filter, delivery history,
// audit-log report buckets and the daily jobs — so on a large live window it was
// costing >1.4s per 8k orders. Reusing one cached formatter is ~60x faster and
// produces byte-identical 'YYYY-MM-DD' output.
const _SG_DATE_FMT = new Intl.DateTimeFormat('en-CA', { timeZone: 'Asia/Singapore', year: 'numeric', month: '2-digit', day: '2-digit' });
const _SG_HOUR_FMT = new Intl.DateTimeFormat('en-GB', { timeZone: 'Asia/Singapore', hour: '2-digit', hour12: false });
function sgDateStr(d = new Date()) {
  return _SG_DATE_FMT.format(d); // YYYY-MM-DD
}
function sgHour(d = new Date()) {
  return parseInt(_SG_HOUR_FMT.format(d), 10);
}
async function runNightlyBackup(reason) {
  const day  = sgDateStr();
  const file = path.join(BACKUP_DIR, `idealone-backup-${day}.json.gz`);
  fs.mkdirSync(BACKUP_DIR, { recursive: true });
  const gz = zlib.gzipSync(Buffer.from(JSON.stringify(buildBackupObject())));
  fs.writeFileSync(file, gz);
  // RETENTION — daily backups are never overwritten (one immutable file per
  // day) and the MONTH-END one is kept forever, so history is not lost to a
  // rolling window. Only mid-month dailies older than the window are pruned.
  // Anything an operator has downloaded is theirs regardless.
  const backupDate = f => (f.match(/(\d{4}-\d{2}-\d{2})/) || [''])[0];
  const all = fs.readdirSync(BACKUP_DIR)
    .filter(f => f.startsWith('idealone-backup-') || f.startsWith('idealscan-backup-'))
    .sort((a, b) => backupDate(a).localeCompare(backupDate(b)));
  // the newest file in each month is that month's permanent archive
  const keepForever = new Set();
  const byMonth = {};
  for (const f of all) { const d = backupDate(f); if (d) byMonth[d.slice(0, 7)] = f; }
  Object.values(byMonth).forEach(f => keepForever.add(f));
  const recent = new Set(all.slice(-BACKUP_DAILY_KEEP));
  const old = all.filter(f => !keepForever.has(f) && !recent.has(f));
  for (const f of old) { try { fs.unlinkSync(path.join(BACKUP_DIR, f)); } catch {} }
  console.log(`[IdealOne] Nightly backup written (${reason}): ${file} (${(gz.length / 1024).toFixed(0)} KB)`
    + `; kept ${all.length - old.length} (${keepForever.size} permanent), pruned ${old.length}`);

  try {
    const transporter = buildTransporter();
    const to = getDefaultRecipient();
    if (transporter && to) {
      // Backups now include the whole inventory store (a real site is 10k+
      // bins), so the file can outgrow what a mail server will accept. Rather
      // than have the send fail — and take the notification down with it —
      // drop the attachment past the limit and point at the download page,
      // where the file is waiting either way.
      const tooBig = gz.length > BACKUP_EMAIL_MAX_BYTES;
      const when = new Date().toLocaleString('en-GB', { timeZone: 'Asia/Singapore' });
      await transporter.sendMail({
        from: getFromEmail(), to,
        subject: `IDEALONE nightly backup — ${day}${tooBig ? ' (on server, too large to email)' : ''}`,
        text: tooBig
          ? `The nightly backup for ${day} completed successfully (${(gz.length / 1048576).toFixed(1)} MB).\n\n`
            + `It is too large to email, so it was NOT attached. It is saved on the server and can be downloaded at any time:\n`
            + `  Administrator → System → Archived backups → Download\n\n`
            + `Nothing is lost — every day is kept as its own file and month-end backups are kept permanently.\n`
            + `Generated ${when} SGT.`
          : `Automatic nightly backup attached — includes warehouse locations and all inventory.\n\n`
            + `More copies: Administrator → System → Archived backups.\n`
            + `Generated ${when} SGT.`,
        attachments: tooBig ? [] : [{ filename: `idealone-backup-${day}.json.gz`, content: gz }],
      });
      console.log(`[IdealOne] Nightly backup ${tooBig ? 'notification (attachment too large)' : 'emailed'} to ${to}`);
    } else {
      console.log('[IdealOne] Nightly backup email skipped — email not configured');
    }
  } catch (e) {
    console.error('[IdealOne] Nightly backup email FAILED:', e.message);
  }
}
function nightlyBackupDue() {
  const day = sgDateStr();
  if (sgHour() < 2) return false; // wait for the quiet window after 2am SGT
  try { return !fs.existsSync(path.join(BACKUP_DIR, `idealone-backup-${day}.json.gz`)); }
  catch { return true; }
}
setInterval(() => {
  if (nightlyBackupDue()) runNightlyBackup('scheduled').catch(e => console.error('[IdealOne] nightly backup failed:', e.message));
}, 30 * 60 * 1000);
// also check shortly after boot — covers redeploys that skip the 2am window
setTimeout(() => {
  if (nightlyBackupDue()) runNightlyBackup('startup catch-up').catch(e => console.error('[IdealOne] nightly backup failed:', e.message));
}, 2 * 60 * 1000);

app.post('/api/master/reset', (req, res) => {
  if (!checkMaster(req, res)) return;
  try {
    // Keep users — the UI promises "Users and email settings are preserved",
    // but users live inside db.json now, so a bare reset would wipe them.
    // The audit ledger ALSO survives reset (deletion-proof reports) and the
    // reset itself is recorded.
    const prev = readDb();
    writeDb({
      batches: [],
      users: prev.users || [],
      noBarcodeSkus: prev.noBarcodeSkus || {},
      auditBackfilled: true,
      auditLog: [
        ...(prev.auditLog || []),
        { type: 'master_reset', at: new Date().toISOString(), by: req.userId || 'master', batchesDeleted: (prev.batches || []).length },
      ],
    });
    activeSessions.clear();
    for (const f of fs.readdirSync(WMS_DIR))
      try { fs.unlinkSync(path.join(WMS_DIR, f)); } catch {}
    for (const d of fs.readdirSync(WAYBILL_DIR)) {
      const dp = path.join(WAYBILL_DIR, d);
      try { fs.rmSync(dp, { recursive: true, force: true }); } catch {}
    }
    res.json({ ok: true });
  } catch (err) {
    res.status(500).json({ error: err.message });
  }
});

// ── Master: delete batch / delete single order ───────────────────────────────

// ── Standard reports — built from the audit ledger, deletion-proof ──────────
// GET /api/master/report/:kind?from=YYYY-MM-DD&to=YYYY-MM-DD  (manifest: ?date=)
//
// Access split:
//   • Operational reports → any ADMIN login (daily-summary, productivity,
//     carrier-manifest, aging, lot-traceability). Warehouse role: none.
//   • Commercial/oversight reports → MASTER key only (client-activity =
//     billing data; exceptions = includes the deletion audit that watches
//     the admins themselves).
const ADMIN_REPORT_KINDS = new Set(['daily-summary', 'productivity', 'carrier-manifest', 'aging', 'lot-traceability', 'order-size', 'inbound', 'drivers', 'outbound-stock', 'fulfilment']);

app.get('/api/master/report/:kind', (req, res) => {
  const { kind } = req.params;
  const isMaster = req.headers['x-master-key'] === MASTER_PASS;
  if (!isMaster) {
    const role = readUsers().find(u => u.id === req.userId)?.role || 'warehouse';
    if (role !== 'admin' || !ADMIN_REPORT_KINDS.has(kind)) {
      return res.status(403).json({ error: 'This report requires Administrator access' });
    }
  }
  try {
    const db  = readDb();

    const today = sgDateStr();
    const from  = (req.query.from || '').slice(0, 10) || sgDateStr(new Date(Date.now() - 30 * 86400000));
    const to    = (req.query.to   || '').slice(0, 10) || today;
    // Transparently pulls in archived months when the range reaches past
    // what's still live in db.auditLog — reports can filter back at least
    // 6 months regardless of how long ago the data actually happened.
    const log   = readAuditLogForRange(db, from, to);
    const day   = at => at ? sgDateStr(new Date(at)) : ''; // SGT calendar day
    const inRange = ev => day(ev.at) >= from && day(ev.at) <= to;
    const mins  = ev => (ev.startTime && ev.endTime) ? Math.round((new Date(ev.endTime) - new Date(ev.startTime)) / 6000) / 10 : null;
    const avg   = a => a.length ? Math.round(a.reduce((s, v) => s + v, 0) / a.length * 10) / 10 : '';
    const hhmm  = at => at ? new Date(at).toLocaleTimeString('en-SG', { hour12: false }) : '';
    const byUserId = new Map(readUsers().map(u => [u.id, u.name || u.id]));
    const nameFor  = id => byUserId.get(id) || id || '—';

    const uploads   = log.filter(e => e.type === 'upload' && inRange(e));
    const completed = log.filter(e => e.type === 'order_completed' && inRange(e));
    const cancelled = log.filter(e => e.type === 'order_cancelled' && inRange(e));
    const deletions = log.filter(e => ['batch_deleted', 'order_deleted', 'order_deletion_rejected', 'master_reset'].includes(e.type) && inRange(e));

    const wb = XLSX.utils.book_new();
    const addSheet = (name, aoa) => XLSX.utils.book_append_sheet(wb, XLSX.utils.aoa_to_sheet(aoa), name);
    let title = kind;

    if (kind === 'daily-summary') {
      title = 'Daily_Operations_Summary';
      const days = {};
      const D = d => days[d] ||= { batches: 0, ordUp: 0, lines: 0, done: 0, pieces: 0, durs: [] };
      for (const e of uploads)   { const x = D(day(e.at)); x.batches++; x.ordUp += e.orders || 0; x.lines += e.lines || 0; }
      for (const e of completed) { const x = D(day(e.at)); x.done++; x.pieces += e.pieces || 0; const m = mins(e); if (m !== null) x.durs.push(m); }
      addSheet('Daily', [
        ['Date', 'Batches Uploaded', 'Orders Uploaded', 'Lines Uploaded', 'Orders Completed', 'Pieces Scanned', 'Avg Mins / Order'],
        ...Object.keys(days).sort().map(d => { const x = days[d]; return [d, x.batches, x.ordUp, x.lines, x.done, x.pieces, avg(x.durs)]; }),
      ]);
      const dc = {};
      for (const e of completed) { const k = day(e.at) + '|' + (e.client || '—'); dc[k] ||= { done: 0, pieces: 0 }; dc[k].done++; dc[k].pieces += e.pieces || 0; }
      addSheet('By Client', [
        ['Date', 'Client', 'Orders Completed', 'Pieces Scanned'],
        ...Object.keys(dc).sort().map(k => { const [d, c] = k.split('|'); return [d, c, dc[k].done, dc[k].pieces]; }),
      ]);

    } else if (kind === 'productivity') {
      title = 'Packer_Productivity';
      const g = {};
      for (const e of completed) {
        const k = day(e.at) + '|' + (e.operator || '—');
        g[k] ||= { done: 0, pieces: 0, durs: [] };
        g[k].done++; g[k].pieces += e.pieces || 0;
        const m = mins(e); if (m !== null) g[k].durs.push(m);
      }
      addSheet('Productivity', [
        ['Date', 'Operator', 'Orders Completed', 'Pieces Scanned', 'Avg Mins / Order', 'Fastest (mins)', 'Slowest (mins)'],
        ...Object.keys(g).sort().map(k => {
          const [d, op] = k.split('|'); const x = g[k];
          return [d, op, x.done, x.pieces, avg(x.durs), x.durs.length ? Math.min(...x.durs) : '', x.durs.length ? Math.max(...x.durs) : ''];
        }),
      ]);

    } else if (kind === 'client-activity') {
      title = 'Client_Activity';
      const g = {};
      const G = c => g[c || '—'] ||= { batches: 0, ordUp: 0, lines: 0, done: 0, pieces: 0 };
      for (const e of uploads)   { const x = G(e.client); x.batches++; x.ordUp += e.orders || 0; x.lines += e.lines || 0; }
      for (const e of completed) { const x = G(e.client); x.done++; x.pieces += e.pieces || 0; }
      addSheet('Client Activity', [
        [`Period: ${from} to ${to}`],
        ['Client', 'Batches Uploaded', 'Orders Uploaded', 'Lines Uploaded', 'Orders Completed', 'Pieces Scanned'],
        ...Object.keys(g).sort().map(c => { const x = g[c]; return [c, x.batches, x.ordUp, x.lines, x.done, x.pieces]; }),
      ]);

    } else if (kind === 'exceptions') {
      title = 'Exceptions_Discrepancies';
      const rows = [];
      for (const e of cancelled) {
        if ((e.mismatches || []).length) {
          for (const m of e.mismatches) rows.push([e.at, 'Cancelled - mismatch', e.order, e.client, e.operator, m.sku, m.ordered, m.scanned, m.gap, '']);
        } else {
          rows.push([e.at, 'Cancelled', e.order, e.client, e.operator, '', '', '', '', '']);
        }
      }
      for (const e of deletions) {
        if (e.type === 'batch_deleted') rows.push([e.at, 'BATCH DELETED', '', e.client, e.by, '', '', '', '', `${e.filename} (${e.orders} orders): ${(e.orderNumbers || []).slice(0, 20).join(', ')}${(e.orderNumbers || []).length > 20 ? '…' : ''}`]);
        else if (e.type === 'order_deleted') rows.push([e.at, 'ORDER DELETED', e.order, e.client, e.by, '', '', '', '', e.requestedBy ? `${e.reason || ''} (requested by ${e.requestedBy}, approved by ${e.by})` : (e.reason || '')]);
        else if (e.type === 'order_deletion_rejected') rows.push([e.at, 'DELETION REJECTED', e.order, e.client, e.by, '', '', '', '', `Requested by ${e.requestedBy}: "${e.reason || ''}"${e.note ? ` — Master note: ${e.note}` : ''}`]);
        else rows.push([e.at, 'MASTER RESET', '', '', e.by, '', '', '', '', `${e.batchesDeleted} batches wiped`]);
      }
      rows.sort((a, b) => String(a[0]).localeCompare(String(b[0])));
      addSheet('Exceptions', [
        ['Date/Time', 'Type', 'Order', 'Client', 'Operator/By', 'SKU', 'Ordered', 'Scanned', 'Gap', 'Note'],
        ...rows,
      ]);

    } else if (kind === 'carrier-manifest') {
      title = 'Carrier_Manifest';
      const date = (req.query.date || today).slice(0, 10);
      const evs  = log.filter(e => e.type === 'order_completed' && day(e.at) === date)
                      .sort((a, b) => (a.carrier || '').localeCompare(b.carrier || '') || String(a.at).localeCompare(String(b.at)));
      addSheet('Manifest', [
        [`Carrier Handover Manifest — ${date}`],
        ['Carrier', 'Order No', 'Waybill', 'Customer', 'Pieces', 'Completed At', 'Packed By', 'Received By (sign)'],
        ...evs.map(e => [e.carrier || '—', e.order, e.waybill || '', e.customer || '', e.pieces || '', hhmm(e.endTime || e.at), e.operator || '', '']),
      ]);

    } else if (kind === 'aging') {
      title = 'Order_Aging_Backlog';
      const rows = [];
      for (const b of db.batches || []) {
        const states = b.orderStates || {};
        for (const o of b.orders || []) {
          const st = states[o.order_number] || { status: 'pending' };
          if (st.status === 'done') continue;
          const daysOld = Math.floor((Date.now() - new Date(b.uploaded_at)) / 86400000);
          rows.push([o.order_number, b.client_name || '', o.carrier || '', st.status || 'pending', day(b.uploaded_at), daysOld, (o.lines || []).length, (o.lines || []).reduce((s, l) => s + (l.qty || 0), 0)]);
        }
      }
      rows.sort((a, b) => b[5] - a[5]);
      addSheet('Aging', [
        ['Order No', 'Client', 'Carrier', 'Status', 'Uploaded', 'Days Pending', 'Lines', 'Pieces Ordered'],
        ...rows,
      ]);

    } else if (kind === 'outbound-stock') {
      // WHAT THE STOCK ACTUALLY DID, per order. Reserved at intake, released if
      // the order was cancelled, depleted when it shipped — read from
      // stock_movements, which is the ledger those three write to.
      title = 'Outbound_Stock_Movements';
      const LABEL = { reserve: 'Reserved', release: 'Released (cancelled)', outbound: 'Depleted (shipped)' };
      const clients = [...new Set((db.batches || []).map(b => b.client_name).filter(Boolean))];
      const rows = [];
      for (const cn of clients) {
        const cid = invClientId(cn);
        let mv = [];
        // Do NOT swallow this silently — an empty report that should have rows
        // is indistinguishable from a quiet month.
        try { mv = inventory.outboundMovements(cid, { from, to }); }
        catch (e) { console.warn('[report/outbound-stock]', cn, e.message); }
        for (const m of mv) {
          rows.push([m.at, cn, m.order_id || '', m.sku, m.product || '',
            LABEL[m.type] || m.type, Math.abs(Number(m.qty) || 0), m.operator || '', m.reason || '']);
        }
      }
      rows.sort((a, b) => String(b[0]).localeCompare(String(a[0])));
      addSheet('Outbound Stock', [
        ['When', 'Client', 'Order No', 'SKU', 'Product', 'What happened', 'Units', 'By', 'Note'],
        ...rows,
      ]);
      // One line per order so the shape is readable without reading every move.
      const byOrder = new Map();
      for (const r of rows) {
        const k = `${r[1]}|${r[2]}`;
        const e = byOrder.get(k) || { client: r[1], order: r[2], reserved: 0, released: 0, shipped: 0, last: r[0] };
        if (/^Reserved/.test(r[5])) e.reserved += r[6];
        else if (/^Released/.test(r[5])) e.released += r[6];
        else e.shipped += r[6];
        if (String(r[0]) > String(e.last)) e.last = r[0];
        byOrder.set(k, e);
      }
      addSheet('By Order', [
        ['Client', 'Order No', 'Units reserved', 'Units released', 'Units shipped', 'Still reserved', 'Last movement'],
        ...[...byOrder.values()].map(e => [e.client, e.order, e.reserved, e.released, e.shipped,
          Math.max(0, e.reserved - e.released - e.shipped), e.last]),
      ]);

    } else if (kind === 'fulfilment') {
      // DID WE HAND IT OVER WHEN WE SAID WE WOULD? Read from live orders, not
      // from the audit log, because the promise is DERIVED from the current
      // policy — a report built from stamped values would go stale the moment
      // a cut-off changed. `from`/`to` slice on the day the order reached us.
      title = 'Fulfilment_KPI';
      const fpol = fulfilmentPolicy(db), ppol = pickupPolicy(db), nowIso = new Date().toISOString();
      const fmtSgt = t => (t ? new Date(t).toLocaleString('en-GB', { timeZone: 'Asia/Singapore', hour12: false }) : '');
      const rows = [];
      for (const b of db.batches || []) {
        const day = sgDateStr(new Date(b.uploaded_at));
        if ((from && day < from) || (to && day > to)) continue;
        for (const o of b.orders || []) {
          const st = (b.orderStates || {})[o.order_number] || {};
          if (isClientCancelled(st)) continue;
          const f = fulfilmentSla({
            uploadedAt: b.uploaded_at, platform: o.platform || '',
            waybill_number: o.waybill_number || '',
            scan_status: st.status || 'pending', endTime: st.endTime || null,
            picked_up_at: st.pickup?.at || null,
          }, fpol, ppol, nowIso);
          if (!f) continue;
          const VERDICT = { met: 'Met', missed: 'Missed', overdue: 'OVERDUE — still here',
            critical: 'Critical', 'due-soon': 'Due soon', ontime: 'On time', cancelled: 'Cancelled',
            unknown: 'No handover date' };
          rows.push([
            b.client_name || '', o.order_number, o.platform || '',
            fmtSgt(b.uploaded_at), f.receivedHhmm, f.band,
            f.commitment === 'target' ? 'Target' : 'Committed',
            f.dueDay, ppol.cutoff,
            st.status === 'done' ? fmtSgt(st.endTime) : '',
            f.handoverDay || '', VERDICT[f.status] || f.status,
            f.closed ? '' : (f.minutesLeft === null ? '' : f.minutesLeft),
            f.daysLate || 0,
          ]);
        }
      }
      rows.sort((a, c) => String(a[3]).localeCompare(String(c[3])));
      addSheet('Fulfilment', [
        ['Client', 'Order No', 'Channel', 'Received (SGT)', 'Received at', 'Band', 'Commitment',
         'Due day', 'Handover by', 'Completed (SGT)', 'Left on', 'Verdict', 'Minutes left', 'Days late'],
        ...rows,
      ]);
      // The headline. Committed work is what the promise is measured on; the
      // target band is reported separately rather than folded in, because
      // scoring a "where we can" against a hard promise would flatter or
      // damn us for the wrong reason.
      const tally = (pred) => {
        const set = rows.filter(pred);
        const met = set.filter(r => r[11] === 'Met').length;
        const missed = set.filter(r => r[11] === 'Missed').length;
        const closed = met + missed;
        return [set.length, met, missed, closed ? `${Math.round(met / closed * 100)}%` : 'n/a'];
      };
      addSheet('Summary', [
        ['Fulfilment KPI', '', '', ''],
        [`Handover cut-off: ${ppol.cutoff} SGT`, '', '', ''],
        [], ['Group', 'Orders', 'Met', 'Missed', 'On-time %'],
        ['Committed', ...tally(r => r[6] === 'Committed')],
        ['Target (same day where we can)', ...tally(r => r[6] === 'Target')],
        ['All', ...tally(() => true)],
        [],
        ['Still open', rows.filter(r => ['On time', 'Due soon', 'Critical', 'OVERDUE — still here'].includes(r[11])).length, '', '', ''],
        ['…of which overdue', rows.filter(r => r[11] === 'OVERDUE — still here').length, '', '', ''],
        [],
        ['NOTE — an order counts as fulfilled on the day it physically LEAVES,'],
        ['not the moment scanning finished. Work completed after the handover'],
        ['cut-off leaves on the next collecting day, and is judged on that day.'],
        ['Bands and thresholds are the CURRENT policy: this report is derived,'],
        ['so changing a cut-off re-scores history honestly rather than leaving'],
        ['stale targets behind.'],
      ]);
      // Where the misses are.
      const byCh = new Map();
      for (const r of rows) {
        const k = r[2] || '(not a marketplace order)';
        const e = byCh.get(k) || { ch: k, n: 0, met: 0, missed: 0, open: 0, overdue: 0 };
        e.n++;
        if (r[11] === 'Met') e.met++;
        else if (r[11] === 'Missed') e.missed++;
        else if (r[11] === 'Cancelled') { /* carries no promise */ }
        else { e.open++; if (r[11] === 'OVERDUE — still here') e.overdue++; }
        byCh.set(k, e);
      }
      addSheet('By Channel', [
        ['Channel', 'Orders', 'Met', 'Missed', 'On-time %', 'Still open', 'Overdue'],
        ...[...byCh.values()].sort((a, c) => c.n - a.n).map(e => [
          e.ch, e.n, e.met, e.missed,
          (e.met + e.missed) ? `${Math.round(e.met / (e.met + e.missed) * 100)}%` : 'n/a',
          e.open, e.overdue,
        ]),
      ]);

    } else if (kind === 'login-audit') {
      title = 'User_Login_Audit';
      const evs = log.filter(e => ['login', 'login_failed', 'logout'].includes(e.type) && inRange(e));
      const label = { login: 'Login', login_failed: 'FAILED LOGIN', logout: 'Logout' };
      addSheet('Login Audit', [
        ['Date/Time', 'User', 'Event', 'IP Address', 'Device', 'Note'],
        ...evs.map(e => [e.at, e.user || '—', label[e.type], e.ip || '', e.device || '',
                         e.replacedSession ? 'Signed in elsewhere — previous session ended' : '']),
      ]);
      // Per-user summary: first/last activity and counts
      const byUser = {};
      for (const e of evs) {
        const u = byUser[e.user || '—'] ||= { logins: 0, failed: 0, logouts: 0, first: e.at, last: e.at };
        if (e.type === 'login') u.logins++; else if (e.type === 'login_failed') u.failed++; else u.logouts++;
        if (e.at < u.first) u.first = e.at;
        if (e.at > u.last)  u.last  = e.at;
      }
      addSheet('Per User', [
        ['User', 'Logins', 'Failed Attempts', 'Logouts', 'First Activity', 'Last Activity'],
        ...Object.keys(byUser).sort().map(u => { const x = byUser[u]; return [u, x.logins, x.failed, x.logouts, x.first, x.last]; }),
      ]);

    } else if (kind === 'lot-traceability') {
      title = 'Lot_Expiry_Traceability';
      const rows = [];
      for (const e of completed) {
        for (const l of e.lines || []) {
          if (!l.lot && !l.expiry) continue;
          rows.push([day(e.at), e.order, e.client, l.sku, l.description, l.lot, l.expiry, l.scanned ?? l.qty, e.operator, e.waybill || '']);
        }
      }
      addSheet('Traceability', [
        ['Date', 'Order No', 'Client', 'SKU', 'Description', 'Lot / Batch', 'Expiry', 'Qty Shipped', 'Packed By', 'Waybill'],
        ...rows,
      ]);

    } else if (kind === 'order-size') {
      title = 'Order_Size_Analysis';
      const SIZE_BUCKETS = [
        { label: 'Small (1-5 pcs)',   test: p => p <= 5 },
        { label: 'Medium (6-20 pcs)', test: p => p > 5 && p <= 20 },
        { label: 'Large (21+ pcs)',   test: p => p > 20 },
      ];
      const orderRows = completed.map(e => [
        e.order, e.client || '', e.customer || '', e.pieces || 0, (e.lines || []).length, day(e.at), e.operator || '',
      ]);

      const bySize = SIZE_BUCKETS.map(b => {
        const matched = orderRows.filter(r => b.test(r[3]));
        return [b.label, matched.length, matched.reduce((s, r) => s + r[3], 0)];
      });
      addSheet('Size Summary', [
        ['Size Bucket', 'Orders', 'Total Pieces'],
        ...bySize,
        ['All orders', orderRows.length, orderRows.reduce((s, r) => s + r[3], 0)],
      ]);

      addSheet('By Pieces', [
        ['Order No', 'Client', 'Customer', 'Pieces', 'Line Items', 'Completed', 'Operator'],
        ...[...orderRows].sort((a, b) => b[3] - a[3]),
      ]);

      addSheet('By Line Items', [
        ['Order No', 'Client', 'Customer', 'Pieces', 'Line Items', 'Completed', 'Operator'],
        ...[...orderRows].sort((a, b) => b[4] - a[4]),
      ]);

    } else if (kind === 'inbound') {
      title = 'Inbound_Receiving';
      // Live data straight from db.inbound — same pattern as 'aging' above —
      // since inbound jobs aren't audit-log-derived the way order completion is.
      const jobs = (db.inbound || []).filter(rec => {
        const d = day(rec.uploaded_at);
        return d >= from && d <= to;
      });

      addSheet('Inbound Jobs', [
        ['Serial', 'Type', 'Reference', 'Source', 'Client', 'Uploaded', 'Uploaded By', 'Status', 'Expected Qty', 'Scanned Qty', 'Cartons'],
        ...jobs.map(rec => {
          const state = rec.state || {};
          const expected = (rec.lines || []).reduce((s, l) => s + (l.expected_qty || 0), 0);
          const scanned  = Object.values(state.scanned || {}).reduce((s, q) => s + q, 0);
          return [
            rec.serial || '', rec.type === 'po' ? 'PO / ASN' : 'Return', rec.reference || '',
            rec.source_name || '', rec.client_name || '', day(rec.uploaded_at), nameFor(rec.uploaded_by),
            state.status || 'pending', rec.type === 'po' ? expected : '', scanned,
            (state.cartons || []).length || 1,
          ];
        }),
      ]);

      const lineRows = [];
      for (const rec of jobs) {
        const state = rec.state || {};
        const scanned = state.scanned || {};
        const bySku = new Map((rec.lines || []).map(l => [l.sku, l]));
        const skus = new Set([...bySku.keys(), ...Object.keys(scanned)]);
        for (const sku of skus) {
          const line = bySku.get(sku);
          const qty  = scanned[sku] || 0;
          const cond = (state.conditionTotals || {})[sku] || {};
          lineRows.push([
            rec.serial || '', rec.reference || '', sku, line?.description || '',
            rec.type === 'po' ? (line?.expected_qty || 0) : '', qty,
            cond.straight_to_inventory || '', cond.damaged || '', cond.kiv || '',
          ]);
        }
      }
      addSheet('Inbound Lines', [
        ['Serial', 'Reference', 'SKU', 'Description', 'Expected Qty', 'Scanned Qty', 'Straight to Inventory', 'Damaged', 'KIV'],
        ...lineRows,
      ]);

    } else if (kind === 'drivers') {
      title = 'Driver_Performance';
      const { drivers, summary } = computeDriverPerformance(db, from, to);

      addSheet('Driver Summary', [
        ['Driver', 'Jobs Assigned', 'Delivered', 'Confirmed (awaiting delivery)', 'Preplanned (open)', 'Total Cartons', 'Est. Distance (km)', 'Days Active', 'Avg Jobs / Day'],
        ...summary.map(s => [s.name, s.jobsAssigned, s.delivered, s.confirmed, s.open, s.cartons, s.km, s.daysActive, s.avgJobsPerDay]),
      ]);

      addSheet('Driver Jobs', [
        ['Driver', 'Date', 'Job ID', 'Client', 'Postal', 'Cartons', 'Route', 'Stop #', 'Status', 'Planned At', 'Delivered At'],
        ...Object.keys(drivers).sort().flatMap(name =>
          drivers[name].jobs
            .sort((a, b) => day(a.deliveredAt || a.plannedAt || a.createdAt).localeCompare(day(b.deliveredAt || b.plannedAt || b.createdAt)) ||
                            (a.routeNum || 99) - (b.routeNum || 99) || (a.stopSeq || 99) - (b.stopSeq || 99))
            .map(j => [
              name, day(j.deliveredAt || j.plannedAt || j.createdAt), j.id, j.clientName || '',
              j.shipping?.zip || '', j.packages || 1, j.routeNum || '', j.stopSeq || '',
              j.status || 'pending', hhmm(j.plannedAt), hhmm(j.deliveredAt),
            ])),
      ]);

      addSheet('Notes', [
        ['About this report'],
        ['Distances are ESTIMATES based on Singapore postal-district centroids (the same basis route planning uses), starting each day from the Marina depot reference. They are suitable for comparing drivers and days, not for odometer/fuel claims.'],
        ['A job counts toward the day it was delivered; undelivered jobs count toward the day they were planned (or created).'],
      ]);

    } else {
      return res.status(400).json({ error: `Unknown report kind: ${kind}` });
    }

    const buf = XLSX.write(wb, { type: 'buffer', bookType: 'xlsx' });
    res.setHeader('Content-Type', 'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet');
    res.setHeader('Content-Disposition', `attachment; filename="${title}_${from}_to_${to}.xlsx"`);
    res.send(buf);
  } catch (err) {
    console.error('[report]', err.message);
    res.status(500).json({ error: err.message });
  }
});

app.delete('/api/master/batch/:batchId', (req, res) => {
  if (!checkMaster(req, res)) return;
  const { batchId } = req.params;
  try {
    const db  = readDb();
    const idx = db.batches.findIndex(b => b.id === batchId);
    if (idx === -1) return res.status(404).json({ error: 'Batch not found' });
    const victim = db.batches[idx];
    const doneOrders = (victim.orders || [])
      .filter(o => (victim.orderStates?.[o.order_number]?.status) === 'done')
      .map(o => o.order_number);
    if (doneOrders.length > 0) {
      return res.status(403).json({
        error: `This batch has ${doneOrders.length} completed order(s) and cannot be deleted. Completed work is never overwritten or removed by a batch delete — use the per-order deletion request workflow for individual orders if needed.`,
        doneOrders: doneOrders.slice(0, 500),
      });
    }
    db.batches.splice(idx, 1);
    pruneOrphanBackorders(db);          // every order in it took its backorders too
    releaseOrphanReservations(db);      // …and gave back what it had reserved
    pruneOrphanTransportJobs(db);       // and their deliveries
    writeDb(db);
    logAudit('batch_deleted', {
      batchId, filename: victim.filename || '', client: victim.client_name || '',
      orders: (victim.orders || []).length, by: req.userId || 'master',
      orderNumbers: (victim.orders || []).map(o => o.order_number).slice(0, 500),
    });
    try { fs.unlinkSync(path.join(WMS_DIR, `${batchId}.xlsx`)); } catch {}
    try { fs.rmSync(path.join(WAYBILL_DIR, batchId), { recursive: true, force: true }); } catch {}
    invalidateWaybillCache(batchId);
    res.json({ ok: true });
  } catch (err) {
    res.status(500).json({ error: err.message });
  }
});

// Removes an order from a batch (splice + orderStates cleanup + waybill PDF).
// Shared by the direct master delete and the deletion-request approval path.
function removeOrderFromBatch(batch, orderNumber) {
  const before  = (batch.orders || []).length;
  batch.orders  = (batch.orders || []).filter(o => o.order_number !== orderNumber);
  if (batch.orders.length === before) return false;
  batch.order_count = batch.orders.length;
  if (batch.orderStates) delete batch.orderStates[orderNumber];
  try { fs.unlinkSync(path.join(WAYBILL_DIR, batch.id, `${orderNumber}.pdf`)); } catch {}
  return true;
}

app.delete('/api/master/order/:batchId/:orderNumber', (req, res) => {
  if (!checkMaster(req, res)) return;
  const { batchId, orderNumber } = req.params;
  const reason = String(req.body?.reason || '').trim();
  if (!reason) return res.status(400).json({ error: 'A reason is required to delete an order.' });
  try {
    const db    = readDb();
    const batch = db.batches.find(b => b.id === batchId);
    if (!batch) return res.status(404).json({ error: 'Batch not found' });
    const state = (batch.orderStates || {})[orderNumber];
    if (state && state.status === 'done') {
      return res.status(403).json({ error: 'This order is completed and can no longer be deleted.' });
    }
    if (!removeOrderFromBatch(batch, orderNumber)) return res.status(404).json({ error: 'Order not found in batch' });
    pruneOrphanBackorders(db);          // the order's backorders go with it
    releaseOrphanReservations(db);      // …and its reservation is given back
    pruneOrphanTransportJobs(db);       // and its delivery
    writeDb(db);
    logAudit('order_deleted', { order: orderNumber, batchId, client: batch.client_name || '', by: req.userId || 'master', reason });
    res.json({ ok: true });
  } catch (err) {
    res.status(500).json({ error: err.message });
  }
});

// ── Order deletion requests — Admin requests, Master confirms ───────────────
// Admin-role users don't hold the master key, so they can no longer delete
// an order outright. They request deletion (re-entering their OWN account
// password as a confirmation step); the order is flagged pending_deletion
// (visible to everyone as a status) until Master reviews it from the
// Administrator "Pending Deletions" tab and approves or rejects it.
// Shared re-confirmation for destructive admin actions: the signed-in admin
// re-enters THEIR OWN login password. The Administrator key is also accepted —
// it proves at least as much authority, and "password" in these dialogs was
// genuinely ambiguous to admins who think of that key as *the* password, which
// produced a wall of "Incorrect password" with no way to tell which secret was
// wanted. Returns a 403-shaped error string, never 401: the session token is
// still valid, and a 401 would trip the client's global "session expired"
// handler and force-reload the page mid-dialog.
function verifyAdminReconfirm(req, { role = 'admin' } = {}) {
  const user = readUsers().find(u => u.id === req.userId);
  if (!user) return { error: 'Session user not found.', code: 401 };
  if (role && (user.role || 'admin') !== role) {
    return { error: `Only ${role === 'admin' ? 'Admin' : role} users can do this.`, code: 403 };
  }
  const pw = String(req.body?.password || '');
  if (!pw) return { error: 'Enter your password to confirm.', code: 403 };
  if (pw === MASTER_PASS) return { user, viaMaster: true };
  if (hashPass(pw, user.salt) === user.passwordHash) return { user, viaMaster: false };
  return {
    error: `That password does not match. Enter the password you use to sign in as "${user.id}" (or the Administrator key).`,
    code: 403,
  };
}

// ── COLLECTION QUEUE — closing off orders that have left the building ───────
// Everything that is DONE but not yet picked up, grouped by the day it is due
// to be collected. This is the screen someone works down as the courier loads.
app.get('/api/orders/pickup-queue', (req, res) => {
  const db = readDb();
  const policy = pickupPolicy(db);
  // Self-drop days settle themselves, so bring those up to date before
  // reporting — otherwise Saturday's work would sit in the queue asking to be
  // closed by hand every Monday morning.
  if (applyAutoPickups(db)) writeDb(db);

  const today = sgDateStr();
  const rows = [];
  let pickedToday = 0;
  for (const batch of db.batches || []) {
    for (const ord of batch.orders || []) {
      const state = (batch.orderStates || {})[ord.order_number];
      if (!state || state.status !== 'done') continue;
      if (state.pickup) {
        if (sgParts(state.pickup.at)?.day === today) pickedToday++;
        continue;
      }
      const due = collectionDayFor(state.endTime, policy);
      rows.push({
        order_number: ord.order_number,
        // Synced marketplace orders are closed by WAYBILL SCAN only — their
        // status relays to the platform, so a hand-tick must not touch them.
        api_source:   !!(ord.zort_id || batch.uploaded_by === 'zort-sync'),
        client_name:  batch.client_name || '',
        customer_name: ord.customer_name || '',
        waybill_number: ord.waybill_number || '',
        carrier:      ord.carrier || '',
        idealscan_code: batch.idealscan_code || '',
        cartons:      (state.cartons || []).length || 1,
        done_at:      state.endTime || null,
        operator:     state.operator || '',
        collection_due: due,
        overdue:      pickupOverdue(due),
      });
    }
  }
  // Oldest first — the parcel that has been here longest is the one to chase.
  rows.sort((a, b) => String(a.collection_due || '').localeCompare(String(b.collection_due || ''))
                   || String(a.done_at || '').localeCompare(String(b.done_at || '')));
  // Per the user: close off by CLIENT. A courier usually collects one
  // client's parcels, so the list is filtered to that account rather than
  // ticked out of a mixed pile — which is how the wrong parcel gets closed.
  const clients = [...new Set(rows.map(r => r.client_name).filter(Boolean))].sort();
  const want = String(req.query.client || '').trim().toLowerCase();
  const shown = want ? rows.filter(r => String(r.client_name || '').trim().toLowerCase() === want) : rows;
  res.json({
    policy, today,
    // The TILES stay whole-warehouse — they answer "what is outstanding here",
    // and narrowing them to the filter would hide the rest of the backlog.
    awaiting: rows.length,
    dueToday: rows.filter(r => r.collection_due === today).length,
    overdue: rows.filter(r => r.overdue).length,
    pickedToday,
    clients,
    filteredClient: want ? (clients.find(c => c.toLowerCase() === want) || req.query.client) : '',
    showing: shown.length,
    rows: shown.slice(0, 500),
  });
});

// Mark orders picked up (or undo a mistake). `at` lets a closing be recorded
// for when it actually happened rather than when someone got round to keying
// it — a courier that came at 17:00 and a screen touched at 18:30 are not the
// same event, and the whole point of this record is that it is true.
app.post('/api/orders/pickup', express.json(), (req, res) => {
  const nums = Array.isArray(req.body?.orderNumbers) ? req.body.orderNumbers.map(String) : [];
  if (!nums.length) return res.status(400).json({ error: 'Select at least one order.' });
  const undo = req.body?.undo === true;
  const at = req.body?.at && !isNaN(new Date(req.body.at)) ? new Date(req.body.at).toISOString() : new Date().toISOString();
  const db = readDb();
  const policy = pickupPolicy(db);
  const done = [], refused = [];
  for (const num of nums) {
    const batch = findBatchForOrder(db, num);
    const state = batch?.orderStates?.[num];
    if (!batch || !state) { refused.push({ order: num, error: 'Order not found' }); continue; }
    // ONLY picked, packed and scanned work can be closed off. A part-scanned
    // order marked as collected would bank an unfinished pick as shipped.
    if (state.status !== 'done') { refused.push({ order: num, error: `Not finished yet (${state.status})` }); continue; }
    if (undo) {
      if (!state.pickup) { refused.push({ order: num, error: 'Was not marked picked up' }); continue; }
      delete state.pickup;
      done.push(num);
      continue;
    }
    if (state.pickup) { refused.push({ order: num, error: 'Already picked up' }); continue; }
    // API-SYNCED ORDERS: the collection status feeds the platform relay, so a
    // hand-tick is disallowed — closing one requires SCANNING its waybill (an
    // observed physical handover), never a checkbox. Uploaded orders keep the
    // manual tick exactly as before.
    {
      const ord = (batch.orders || []).find(o => String(o.order_number) === num);
      const apiSource = !!(ord?.zort_id || batch.uploaded_by === 'zort-sync');
      const method = String(req.body?.method || 'manual');
      if (apiSource && method !== 'scan') {
        refused.push({ order: num, error: 'API order — close by scanning its waybill, not by tick' });
        continue;
      }
    }
    state.pickup = {
      at, by: req.userId || '',
      method: String(req.body?.method || 'manual').slice(0, 20),
      collection_day: collectionDayFor(state.endTime, policy),
    };
    done.push(num);
  }
  if (done.length) {
    writeDb(db);
    logAudit(undo ? 'orders_pickup_undone' : 'orders_picked_up', {
      orders: done.length, sample: done.slice(0, 12), at,
      method: String(req.body?.method || 'manual').slice(0, 20), by: req.userId || '',
    });
  }
  res.json({ ok: true, updated: done.length, orders: done, refused });
});

// The collection policy — cut-off, self-drop days, no-collection days.
app.get('/api/pickup-policy', (req, res) => res.json(pickupPolicy(readDb())));
// ADMIN OR MASTER, not master-only. The collection schedule is an operational
// arrangement the admins run day to day (a courier changing their pickup time
// should not need the Administrator key), so it follows the same guard as the
// admin reports: master key OR role 'admin', enforced server-side — warehouse
// gets a real 403 even calling it directly, not just a hidden button.
app.post('/api/master/pickup-policy', express.json(), (req, res) => {
  if (req.headers['x-master-key'] !== MASTER_PASS) {
    const role = readUsers().find(u => u.id === req.userId)?.role || 'warehouse';
    if (role !== 'admin') return res.status(403).json({ error: 'Only Admin users can change the collection schedule.' });
  }
  const b = req.body || {};
  if (b.cutoff && !/^\d{1,2}:\d{2}$/.test(String(b.cutoff))) {
    return res.status(400).json({ error: 'Cut-off must look like 17:00.' });
  }
  const clean = list => [...new Set((Array.isArray(list) ? list : []).map(Number).filter(n => Number.isInteger(n) && n >= 0 && n <= 6))];
  const db = readDb();
  const next = {
    enabled: b.enabled !== false,
    cutoff: b.cutoff ? String(b.cutoff) : pickupPolicy(db).cutoff,
    selfDropDays: b.selfDropDays === undefined ? pickupPolicy(db).selfDropDays : clean(b.selfDropDays),
    noCollectionDays: b.noCollectionDays === undefined ? pickupPolicy(db).noCollectionDays : clean(b.noCollectionDays),
  };
  // A day cannot both collect nothing and be one we drive over ourselves.
  const clash = next.selfDropDays.filter(d => next.noCollectionDays.includes(d));
  if (clash.length) return res.status(400).json({ error: 'A day cannot be both a self-drop day and a no-collection day.' });
  db.pickupPolicy = next;
  applyAutoPickups(db);   // a newly-added self-drop day settles its own history
  writeDb(db);
  logAudit('pickup_policy_updated', { ...next, by: req.userId || 'master' });
  res.json({ ok: true, policy: next });
});

// ── Fulfilment KPI schedule ─────────────────────────────────────────────────
// Reading it is floor information — the packers need to know what today's
// cut-offs are. Changing it is a commercial promise, so it follows the same
// guard as the collection schedule: admin role or the master key.
app.get('/api/fulfilment-policy', (req, res) => {
  const db = readDb();
  res.json({ ...fulfilmentPolicy(db), handoverAt: pickupPolicy(db).cutoff });
});
app.post('/api/master/fulfilment-policy', express.json(), (req, res) => {
  if (req.headers['x-master-key'] !== MASTER_PASS) {
    const role = readUsers().find(u => u.id === req.userId)?.role || 'warehouse';
    if (role !== 'admin') return res.status(403).json({ error: 'Only Admin users can change the fulfilment KPI.' });
  }
  const b = req.body || {};
  const db = readDb();
  const cur = fulfilmentPolicy(db);
  let bands = cur.bands;
  if (b.bands !== undefined) {
    if (!Array.isArray(b.bands) || !b.bands.length) {
      return res.status(400).json({ error: 'At least one cut-off band is required.' });
    }
    if (b.bands.length > 6) return res.status(400).json({ error: 'At most 6 bands.' });
    for (const x of b.bands) {
      if (!/^\d{1,2}:\d{2}$/.test(String(x?.until || ''))) {
        return res.status(400).json({ error: 'Each band needs a cut-off time like 12:00.' });
      }
    }
    bands = b.bands.map(x => ({
      until: String(x.until).padStart(5, '0'),
      sameDay: x.sameDay !== false,
      commitment: x.commitment === 'target' ? 'target' : 'committed',
      label: String(x.label || '').slice(0, 60) || (x.sameDay !== false ? 'Same working day' : 'Next working day'),
      priorityPlatforms: (Array.isArray(x.priorityPlatforms) ? x.priorityPlatforms : [])
        .map(v => String(v).trim().toLowerCase()).filter(Boolean).slice(0, 10),
    })).sort((a, c) => a.until.localeCompare(c.until));
    // The last band has to catch everything, or an order arriving late in the
    // evening would fall through and carry no promise at all.
    if (bands[bands.length - 1].until < '23:59') bands[bands.length - 1].until = '24:00';
    if (new Set(bands.map(x => x.until)).size !== bands.length) {
      return res.status(400).json({ error: 'Two bands cannot share the same cut-off time.' });
    }
  }
  const next = {
    enabled: b.enabled !== false,
    bands,
    warnMins: b.warnMins === undefined ? cur.warnMins : Number(b.warnMins),
    criticalMins: b.criticalMins === undefined ? cur.criticalMins : Number(b.criticalMins),
  };
  if (!(next.criticalMins > 0) || !(next.warnMins > 0)) {
    return res.status(400).json({ error: 'The amber and red thresholds must both be more than zero minutes.' });
  }
  if (next.criticalMins >= next.warnMins) {
    return res.status(400).json({ error: 'The red threshold must be shorter than the amber one.' });
  }
  db.fulfilmentPolicy = next;
  writeDb(db);
  logAudit('fulfilment_policy_updated', {
    enabled: next.enabled, bands: next.bands.length, warnMins: next.warnMins,
    criticalMins: next.criticalMins, by: req.userId || 'master',
  });
  res.json({ ok: true, policy: { ...fulfilmentPolicy(db), handoverAt: pickupPolicy(db).cutoff } });
});

app.post('/api/scan/order-deletion-request', (req, res) => {
  const { orderNumber, batchId, reason } = req.body || {};
  const reasonTrim = String(reason || '').trim();
  if (!orderNumber || !batchId) return res.status(400).json({ error: 'orderNumber and batchId required' });
  if (!reasonTrim) return res.status(400).json({ error: 'A reason is required to request deletion.' });
  const auth = verifyAdminReconfirm(req);
  if (auth.error) return res.status(auth.code).json({ error: auth.error, authFailed: auth.code === 403 });
  const db    = readDb();
  const batch = db.batches.find(b => b.id === batchId);
  if (!batch) return res.status(404).json({ error: 'Batch not found' });
  if (!(batch.orders || []).some(o => o.order_number === orderNumber)) {
    return res.status(404).json({ error: 'Order not found in batch' });
  }
  if (!batch.orderStates) batch.orderStates = {};
  const state = batch.orderStates[orderNumber] || { status: 'pending', scanned: {} };
  if (state.status === 'done') {
    return res.status(403).json({ error: 'This order is completed and can no longer be deleted.' });
  }
  if (state.pending_deletion) {
    return res.status(409).json({ error: 'A deletion request is already pending for this order.' });
  }
  state.pending_deletion = { reason: reasonTrim, requestedBy: req.userId, requestedAt: new Date().toISOString() };
  batch.orderStates[orderNumber] = state;
  writeDb(db);
  logAudit('order_deletion_requested', { order: orderNumber, batchId, client: batch.client_name || '', by: req.userId || '', reason: reasonTrim });
  res.json({ ok: true });
});

// Bulk version. The single-order route used to be called in a LOOP from the
// client — one HTTP request and one password check per order — so selecting 143
// orders re-verified the same password 143 times and, when it did not match,
// produced 143 identical "Incorrect password" lines in one alert with no clue
// which secret was wanted. Here the password is checked ONCE up front and a
// failure returns a single clear message; only then are the orders processed,
// each with its own per-order outcome so genuine per-order refusals (already
// completed, already pending) are still reported individually.
app.post('/api/scan/order-deletion-request-bulk', express.json(), (req, res) => {
  const reasonTrim = String(req.body?.reason || '').trim();
  const targets = Array.isArray(req.body?.targets) ? req.body.targets : [];
  if (!targets.length) return res.status(400).json({ error: 'No orders selected.' });
  if (!reasonTrim) return res.status(400).json({ error: 'A reason is required to request deletion.' });
  if (targets.length > 2000) return res.status(400).json({ error: 'Too many orders in one request.' });

  const auth = verifyAdminReconfirm(req);
  if (auth.error) return res.status(auth.code).json({ error: auth.error, authFailed: auth.code === 403 });

  const db = readDb();
  const requested = [], failed = [];
  for (const t of targets) {
    const orderNumber = String(t?.orderNumber || '');
    const batchId = String(t?.batchId || '');
    const batch = db.batches.find(b => b.id === batchId);
    if (!batch) { failed.push({ orderNumber, error: 'Batch not found' }); continue; }
    if (!(batch.orders || []).some(o => o.order_number === orderNumber)) {
      failed.push({ orderNumber, error: 'Order not found in batch' }); continue;
    }
    if (!batch.orderStates) batch.orderStates = {};
    const state = batch.orderStates[orderNumber] || { status: 'pending', scanned: {} };
    if (state.status === 'done') { failed.push({ orderNumber, error: 'Already completed — cannot be deleted' }); continue; }
    if (state.pending_deletion) { failed.push({ orderNumber, error: 'Already pending deletion' }); continue; }
    state.pending_deletion = { reason: reasonTrim, requestedBy: req.userId, requestedAt: new Date().toISOString() };
    batch.orderStates[orderNumber] = state;
    requested.push(orderNumber);
  }
  // One write for the whole batch of requests, not one per order.
  if (requested.length) writeDb(db);
  logAudit('order_deletion_requested_bulk', {
    count: requested.length, failedCount: failed.length, by: req.userId || '',
    viaMaster: !!auth.viaMaster, reason: reasonTrim,
    orders: requested.slice(0, 200),
  });
  res.json({ ok: true, requested: requested.length, failed });
});

app.get('/api/master/pending-deletions', (req, res) => {
  if (!checkMaster(req, res)) return;
  const db      = readDb();
  const nameFor = (() => {
    const byId = new Map(readUsers().map(u => [u.id, u.name || u.id]));
    return id => byId.get(id) || id || '(unknown)';
  })();
  const out = [];
  for (const batch of db.batches || []) {
    const states = batch.orderStates || {};
    for (const ord of (batch.orders || [])) {
      const state = states[ord.order_number];
      if (!state || !state.pending_deletion) continue;
      const scannedQty = Object.values(state.scanned || {}).reduce((s, v) => s + v, 0);
      out.push({
        orderNumber:     ord.order_number,
        batchId:         batch.id,
        client:          batch.client_name || '',
        reason:          state.pending_deletion.reason,
        requestedBy:     state.pending_deletion.requestedBy,
        requestedByName: nameFor(state.pending_deletion.requestedBy),
        requestedAt:     state.pending_deletion.requestedAt,
        scannedQty,
        totalQty:        ord.total_qty || 0,
      });
    }
  }
  out.sort((a, b) => String(a.requestedAt).localeCompare(String(b.requestedAt))); // oldest-waiting first
  res.json(out);
});

// Bulk approve / reject. A Master facing 143 queued requests should not have to
// click 143 times, so the Pending Deletions table has select-all. Approving is
// IRREVERSIBLE, so this route does the work once, atomically (a single writeDb),
// and reports what actually happened per order rather than assuming success.
app.post('/api/master/pending-deletions/bulk', express.json(), (req, res) => {
  if (!checkMaster(req, res)) return;
  const action = req.body?.action === 'reject' ? 'reject' : 'approve';
  const note = String(req.body?.note || '').trim();
  const targets = Array.isArray(req.body?.targets) ? req.body.targets : [];
  if (!targets.length) return res.status(400).json({ error: 'Nothing selected.' });
  if (targets.length > 5000) return res.status(400).json({ error: 'Too many in one request.' });

  const db = readDb();
  const done = [], failed = [];
  for (const t of targets) {
    const orderNumber = String(t?.orderNumber || '');
    const batchId = String(t?.batchId || '');
    const batch = db.batches.find(b => b.id === batchId);
    if (!batch) { failed.push({ orderNumber, error: 'Batch no longer exists' }); continue; }
    const state = (batch.orderStates || {})[orderNumber];
    if (!state || !state.pending_deletion) { failed.push({ orderNumber, error: 'No longer pending' }); continue; }
    const pending = state.pending_deletion;
    if (action === 'reject') {
      delete state.pending_deletion;
      logAudit('order_deletion_rejected', {
        order: orderNumber, batchId, client: batch.client_name || '',
        by: req.userId || 'master', requestedBy: pending.requestedBy, reason: pending.reason, note, bulk: true,
      });
      done.push(orderNumber);
      continue;
    }
    // Completed work is never deleted — the standing rule, re-checked HERE and
    // not only at request time, because an order can be finished in the window
    // between the request and the approval.
    if (state.status === 'done') { failed.push({ orderNumber, error: 'Completed since the request — not deleted' }); continue; }
    if (!removeOrderFromBatch(batch, orderNumber)) { failed.push({ orderNumber, error: 'Order not found in batch' }); continue; }
    logAudit('order_deleted', {
      order: orderNumber, batchId, client: batch.client_name || '',
      by: req.userId || 'master', reason: pending.reason, requestedBy: pending.requestedBy, bulk: true,
    });
    done.push(orderNumber);
  }
  if (done.length) { pruneOrphanBackorders(db); pruneOrphanTransportJobs(db); releaseOrphanReservations(db); writeDb(db); }
  logAudit(action === 'approve' ? 'order_deletions_bulk_approved' : 'order_deletions_bulk_rejected', {
    count: done.length, failedCount: failed.length, by: req.userId || 'master', note,
    orders: done.slice(0, 200),
  });
  res.json({ ok: true, action, processed: done.length, failed });
});

app.post('/api/master/pending-deletions/:batchId/:orderNumber/approve', (req, res) => {
  if (!checkMaster(req, res)) return;
  const { batchId, orderNumber } = req.params;
  try {
    const db    = readDb();
    const batch = db.batches.find(b => b.id === batchId);
    if (!batch) return res.status(404).json({ error: 'Batch not found' });
    const state = (batch.orderStates || {})[orderNumber];
    if (!state || !state.pending_deletion) return res.status(404).json({ error: 'No pending deletion request for this order.' });
    const pending = state.pending_deletion;
    if (!removeOrderFromBatch(batch, orderNumber)) return res.status(404).json({ error: 'Order not found in batch' });
    pruneOrphanBackorders(db);          // the order's backorders go with it
    releaseOrphanReservations(db);      // …and its reservation is given back
    pruneOrphanTransportJobs(db);       // and its delivery
    writeDb(db);
    logAudit('order_deleted', {
      order: orderNumber, batchId, client: batch.client_name || '',
      by: req.userId || 'master', reason: pending.reason, requestedBy: pending.requestedBy,
    });
    res.json({ ok: true });
  } catch (err) {
    res.status(500).json({ error: err.message });
  }
});

app.post('/api/master/pending-deletions/:batchId/:orderNumber/reject', (req, res) => {
  if (!checkMaster(req, res)) return;
  const { batchId, orderNumber } = req.params;
  const note = String(req.body?.note || '').trim();
  try {
    const db    = readDb();
    const batch = db.batches.find(b => b.id === batchId);
    if (!batch) return res.status(404).json({ error: 'Batch not found' });
    const state = (batch.orderStates || {})[orderNumber];
    if (!state || !state.pending_deletion) return res.status(404).json({ error: 'No pending deletion request for this order.' });
    const pending = state.pending_deletion;
    delete state.pending_deletion;
    writeDb(db);
    logAudit('order_deletion_rejected', {
      order: orderNumber, batchId, client: batch.client_name || '',
      by: req.userId || 'master', requestedBy: pending.requestedBy, reason: pending.reason, note,
    });
    res.json({ ok: true });
  } catch (err) {
    res.status(500).json({ error: err.message });
  }
});

// ── Master: find/remove batches corrupted by the wide-pivot-melt bug ────────
// A fixed bug (_tryMeltWide misreading Keyfields/Betime "d-" metadata columns
// as SKU columns) saved some uploaded batches with fake item rows (sku values
// like "d-exline", "d-exref2", "d-exdate2") instead of real product SKUs. The
// real SKU values were never stored, so these batches can't be repaired in
// place — they must be re-uploaded from the original source file. These
// routes locate and remove the affected batches so they can be re-uploaded.
// Exact match only (no "d-" prefix heuristic) — a real product SKU could
// legitimately start with "D-"; the reserved Keyfields names below are an
// exact, fixed list so matching them precisely carries no false-positive risk.
const _RESERVED_KEYFIELDS = new Set(KEYFIELDS_HEADERS.map(h => h.toLowerCase()));
function _isMeltBugSku(sku) {
  return _RESERVED_KEYFIELDS.has(String(sku || '').trim().toLowerCase());
}
function _findMeltBugBatches(db) {
  return db.batches.filter(b =>
    (b.orders || []).some(o => (o.lines || []).some(l => _isMeltBugSku(l.sku)))
  );
}

app.get('/api/master/melt-bug-scan', (req, res) => {
  if (!checkMaster(req, res)) return;
  const db       = readDb();
  const affected = _findMeltBugBatches(db).map(b => ({
    batchId:      b.id,
    filename:     b.filename,
    uploaded_at:  b.uploaded_at,
    client_name:  b.client_name || '',
    order_count:  b.order_count,
    row_count:    b.row_count,
  }));
  res.json({ affectedCount: affected.length, batches: affected });
});

app.delete('/api/master/melt-bug-batches', (req, res) => {
  if (!checkMaster(req, res)) return;
  try {
    const db       = readDb();
    const affected = _findMeltBugBatches(db);
    const removed  = affected.map(b => ({ batchId: b.id, filename: b.filename, client_name: b.client_name || '' }));
    const ids      = new Set(affected.map(b => b.id));
    db.batches = db.batches.filter(b => !ids.has(b.id));
    writeDb(db);
    for (const b of affected) {
      try { fs.unlinkSync(path.join(WMS_DIR, `${b.id}.xlsx`)); } catch {}
      try { fs.rmSync(path.join(WAYBILL_DIR, b.id), { recursive: true, force: true }); } catch {}
    }
    res.json({ ok: true, removedCount: removed.length, removed });
  } catch (err) {
    res.status(500).json({ error: err.message });
  }
});

