// POST /api/tms/stops/:id/complete — Mark route stop as completed
app.post('/api/tms/stops/:id/complete', requireAuth, requireMysql, express.json(), async (req, res) => {
  try {
    const { id } = req.params;
    const { notes, photo_url } = req.body;

    await queryMysql(
      'UPDATE route_stops SET status = "completed", completed_at = NOW(), notes = ? WHERE id = ?',
      [notes || null, id]
    );

    // Check if all stops in the route are completed
    const stop = await queryMysql('SELECT route_id FROM route_stops WHERE id = ?', [id]);
    if (stop && stop.length > 0) {
      const routeId = stop[0].route_id;
      const remaining = await queryMysql(
        'SELECT COUNT(*) as count FROM route_stops WHERE route_id = ? AND status != "completed"',
        [routeId]
      );

      if (remaining && remaining.length > 0 && remaining[0].count === 0) {
        // All stops completed, mark route as completed
        await queryMysql('UPDATE routes SET status = "completed" WHERE id = ?', [routeId]);
        logAudit('tms_route_completed', { routeId });
      }
    }

    logAudit('tms_stop_completed', { stopId: id, by: req.userId || 'unknown' });
    res.json({ success: true, message: 'Stop marked as completed' });
  } catch (err) {
    res.status(500).json({ error: err.message });
  }
});

// POST /api/tms/stops/:id/fail — Mark route stop as failed
app.post('/api/tms/stops/:id/fail', requireAuth, requireMysql, express.json(), async (req, res) => {
  try {
    const { id } = req.params;
    const { reason, notes } = req.body;

    await queryMysql(
      'UPDATE route_stops SET status = "failed", notes = ? WHERE id = ?',
      [notes || reason || null, id]
    );

    logAudit('tms_stop_failed', { stopId: id, reason: reason || 'unknown', by: req.userId || 'unknown' });
    res.json({ success: true, message: 'Stop marked as failed' });
  } catch (err) {
    res.status(500).json({ error: err.message });
  }
});

// ── DRIVER APP API ENDPOINTS ─────────────────────────────────────────────────
// Drivers are `db.drivers[]` records (the SAME roster the Transport route
// planner assigns from — see /api/drivers above) with an optional PIN set
// via Transport → Driver Details. This replaces an earlier, broken
// implementation that authenticated against `users[role==='driver']` — a
// store nothing could ever create a record in through normal use, and whose
// ids never matched `transport.assignedDriver` (populated from db.drivers
// ids by the route planner) — so no job could ever have appeared for a
// logged-in driver even if login itself worked. Session tokens are issued
// through the same `activeSessions` map every other login uses, just
// namespaced `driver:<id>` so they can never collide with a staff user id.
function driverStatusLabel(job) {
  const remarks = String(job?.podRemarks || '').trim();
  if (job?.status === 'confirmed')  return { label: 'Staging', color: '#64748b' };
  if (job?.status === 'in-transit') return { label: 'On the road', color: '#f59e0b' };
  if (job?.status === 'delivered')  return remarks
    ? { label: 'Delivered w/ Remarks', color: '#ef4444' }
    : { label: 'Delivered', color: '#22c55e' };
  if (job?.status === 'cancelled')  return { label: 'Cancelled', color: '#94a3b8' };
  return { label: 'Preplanned', color: '#0ea5e9' };
}
// db.drivers[] is TENANT-SCOPED data (unlike users[], which is global with
// its own explicit tenant_id field) — a driver id alone doesn't say which
// tenant it belongs to. Login has no tenant context yet, so it searches
// every tenant's own db.drivers[] for a match. Session keys then ENCODE the
// resolved tenant (driver:<tenantId>:<driverId>) so every later request can
// re-establish the correct tenant directly from the token, with no repeated
// search — see requireDriverAuthMiddleware below.
// Resolves what a driver typed into the Driver App's "Driver ID" box.
// Accepts EITHER the record id or the driver's name, because a driver added
// without an explicit id gets an auto-generated one (DRV-<timestamp>) while
// the label everyone actually knows them by ("DRV001") is the NAME — typing
// that failed with "Driver not found" and no screen showed the real id.
// ID always wins so an exact id can never be shadowed by someone else's
// name; a name matching several drivers is refused rather than guessed at.
function _findDriverAcrossTenants(idNorm) {
  for (const t of tenantStore.listTenants()) {
    const found = tenantContext.run(t.id, () => (readDb().drivers || []).find(d => String(d.id).trim().toLowerCase() === idNorm));
    if (found) return { tenantId: t.id, driver: found };
  }
  const byName = [];
  for (const t of tenantStore.listTenants()) {
    tenantContext.run(t.id, () => {
      for (const d of (readDb().drivers || [])) {
        if (String(d.name || '').trim().toLowerCase() === idNorm) byName.push({ tenantId: t.id, driver: d });
      }
    });
  }
  if (byName.length === 1) return byName[0];
  if (byName.length > 1) return { ambiguous: true };
  return null;
}

// Local token check (the '/api/driver/' prefix is exempt from the global
// requireAuth middleware — see AUTH_PUBLIC — so each handler checks itself).
// Registered as real Express middleware (not called inline) because it must
// re-establish the CORRECT tenant context for the rest of the request —
// the earlier global tenantMiddleware gets this wrong for driver tokens
// (it looks up the token's owner in the global users[] store, where
// drivers don't exist), so this overrides it via a nested
// tenantContext.run(), the same mechanism tenantMiddleware itself uses.
function requireDriverAuthMiddleware(req, res, next) {
  const token = req.headers['x-auth-token'] || req.query.token;
  if (!token) { res.status(401).json({ error: 'Unauthorised' }); return; }
  for (const [sessionKey, t] of activeSessions) {
    if (t !== token || !sessionKey.startsWith('driver:')) continue;
    const rest = sessionKey.slice(7);
    const sep = rest.indexOf(':');
    // Old-format sessions (driver:<id>, pre-dating tenant-aware keys) fall
    // back to the default tenant — the same behavior they had before this
    // fix, so an existing logged-in driver isn't kicked out by the change.
    const tenantId = sep >= 0 ? rest.slice(0, sep) : tenantStore.DEFAULT_TENANT_ID;
    const driverId = sep >= 0 ? rest.slice(sep + 1) : rest;
    req.driverId = driverId;
    req.driverSessionKey = sessionKey;
    tenantContext.run(tenantId, () => next());
    return;
  }
  res.status(401).json({ error: 'Session expired' });
}

app.post('/api/driver/login', express.json(), (req, res) => {
  const { id, pin } = req.body || {};
  if (!String(id || '').trim() || !String(pin || '').trim()) {
    return res.status(400).json({ error: 'Driver ID and PIN required' });
  }
  const idNorm = String(id).trim().toLowerCase();
  const dWait = loginBlockedFor(req, 'drv:' + idNorm);
  if (dWait) {
    res.setHeader('Retry-After', String(dWait));
    return res.status(429).json({ error: `Too many failed attempts. Try again in ${dWait}s.`, retryAfter: dWait });
  }
  const found = _findDriverAcrossTenants(idNorm);
  if (found && found.ambiguous) {
    // Name typed, but more than one driver answers to it — never guess which
    // person is signing in; the unique Driver ID disambiguates.
    loginFailure(req, 'drv:' + idNorm);
    logAudit('driver_login_failed', { driver: String(id).trim().slice(0, 60), reason: 'ambiguous_name' });
    return res.status(401).json({ error: 'More than one driver has that name — sign in with your Driver ID instead (ask your dispatcher).' });
  }
  if (!found) {
    loginFailure(req, 'drv:' + idNorm);
    logAudit('driver_login_failed', { driver: String(id).trim().slice(0, 60), reason: 'not_found' });
    return res.status(401).json({ error: 'Driver not found' });
  }
  const { tenantId, driver } = found;
  if (!driver.pinHash) {
    return res.status(401).json({ error: 'No PIN set for this driver yet — ask your dispatcher to set one in Transport → Driver Details.' });
  }
  if (hashPass(String(pin).trim(), driver.pinSalt) !== driver.pinHash) {
    loginFailure(req, 'drv:' + idNorm);
    tenantContext.run(tenantId, () => logAudit('driver_login_failed', { driver: driver.id, reason: 'bad_pin' }));
    return res.status(401).json({ error: 'Invalid PIN' });
  }
  loginSuccess(req, 'drv:' + idNorm);
  const token = uuidv4();
  const sessionKey = `driver:${tenantId}:${driver.id}`;
  const kickedOther = activeSessions.has(sessionKey);
  activeSessions.set(sessionKey, token); // one active device per driver, same rule as user logins
  persistSessions();
  tenantContext.run(tenantId, () => logAudit('driver_login', { driver: driver.id, replacedSession: kickedOther }));
  res.json({ token, driver: { id: driver.id, name: driver.name, phone: driver.phone, vehicle: driver.vehicle, plate: driver.plate } });
});

app.post('/api/driver/logout', requireDriverAuthMiddleware, express.json(), (req, res) => {
  activeSessions.delete(req.driverSessionKey);
  persistSessions();
  logAudit('driver_logout', { driver: req.driverId });
  res.json({ ok: true });
});

// GET /api/driver/jobs — the logged-in driver's own worklist: everything
// assigned to them that isn't cancelled, sorted into route order (matches
// the sequence the planner gave them), with today's already-delivered stops
// kept visible for reference at the end of the list.
app.get('/api/driver/jobs', requireDriverAuthMiddleware, (req, res) => {
  const driverId = req.driverId;
  const db = readDb();
  const todayStr = sgDateStr();
  const jobs = (db.transport || [])
    .filter(t => t.assignedDriver === driverId && t.status !== 'cancelled')
    .filter(t => t.status !== 'delivered' || sgDateStr(new Date(t.deliveredAt || 0)) === todayStr)
    .sort((a, b) => (a.routeNum ?? 9999) - (b.routeNum ?? 9999) || (a.stopSeq ?? 9999) - (b.stopSeq ?? 9999))
    .map(t => {
      const st = driverStatusLabel(t);
      return {
        id: t.id,
        client: t.clientName || '',
        referenceId: t.referenceId || t.clientId || '',
        address: t.shipping?.addressLine1 || '',
        zip: t.shipping?.zip || '',
        phone: t.shipping?.phone || '',
        notes: t.notes || '',
        packages: t.packages || 1,
        routeNum: t.routeNum ?? null,
        stopSeq: t.stopSeq ?? null,
        status: t.status || 'pending',
        statusLabel: st.label,
        statusColor: st.color,
        podRemarks: t.podRemarks || '',
        deliveredAt: t.deliveredAt || null,
        driverAcceptedAt: t.driverAcceptedAt || null,
        podPhotos: (t.podPhotos || []).map(p => ({ id: p.id, uploadedAt: p.uploadedAt })),
        podLocation: t.podLocation || null,
      };
    });
  // Today's running stats, so the driver sees drops/done/distance/idle
  // without the app having to derive them.
  const drv = (db.drivers || []).find(d => d.id === driverId) || {};
  const t = (drv.today && drv.today.day === todayStr) ? drv.today : {};
  const idleMin = t.idleSince ? Math.round((Date.now() - new Date(t.idleSince).getTime()) / 60000) : 0;
  res.json({
    jobs,
    driver: {
      id: drv.id || driverId, name: drv.name || '', vehicle: drv.vehicle || '', plate: drv.plate || '',
    },
    stats: {
      drops:      jobs.length,
      done:       jobs.filter(j => j.status === 'delivered').length,
      onRoad:     jobs.filter(j => j.status === 'in-transit').length,
      distanceKm: Math.round((t.distanceM || 0) / 100) / 10,
      idleMinutes: idleMin,
      idleTotalMinutes: Math.round((t.idleTotalMs || 0) / 60000) + idleMin,
      idleAlert:  idleMin >= 10,
    },
  });
});

// POST /api/driver/jobs/:id/accept — the driver acknowledges a newly
// assigned job. A separate acknowledgment layer, NOT a status transition
// (status stays 'confirmed') — so it never interferes with the existing
// status lifecycle the office UI/reports depend on. Pickup refuses to
// proceed until a job has been accepted, so this is a real gate, not
// cosmetic.
app.post('/api/driver/jobs/:id/accept', requireDriverAuthMiddleware, express.json(), (req, res) => {
  const driverId = req.driverId;
  const db = readDb();
  const job = (db.transport || []).find(t => t.id === req.params.id);
  if (!job) return res.status(404).json({ error: 'Job not found' });
  if (job.assignedDriver !== driverId) return res.status(403).json({ error: 'This job is not assigned to you' });
  if (job.status !== 'confirmed') return res.status(409).json({ error: `Job is "${job.status}", nothing to accept` });
  job.driverAcceptedAt = new Date().toISOString();
  writeDb(db);
  logAudit('driver_job_accepted', { jobId: job.id, driver: driverId, client: job.clientName || '' });
  res.json({ ok: true, job });
});

// POST /api/driver/jobs/:id/pickup — "I've picked this up, heading out."
// Same transition the office map popup's "Picked Up" button performs, just
// ownership-scoped so a driver can only move their OWN assigned jobs.
// Live driver position. The Driver App watches location continuously while
// it's open and posts here; this is what makes a live fleet view possible
// (before this, a driver's location was only ever captured at the moment of
// delivery). Stored on the driver record — one current fix per driver, not a
// history trail, so it can't grow without bound.
// Straight-line metres between two fixes (Haversine) — used for the day's
// distance estimate and to decide whether the driver has actually moved.
function _metresBetween(a, b) {
  const R = 6371000, toRad = d => d * Math.PI / 180;
  const dLat = toRad(b.lat - a.lat), dLng = toRad(b.lng - a.lng);
  const x = Math.sin(dLat / 2) ** 2 + Math.cos(toRad(a.lat)) * Math.cos(toRad(b.lat)) * Math.sin(dLng / 2) ** 2;
  return 2 * R * Math.asin(Math.sqrt(x));
}
const DRIVER_MOVE_THRESHOLD_M = 60;      // below this the driver counts as stationary
const DRIVER_IDLE_LOG_MS      = 10 * 60 * 1000;  // a stop longer than this gets logged

app.post('/api/driver/location', requireDriverAuthMiddleware, express.json(), (req, res) => {
  const { lat, lng, accuracy, heading, speed } = req.body || {};
  const la = Number(lat), ln = Number(lng);
  if (!Number.isFinite(la) || !Number.isFinite(ln)) return res.status(400).json({ error: 'lat and lng are required' });
  if (la < -90 || la > 90 || ln < -180 || ln > 180) return res.status(400).json({ error: 'lat/lng out of range' });
  const db = readDb();
  const drv = (db.drivers || []).find(d => d.id === req.driverId);
  if (!drv) return res.status(404).json({ error: 'Driver not found' });

  const now = new Date();
  const nowMs = now.getTime();
  const fix = {
    lat: la, lng: ln,
    accuracy: Number(accuracy) || null,
    heading: Number.isFinite(Number(heading)) ? Number(heading) : null,
    speed: Number.isFinite(Number(speed)) ? Number(speed) : null,
    at: now.toISOString(),
  };

  // Per-SGT-day rolling stats; a new day starts clean.
  const day = sgDateStr(now);
  if (!drv.today || drv.today.day !== day) {
    drv.today = { day, distanceM: 0, idleSince: null, idleLogged: false, idleTotalMs: 0 };
  }
  const t = drv.today;
  const prev = drv.lastLocation;
  if (prev && Number.isFinite(prev.lat) && Number.isFinite(prev.lng)) {
    const moved = _metresBetween(prev, fix);
    const gapMs = Math.max(0, nowMs - new Date(prev.at || 0).getTime());
    if (moved >= DRIVER_MOVE_THRESHOLD_M) {
      // Real movement: bank the distance and close any idle spell.
      t.distanceM = Math.round((t.distanceM || 0) + moved);
      if (t.idleSince) {
        t.idleTotalMs = (t.idleTotalMs || 0) + Math.max(0, nowMs - new Date(t.idleSince).getTime());
      }
      t.idleSince = null; t.idleLogged = false;
    } else {
      // Stationary — start (or continue) an idle spell. Logged once, when it
      // crosses the threshold, so one long stop is one entry not hundreds.
      if (!t.idleSince) t.idleSince = prev.at || now.toISOString();
      const idleMs = nowMs - new Date(t.idleSince).getTime();
      if (idleMs >= DRIVER_IDLE_LOG_MS && !t.idleLogged) {
        t.idleLogged = true;
        if (!Array.isArray(drv.idleLog)) drv.idleLog = [];
        drv.idleLog.unshift({
          at: t.idleSince, lat: la, lng: ln,
          minutes: Math.round(idleMs / 60000), day,
        });
        if (drv.idleLog.length > 200) drv.idleLog.length = 200;
        logAudit('driver_idle_logged', {
          driverId: drv.id, minutes: Math.round(idleMs / 60000),
          lat: la, lng: ln, since: t.idleSince,
        });
      }
      void gapMs;
    }
  }
  drv.lastLocation = fix;
  writeDb(db);
  // deliberately NOT audit-logged per ping: a fix every ~30s per driver would
  // swamp the ledger. Only the idle events above are recorded.
  res.json({
    ok: true,
    distanceKm: Math.round((t.distanceM || 0) / 100) / 10,
    idleMinutes: t.idleSince ? Math.round((nowMs - new Date(t.idleSince).getTime()) / 60000) : 0,
  });
});

// ── Communication: broadcasts to drivers and/or warehouse & office staff ────
// One store for both audiences. A notice names its recipients explicitly —
// every driver, every staff user, or a hand-picked set of either — and each
// recipient must acknowledge it, so "nobody told me" stops being a defence.
// Acks are keyed by audience so a driver id can never collide with a user id.
function noticeStore(db) {
  // legacy: the first cut of this feature stored driver-only notices under
  // db.driverNotices. Fold any of those in once, so nothing is lost.
  if (Array.isArray(db.driverNotices) && db.driverNotices.length) {
    (db.notices ||= []);
    for (const n of db.driverNotices) {
      db.notices.push({
        id: n.id, message: n.message, priority: n.priority || 'normal',
        toDrivers: n.target === 'all' ? 'all' : (n.driverIds || []),
        toUsers: [],
        createdAt: n.createdAt, createdBy: n.createdBy,
        acks: Object.fromEntries(Object.entries(n.acks || {}).map(([k, v]) => ['driver:' + k, v])),
      });
    }
    delete db.driverNotices;
  }
  return (db.notices ||= []);
}
const _isAll = v => v === 'all';
const _listed = (v, id) => _isAll(v) || (Array.isArray(v) && v.includes(id));
// A CLIENT is one recipient, not one per portal login. A company reads a
// notice once; asking every one of their five logins to acknowledge separately
// would turn an announcement into a chase-list. Any of their logins may
// acknowledge on the account's behalf.
function noticeRecipients(n, db) {
  const drivers = _isAll(n.toDrivers) ? (db.drivers || []).map(d => 'driver:' + d.id)
                : (n.toDrivers || []).map(id => 'driver:' + id);
  const users   = _isAll(n.toUsers)   ? readUsers().map(u => 'user:' + u.id)
                : (n.toUsers || []).map(id => 'user:' + id);
  const clients = _isAll(n.toClients) ? clientProfiles(db).map(p => 'client:' + p.client)
                : (n.toClients || []).map(c => 'client:' + c);
  return [...drivers, ...users, ...clients];
}

// Who an admin can send to (for the recipient picker).
app.get('/api/master/notice-audience', (req, res) => {
  if (!checkMaster(req, res)) return;
  const db = readDb();
  res.json({
    drivers: (db.drivers || []).map(d => ({ id: d.id, name: d.name || d.id, vehicle: d.vehicle || '', plate: d.plate || '' })),
    users:   readUsers().map(u => ({ id: u.id, name: u.name || u.id, role: u.role || 'admin' })),
    // Only clients with a portal login can actually be reached — offering the
    // rest would promise a message nobody will ever see.
    clients: clientProfiles(db)
      .filter(p => portalUsers(p).some(u => u.enabled !== false && u.passwordHash))
      .map(p => ({ id: p.client, name: p.client, logins: portalUsers(p).length })),
  });
});

app.get('/api/master/notices', (req, res) => {
  if (!checkMaster(req, res)) return;
  const db = readDb();
  const names = new Map([
    ...readUsers().map(u => ['user:' + u.id, u.name || u.id]),
    ...(db.drivers || []).map(d => ['driver:' + d.id, d.name || d.id]),
    ...clientProfiles(db).map(p => ['client:' + p.client, p.client]),
  ]);
  res.json(noticeStore(db).map(n => {
    const to = noticeRecipients(n, db);
    const acked = Object.keys(n.acks || {});
    const pending = to.filter(k => !acked.includes(k));
    return {
      id: n.id, message: n.message, priority: n.priority, createdAt: n.createdAt, createdBy: n.createdBy,
      toDrivers: n.toDrivers, toUsers: n.toUsers, toClients: n.toClients || [],
      total: to.length, ackedCount: to.length - pending.length,
      pendingNames: pending.map(k => names.get(k) || k).slice(0, 40),
      ackedNames: to.filter(k => acked.includes(k)).map(k => names.get(k) || k).slice(0, 40),
    };
  }));
});

app.post('/api/master/notices', express.json(), (req, res) => {
  if (!checkMaster(req, res)) return;
  const { message, priority, toDrivers, toUsers, toClients } = req.body || {};
  const msg = String(message || '').trim();
  if (!msg) return res.status(400).json({ error: 'Message is required' });
  if (msg.length > 2000) return res.status(400).json({ error: 'Message is too long (max 2000 characters)' });
  const norm = v => (v === 'all' ? 'all' : (Array.isArray(v) ? v.filter(Boolean) : []));
  const td = norm(toDrivers), tu = norm(toUsers), tc = norm(toClients);
  if (!_isAll(td) && !td.length && !_isAll(tu) && !tu.length && !_isAll(tc) && !tc.length) {
    return res.status(400).json({ error: 'Pick at least one recipient' });
  }
  const db = readDb();
  const notice = {
    id: 'MSG-' + Date.now().toString(36).toUpperCase(),
    message: msg,
    priority: priority === 'urgent' ? 'urgent' : 'normal',
    toDrivers: td, toUsers: tu, toClients: tc,
    createdAt: new Date().toISOString(), createdBy: req.userId || 'master',
    acks: {},
  };
  const store = noticeStore(db);
  store.unshift(notice);
  if (store.length > 300) store.length = 300;
  writeDb(db);
  logAudit('notice_sent', {
    noticeId: notice.id, priority: notice.priority,
    recipients: noticeRecipients(notice, db).length, by: req.userId || '',
  });
  res.json({ ok: true, notice });
});

app.delete('/api/master/notices/:id', (req, res) => {
  if (!checkMaster(req, res)) return;
  const db = readDb();
  const before = noticeStore(db).length;
  db.notices = noticeStore(db).filter(n => n.id !== req.params.id);
  if (db.notices.length === before) return res.status(404).json({ error: 'Notice not found' });
  writeDb(db);
  logAudit('notice_deleted', { noticeId: req.params.id, by: req.userId || '' });
  res.json({ ok: true });
});

// ── Recipient side ──────────────────────────────────────────────────────────
function unackedFor(db, kind, id) {
  return noticeStore(db)
    .filter(n => _listed(kind === 'driver' ? n.toDrivers : n.toUsers, id))
    .filter(n => !(n.acks || {})[kind + ':' + id])
    .map(n => ({ id: n.id, message: n.message, priority: n.priority, createdAt: n.createdAt }));
}
function ackNotice(db, kind, id, noticeId) {
  const n = noticeStore(db).find(x => x.id === noticeId);
  if (!n) return { err: 404, msg: 'Notice not found' };
  if (!_listed(kind === 'driver' ? n.toDrivers : n.toUsers, id)) return { err: 403, msg: 'This notice is not addressed to you' };
  (n.acks ||= {})[kind + ':' + id] = new Date().toISOString();
  return { notice: n };
}

app.get('/api/driver/notices', requireDriverAuthMiddleware, (req, res) => {
  res.json(unackedFor(readDb(), 'driver', req.driverId));
});
app.post('/api/driver/notices/:id/ack', requireDriverAuthMiddleware, express.json(), (req, res) => {
  const db = readDb();
  const r = ackNotice(db, 'driver', req.driverId, req.params.id);
  if (r.err) return res.status(r.err).json({ error: r.msg });
  writeDb(db);
  logAudit('notice_acknowledged', { noticeId: req.params.id, driverId: req.driverId });
  res.json({ ok: true });
});

// Warehouse / office staff see the same notices inside the main app.
app.get('/api/notices', requireAuth, (req, res) => {
  res.json(unackedFor(readDb(), 'user', req.userId));
});
app.post('/api/notices/:id/ack', requireAuth, express.json(), (req, res) => {
  const db = readDb();
  const r = ackNotice(db, 'user', req.userId, req.params.id);
  if (r.err) return res.status(r.err).json({ error: r.msg });
  writeDb(db);
  logAudit('notice_acknowledged', { noticeId: req.params.id, user: req.userId });
  res.json({ ok: true });
});


app.post('/api/driver/jobs/:id/pickup', requireDriverAuthMiddleware, express.json(), (req, res) => {
  const driverId = req.driverId;
  const db = readDb();
  const job = (db.transport || []).find(t => t.id === req.params.id);
  if (!job) return res.status(404).json({ error: 'Job not found' });
  if (job.assignedDriver !== driverId) return res.status(403).json({ error: 'This job is not assigned to you' });
  if (job.status !== 'confirmed') return res.status(409).json({ error: `Job is "${job.status}", not ready for pickup` });
  if (!job.driverAcceptedAt) return res.status(409).json({ error: 'Accept this job before picking it up.' });
  job.status = 'in-transit';
  job.updatedAt = new Date().toISOString();
  writeDb(db);
  logAudit('driver_job_pickup', { jobId: job.id, driver: driverId, client: job.clientName || '' });
  res.json({ ok: true, job });
});

// POST /api/driver/jobs/:id/photo — ePOD photo, taken with the phone's
// camera (capture="environment" on the client's file input). Bytes are
// written to disk, NEVER into db.json — same reasoning as every other
// photo feature in this app (IdealInbound receiving photos). Ownership-
// checked like every other driver action. A delivery cannot be confirmed
// until at least one of these exists (see /deliver below) — this is what
// makes ePOD a real requirement, not an optional nicety.
app.post('/api/driver/jobs/:id/photo', upload.single('photo'), requireDriverAuthMiddleware, (req, res) => {
  const driverId = req.driverId;
  if (!req.file) return res.status(400).json({ error: 'No photo uploaded' });
  const db = readDb();
  const job = (db.transport || []).find(t => t.id === req.params.id);
  if (!job) return res.status(404).json({ error: 'Job not found' });
  if (job.assignedDriver !== driverId) return res.status(403).json({ error: 'This job is not assigned to you' });

  const photoId = uuidv4();
  const ext = (path.extname(req.file.originalname || '') || '.jpg').toLowerCase();
  const dir = path.join(POD_PHOTO_DIR, job.id);
  fs.mkdirSync(dir, { recursive: true });
  fs.writeFileSync(path.join(dir, `${photoId}${ext}`), req.file.buffer);

  const photo = { id: photoId, filename: `${photoId}${ext}`, mimeType: req.file.mimetype, uploadedAt: new Date().toISOString() };
  job.podPhotos = job.podPhotos || [];
  job.podPhotos.push(photo);
  writeDb(db);
  logAudit('driver_job_photo_added', { jobId: job.id, driver: driverId, photoId });
  res.json({ ok: true, photo: { id: photo.id, uploadedAt: photo.uploadedAt } });
});

// GET /api/driver/jobs/:id/photo/:photoId — serves an ePOD photo. BOTH
// staff (viewing from the office) and the driver who took it (viewing
// their own upload in-app) can hit this, so it accepts either token type.
// A staff token's tenant is already correctly set by the global
// tenantMiddleware; a driver token needs the same re-resolution
// requireDriverAuthMiddleware does (drivers aren't in the global users[]
// store the default resolution looks up).
function requireDriverOrStaffPhotoAuth(req, res, next) {
  const token = req.headers['x-auth-token'] || req.query.token;
  if (!token) return res.status(401).json({ error: 'Unauthorised' });
  for (const [sessionKey, t] of activeSessions) {
    if (t !== token) continue;
    if (sessionKey.startsWith('driver:')) {
      const rest = sessionKey.slice(7);
      const sep = rest.indexOf(':');
      const tenantId = sep >= 0 ? rest.slice(0, sep) : tenantStore.DEFAULT_TENANT_ID;
      req.userId = sessionKey;
      tenantContext.run(tenantId, () => next());
      return;
    }
    req.userId = sessionKey; // staff — tenant already correctly resolved upstream
    return next();
  }
  res.status(401).json({ error: 'Session expired' });
}
app.get('/api/driver/jobs/:id/photo/:photoId', requireDriverOrStaffPhotoAuth, (req, res) => {
  const { id, photoId } = req.params;
  const db = readDb();
  const job = (db.transport || []).find(t => t.id === id);
  const photo = job?.podPhotos?.find(p => p.id === photoId);
  if (!photo) return res.status(404).send('Not found');
  res.sendFile(path.join(POD_PHOTO_DIR, id, photo.filename), err => {
    if (err && !res.headersSent) res.status(404).send('Not found');
  });
});

// POST /api/driver/jobs/:id/deliver — closes out the stop. Requires at
// least one ePOD photo to already be uploaded (real proof of delivery, not
// just a status flag). GPS coordinates are best-effort: the client attempts
// navigator.geolocation before calling this, but a denied/unavailable GPS
// permission does NOT block the delivery — a hard block on a phone
// permission issue would strand a real delivery over something outside the
// driver's control, worse than a record with a missing coordinate. Optional
// remarks mark it "Delivered w/ Remarks" (an issue to follow up), same rule
// as the office Mark Delivered flow.
app.post('/api/driver/jobs/:id/deliver', requireDriverAuthMiddleware, express.json(), (req, res) => {
  const driverId = req.driverId;
  const { remarks, lat, lng, accuracy } = req.body || {};
  const db = readDb();
  const job = (db.transport || []).find(t => t.id === req.params.id);
  if (!job) return res.status(404).json({ error: 'Job not found' });
  if (job.assignedDriver !== driverId) return res.status(403).json({ error: 'This job is not assigned to you' });
  if (job.status === 'delivered' || job.status === 'cancelled') return res.status(409).json({ error: `Job is already ${job.status}` });
  if (!(job.podPhotos && job.podPhotos.length)) return res.status(409).json({ error: 'Take a delivery photo (ePOD) before marking this delivered.' });
  job.status = 'delivered';
  job.deliveredAt = new Date().toISOString();
  if (String(remarks || '').trim()) job.podRemarks = String(remarks).trim();
  if (Number.isFinite(Number(lat)) && Number.isFinite(Number(lng))) {
    job.podLocation = { lat: Number(lat), lng: Number(lng), accuracy: Number(accuracy) || null, capturedAt: new Date().toISOString() };
  }
  writeDb(db);
  logAudit('driver_job_delivered', { jobId: job.id, driver: driverId, client: job.clientName || '', withRemarks: !!String(remarks || '').trim(), hasGps: !!job.podLocation });
  res.json({ ok: true, job });
});

// GET /api/master/drivers — List all drivers (admin only)
// NOTE: the old /api/master/drivers* CRUD (a separate users[role=='driver']
// store, disconnected from db.drivers/route planning) was removed here —
// Administrator → Drivers now reads/writes the same /api/drivers roster as
// Transport → Driver Details and the Driver App.

// GET /driver — Serve the driver portal
app.get('/driver', (req, res) => {
  res.sendFile(path.join(__dirname, 'public', 'driver.html'));
});

// GET /portal — the read-only Client Portal (own login, see the portal block).
app.get('/portal', (req, res) => {
  res.sendFile(path.join(__dirname, 'public', 'portal.html'));
});

// ─────────────────────────────────────────────────────────────────────────────
//  INVENTORY (System A) — additive module, own SQLite DB (data/inventory.db).
//  Ported from the previous IdealOne app; does not touch db.json. All routes
//  are guarded by requireAuth (same as the rest of the API). If better-sqlite3
//  is unavailable the store degrades to no-ops and these endpoints return empty.
// ─────────────────────────────────────────────────────────────────────────────
const inventory = require('./lib/inventory-store');
inventory.init();
assertInventoryPath();          // must run here — see the note next to its definition
mergeInventoryClientCasing();   // likewise: needs `inventory` to exist first
backfillCataloguesFromOrders(); // the catalogue learns from the orders already on the books — same zone, same reason
// Reservations held by orders that no longer exist. THIS MUST RUN HERE, not
// with the db.json reconcile pass at the top of the file: `const inventory` is
// still in its temporal dead zone up there, so the call throws into a catch and
// is silently skipped — the trap this file has now hit three times (see
// assertInventoryPath and mergeInventoryClientCasing above).
try {
  const _rdb = readDb();
  const _freed = releaseOrphanReservations(_rdb);
  if (_freed) console.log(`[IdealOne] Inventory: released ${_freed} unit(s) reserved by orders that no longer exist`);
} catch (e) { console.error('[IdealOne] reservation reconcile failed:', e.message); }

// 3PL model: ALL stock is client-owned. Orders/batches carry only a free-text
// client_name, while the inventory store keys on client_id — so we derive a
// stable client_id from the client name (one helper, used everywhere). An
// empty/blank name falls back to 'GENERAL' so nothing is ever silently
// unscoped.
function invClientId(name) { return String(name || '').trim() || 'GENERAL'; }

// The same client spelled with different capitalisation is ONE client. Files
// arrive from different sources — one writes "BETIME", another "Betime" — and
// each new spelling used to create a SEPARATE client: its own row in the
// sidebar, and (because invClientId is case-sensitive) its own inventory
// account, splitting one client's stock in two.
//
// Rather than force a house style, adopt whatever spelling this client is
// ALREADY known by: look for a case-insensitive match across existing batches,
// inbound records and onboarding profiles, and reuse that exact string. New
// clients keep the spelling they arrive with. Everything downstream — stock,
// backorders, billing, portal scoping — then lands on one identity.
function canonicalClientName(db, name) {
  const raw = String(name || '').trim();
  if (!raw) return raw;
  const k = raw.toLowerCase();
  const seen = new Map();   // lowercase -> [spellings, most recent first]
  const note = v => {
    const t = String(v || '').trim();
    if (!t) return;
    const lk = t.toLowerCase();
    if (!seen.has(lk)) seen.set(lk, t);
  };
  // Onboarding profiles win — that is the deliberate, human-entered spelling.
  for (const p of db.clientProfiles || []) note(p.client);
  for (const b of db.batches || []) note(b.client_name);
  for (const r of db.inbound || []) note(r.client_name);
  return seen.get(k) || raw;
}

// Allocate physical bin locations to every order line via FEFO/FIFO, stamping
// l.pick_locations (what the pick list shows) + l.pick_shortfall (units with no
// stock anywhere — a real walk-up / backorder). Pure planning: consumes nothing.
//
// stagingMode governs what happens to a line's bin-shortfall that IS covered by
// STAGING stock (received but not yet put away — inventory.stagingQty):
//   'staging' → allocate those units to a pseudo-location 'STAGING' (pick from the
//               receiving area now, before it's shelved).
//   'wait'    → don't allocate them; stamp l.awaiting_putaway_qty so the pick line
//               shows "awaiting putaway" and the order waits until putaway is done.
// A running per-SKU staging pool is drawn down across the whole batch so two orders
// can't both be promised the same staging units.
// ── ONE STOCK GATE FOR EVERY WAY AN ORDER ARRIVES ──────────────────────────
// Upload, photo scan, store sync and an approved client submission all funnel
// through these two functions, so a marketplace order and a keyed-in one get
// the same allocation and the same refusal. Four copies of this would drift,
// and the first thing to drift would be whether stock was reserved at all.
//
// checkIntakeStock() reserves NOTHING — it only reports what would happen, so
// the answer shown before approving is the answer the reservation will give.
// Does this client have an item master at all? A client we hold NO stock
// position for is not a client who has run out — see the note in
// checkIntakeStock. Cheap enough to call per upload; getAll is a single query.
function clientHasItemMaster(clientId) {
  if (!inventory.available() || !clientId) return false;
  try { return (inventory.getAll({ clientId }) || []).length > 0; }
  catch (e) { console.warn('[intake] item-master check failed:', e.message); return false; }
}

// Does this client's stock live HERE? Off means their inventory is held in
// their own WMS and we only pick, pack and scan for them.
function clientStockTracking(clientId) {
  const norm = String(clientId || '').trim().toLowerCase();
  if (!norm) return true;
  try {
    const p = clientProfiles(readDb()).find(x => String(x.client || '').trim().toLowerCase() === norm);
    return !p || p.stock_tracking !== false;      // absent reads as tracked
  } catch (_) { return true; }
}

// THE GATE THE INTAKE PATHS ACTUALLY ASK. Two separate reasons to hold back —
// no catalogue at all, or a catalogue we hold purely for names and barcodes
// while the client's stock is counted somewhere else. Both mean the same
// thing here: reserve nothing, deduct nothing, invent no SKUs.
function clientStockTracked(clientId) {
  return clientHasItemMaster(clientId) && clientStockTracking(clientId);
}

// ── THE CATALOGUE LEARNS FROM THE ORDERS THAT PASS THROUGH ──────────────────
// Per the user, from a screenshot of the scan screen: a client with NO item
// master showed a full product description on the pick line — the ORDER FILE
// carries it — while the store push had nothing to send. "If my order scanning
// can have description, the store can have it too — make it a permanent
// method." So it is: every batch that enters teaches the client's catalogue.
//
//   - A SKU never seen before is CREATED with the file's wording — but only
//     for a client whose stock is NOT tracked here. For a tracked client,
//     inventing rows would change what the stock gate says about their next
//     upload; their unknown SKUs are already the intake gate's business.
//   - A row whose name is blank, or is just its own code (the legacy
//     name-from-SKU placeholder), takes the file's wording — that HEALS the
//     "1730 / 1730" rows on any client. A real name is never overwritten:
//     the catalogue stays the master (see "the item master is the DEFAULT
//     lookup"), so the learned name is the FIRST wording seen, not the last.
//   - LEARNING MUST NEVER FLIP STOCK ALLOCATION ON. Quantities were never
//     given, so when the first learned rows bring a master into existence,
//     `stock_tracking` is pinned OFF on the profile (created if needed) and
//     audit-logged. Turning it on stays a deliberate act on the onboarding
//     screen — found the hard way when a hand-loaded master nearly turned a
//     93-order client into 93 shortfall prompts.
//   - Not everything printed in a description column is a name: the SKU
//     echoed back, pure numbers and date-shaped strings are refused.
//
// The file's own wording is read from `source_description` first — once a
// placeholder name exists, enrichLinesFromCatalogue moves the file's words
// THERE and puts the (useless) placeholder in `description`.
function harvestCatalogueFromOrders(db, clientName, orders, source) {
  try {
    if (!inventory.available()) return;
    const name = String(clientName || '').trim();
    const cid = invClientId(name);
    if (!name || !cid) return;
    const hadMaster = clientHasItemMaster(cid);
    const mayCreate = !clientStockTracked(cid);
    let created = 0, healed = 0, barcoded = 0;
    const seen = new Set();
    for (const o of orders || []) {
      for (const l of (o.lines || o.items || [])) {
        const sku = String(l.sku || '').trim();
        if (!sku || seen.has(sku.toUpperCase())) continue;
        seen.add(sku.toUpperCase());
        const desc = String(l.source_description || l.description || '').trim();
        if (desc.length < 3) continue;
        if (desc.toUpperCase() === sku.toUpperCase()) continue;   // a code is not a name
        if (/^[\d\s./-]+$/.test(desc)) continue;                  // numbers/dates are not a name
        const barcode = String(l.barcode || '').trim();
        const rec = inventory.get(sku, cid);
        if (rec) {
          const placeholder = !String(rec.name || '').trim()
            || String(rec.name).trim().toUpperCase() === sku.toUpperCase();
          const wantBar = barcode && !String(rec.barcode || '').trim();
          if (!placeholder && !wantBar) continue;
          inventory.upsert({
            sku, clientId: cid,
            name: placeholder ? desc : rec.name,
            ...(wantBar ? { barcode } : {}),
          });
          if (placeholder) healed++;
          if (wantBar) barcoded++;
        } else if (mayCreate) {
          // MARKED AS LEARNED, and that mark is load-bearing. A row invented
          // from an order passing through proves nothing about who owns the
          // SKU — and left unmarked it did real harm: orders misfiled under a
          // channel-placeholder client taught that client the SKUs, which made
          // the SKU look like it had two owners, which made attribution
          // ambiguous, which misfiled the NEXT pull the same way. A loop that
          // deepened itself every five minutes. buildSkuOwnerIndex now ignores
          // these for ownership.
          inventory.upsert({ sku, clientId: cid, name: desc, learned_from_orders: 1, ...(barcode ? { barcode } : {}) });
          created++;
        }
      }
    }
    if (!created && !healed && !barcoded) return;
    if (created && !hadMaster) {
      const list = clientProfiles(db);
      let p = list.find(x => String(x.client || '').trim().toLowerCase() === name.toLowerCase());
      if (!p) { p = { client: name, instructions: [], status: 'Deployed', createdAt: new Date().toISOString() }; list.push(p); }
      if (p.stock_tracking === undefined) {
        p.stock_tracking = false;
        p.updatedAt = new Date().toISOString();
        logAudit('catalogue_learned_tracking_off', {
          client: name, by: 'system',
          reason: 'catalogue learned from order files — quantities were never given, so stock stays untracked until switched on deliberately',
        });
      }
    }
    logAudit('catalogue_learned_from_orders', { client: name, source: source || '', created, healed, barcoded });
  } catch (e) { console.warn('[catalogue-learn]', e.message); }
}

// The work already on the books teaches it too — otherwise only the NEXT
// upload would, and the whole point is that months of live orders already
// carry the descriptions. Runs at boot (in the inventory zone, see the
// temporal-dead-zone warnings), idempotent: a second boot learns nothing new
// and logs nothing.
function backfillCataloguesFromOrders() {
  try {
    if (!inventory.available()) return;
    const db = readDb();
    const before = (db.auditLog || []).length;
    const byClient = new Map();
    for (const b of db.batches || []) {
      const c = String(b.client_name || '').trim();
      if (!c) continue;
      if (!byClient.has(c)) byClient.set(c, []);
      byClient.get(c).push(...(b.orders || []));
    }
    for (const [c, orders] of byClient) harvestCatalogueFromOrders(db, c, orders, 'backfill');
    if ((db.auditLog || []).length !== before) writeDb(db);
  } catch (e) { console.warn('[catalogue-learn] backfill:', e.message); }
}

function checkIntakeStock(clientId, orders) {
  const problems = { unknownSkus: [], shortOrders: [], okOrders: [], byOrder: {}, noItemMaster: false };
  if (!inventory.available() || !clientId) {
    problems.okOrders = (orders || []).map(o => o.order_number);
    return problems;
  }
  // NOT EVERY CLIENT'S STOCK LIVES HERE. Some are pick/pack/scan only — their
  // inventory is held in their own WMS and we were never given an item master.
  // For them "the SKU is not in the item master" is not a shortage, it is the
  // arrangement, and blocking the upload stops real work over a stock position
  // we were never asked to keep. Found the hard way: a 93-order file was
  // refused outright with "every order is short on stock" when not one line
  // was actually short — the client simply had no catalogue loaded.
  if (!clientStockTracked(clientId)) {
    problems.noItemMaster = true;
    problems.stockElsewhere = clientHasItemMaster(clientId);   // a catalogue we hold, stock they hold
    problems.okOrders = (orders || []).map(o => o.order_number);
    return problems;
  }
  const unknown = new Set();
  // Availability is a POOL: two orders for the same SKU compete for it, so the
  // check runs cumulatively rather than judging each order in isolation. A
  // per-order check would pass both and then short the second at reserve time.
  const claimed = new Map();
  for (const o of orders || []) {
    const items = (o.lines || []).filter(l => l.sku).map(l => ({ sku: l.sku, qty: Number(l.qty) || 0 }));
    const res = inventory.checkAvailability(clientId, items);
    const short = [];
    for (const u of res.unknown) unknown.add(u.sku);
    // Fold in what earlier orders in this same batch already claimed.
    for (const it of items) {
      const already = claimed.get(it.sku) || 0;
      const row = inventory.get(it.sku, clientId);
      if (!row) continue;                       // unknown is reported separately
      const free = Math.max(0, (Number(row.stock_qty) || 0) - (Number(row.reserved_qty) || 0) - already);
      if (it.qty > free) {
        const existing = short.find(x => x.sku === it.sku);
        if (existing) existing.shortfall += it.qty - free;
        else short.push({ sku: it.sku, name: row.name || '', needed: it.qty, available: free, shortfall: it.qty - free });
      }
      claimed.set(it.sku, already + it.qty);
    }
    const orderUnknown = res.unknown.map(u => u.sku);
    problems.byOrder[o.order_number] = { unknown: orderUnknown, short };
    if (orderUnknown.length || short.length) {
      problems.shortOrders.push({
        order_number: o.order_number,
        unknown: orderUnknown,
        lines: short,
        reason: orderUnknown.length && short.length ? 'unknown SKU and not enough stock'
              : orderUnknown.length ? 'SKU not in the item master' : 'not enough stock',
      });
    } else {
      problems.okOrders.push(o.order_number);
    }
  }
  problems.unknownSkus = [...unknown];
  return problems;
}

// Reserve every line of every order, record any shortfall as a backorder, and
// allocate pick bins. Returns what was reserved so the caller can stamp the
// batch and notify a connected store.
function reserveIntakeOrders(db, clientId, clientName, orders, batchId, strategy = 'fefo', stagingMode = 'wait') {
  const reservedSkus = new Set();
  if (!inventory.available() || !clientId) return { tracked: false, reservedSkus };
  let tracked = false;
  for (const order of orders || []) {
    const items = (order.lines || []).filter(l => l.sku).map(l => ({ sku: l.sku, qty: Number(l.qty) || 0 }));
    if (!items.length) continue;
    try {
      const rres = inventory.reserveOrder(clientId, { id: order.order_number, items });
      recordBackorders(db, clientName, order.order_number, batchId, rres);
      tracked = true;
      for (const it of items) reservedSkus.add(it.sku);
    } catch (e) { console.warn('[intake] reserve failed for', order.order_number, e.message); }
  }
  if (tracked) {
    try { allocatePickLocations(clientId, orders, strategy, stagingMode); } catch (e) {
      console.warn('[intake] pick allocation failed:', e.message);
    }
  }
  return { tracked, reservedSkus };
}

function allocatePickLocations(clientId, orders, strategy, stagingMode = 'wait') {
  if (!inventory.available()) return;
  // ONE LEDGER FOR THE WHOLE BATCH. allocatePick reads bin_lots and decrements
  // nothing, so without this every line plans against the full pool and two
  // orders wanting the same SKU are both sent to the same units — a pick list
  // that asks a 24-unit bin for more than it holds while another bin is never
  // visited.
  const claim = inventory.newPickClaim();
  const stagingLeft = {}; // sku -> staging units still unallocated this batch
  const stagingFor = sku => (stagingLeft[sku] !== undefined ? stagingLeft[sku] : (stagingLeft[sku] = inventory.stagingQty(clientId, sku)));
  for (const order of (orders || [])) {
    for (const l of (order.lines || [])) {
      if (!l.sku) continue;
      try {
        const upc = Number((inventory.get(l.sku, clientId) || {}).units_per_carton) || 1;
        l.units_per_carton = upc;
        const lineQty = Number(l.qty) || 0;
        // CASE-BREAK: if the order's LOOSE-piece need exceeds what's on the pick
        // face, bring whole carton(s) down from bulk to the shelf FIRST — the
        // picker collects the carton, takes the X pieces the order needs, and the
        // remainder stays on the shelf (replenished in the same trip). The eaches
        // below then allocate from the topped-up shelf.
        if (upc > 1 && lineQty > 0) {
          const looseNeed = lineQty >= upc ? (lineQty % upc) : lineQty;
          if (looseNeed > 0) {
            try {
              const br = inventory.caseBreakReplenish(clientId, l.sku, looseNeed, upc);
              if (br) l.case_break = { from: br.from, to: br.to, cartons: br.cartons, qty: br.qty, take: looseNeed, leave: Math.max(0, br.left_on_shelf) };
            } catch (_) { /* fall back to normal allocation */ }
          }
        }
        const a = inventory.allocatePick(clientId, l.sku, lineQty, strategy, upc, claim);
        // Aggregate the lot-level picks into one row per bin (preserving plan order:
        // bulk case-picks first, then pick-face eaches).
        const byLoc = []; const idx = {};
        for (const p of a.picks) {
          if (idx[p.location_id] === undefined) { idx[p.location_id] = byLoc.length; byLoc.push({ location_id: p.location_id, qty: 0, expiry_date: p.expiry_date || null, kind: p.kind }); }
          const e = byLoc[idx[p.location_id]];
          e.qty += p.qty;
          if (p.expiry_date && (!e.expiry_date || p.expiry_date < e.expiry_date)) e.expiry_date = p.expiry_date;
        }
        l.pick_locations = byLoc;
        let shortfall = a.shortfall;
        l.awaiting_putaway_qty = 0;
        if (shortfall > 0) {
          const fromStaging = Math.min(shortfall, stagingFor(l.sku));
          if (fromStaging > 0) {
            stagingLeft[l.sku] -= fromStaging;
            shortfall -= fromStaging;
            if (stagingMode === 'staging') l.pick_locations.push({ location_id: 'STAGING', qty: fromStaging, expiry_date: null });
            else l.awaiting_putaway_qty = fromStaging;
          }
        }
        l.pick_shortfall = shortfall; // whatever's left has no stock at all
      } catch (_) { /* leave line un-allocated */ }
    }
  }
}

// Bring an order's bin consumption in line with what's been SCANNED for one SKU —
// called live from every scan path so bin occupancy updates per-scan, not only at
// completion. Monotonic + reversible: scanning up consumes more from bins
// (FEFO/FIFO), a downward correction (setqty lower) returns units to their bins.
// state.bin_consumed[sku] records the exact lots taken so a return is precise.
// No-op unless the batch is inventory-tracked and the store is available.
function reconcileBinConsumption(db, batch, ord, state, sku) {
  if (!sku || !batch || !batch.inventory_tracked || !inventory.available()) return;
  const cid = batch.inventory_client || invClientId(batch.client_name);
  const strat = batch.pick_strategy || 'fefo';
  const upc = Number((inventory.get(sku, cid) || {}).units_per_carton) || 1;
  const ordered = (ord.lines || []).filter(l => l.sku === sku).reduce((s, l) => s + (Number(l.qty) || 0), 0);
  const target = Math.min(Number(state.scanned?.[sku] || 0), ordered);   // never consume beyond ordered
  state.bin_consumed = state.bin_consumed || {};
  const list = state.bin_consumed[sku] || [];
  try {
    // FROZEN plan: follow the SAME carton-aware plan the pick list already shows —
    // frozen once (from the line's pick_locations) so it never shifts as this order
    // consumes its own bins. Recomputing against depleted bins would spill units to
    // the wrong bin at completion. STAGING units aren't in a bin, so they're skipped.
    state.bin_plan = state.bin_plan || {};
    if (!state.bin_plan[sku]) {
      const agg = {}; const orderArr = [];
      for (const l of (ord.lines || []).filter(x => x.sku === sku)) {
        for (const p of (l.pick_locations || [])) {
          if (p.location_id === 'STAGING') continue;
          if (agg[p.location_id] === undefined) { agg[p.location_id] = 0; orderArr.push(p.location_id); }
          agg[p.location_id] += p.qty;
        }
      }
      if (!orderArr.length) { // no stored plan — derive one
        for (const p of inventory.allocatePick(cid, sku, ordered, strat, upc).picks) {
          if (agg[p.location_id] === undefined) { agg[p.location_id] = 0; orderArr.push(p.location_id); }
          agg[p.location_id] += p.qty;
        }
      }
      state.bin_plan[sku] = orderArr.map(loc => ({ loc, qty: agg[loc] }));
    }
    const steps = state.bin_plan[sku];
    let remT = target; const desired = {};
    for (const s of steps) { if (remT <= 0) break; const t = Math.min(remT, s.qty); desired[s.loc] = (desired[s.loc] || 0) + t; remT -= t; }
    const cur = {}; for (const e of list) cur[e.location_id] = (cur[e.location_id] || 0) + e.qty;
    const locs = new Set([...Object.keys(desired), ...Object.keys(cur)]);
    for (const loc of locs) {
      const want = desired[loc] || 0, have = cur[loc] || 0;
      if (want > have) {
        const taken = inventory.consumeFromLocation(cid, sku, loc, want - have, strat);
        for (const t of taken) list.push({ location_id: loc, lot_id: t.lot_id, qty: t.qty, expiry_date: t.expiry_date || null, received_at: t.received_at || null, lot_number: t.lot_number || '' });
      } else if (want < have) {
        let give = have - want; const back = [];
        for (let i = list.length - 1; i >= 0 && give > 0; i--) {
          if (list[i].location_id !== loc) continue;
          const take = Math.min(give, list[i].qty);
          back.push({ sku, location_id: loc, qty: take, received_at: list[i].received_at, expiry_date: list[i].expiry_date, lot_number: list[i].lot_number });
          list[i].qty -= take; give -= take;
          if (list[i].qty <= 0) list.splice(i, 1);
        }
        if (back.length) inventory.restoreLots(cid, back);
      }
    }
    state.bin_consumed[sku] = list;
  } catch (e) { console.warn('[bin-reconcile] failed for', sku, e.message); }
}

// Heads-up for the Confirm modal: how many units across this file are covered by
// STAGING (received-but-unbinned) stock rather than a bin — i.e. the units the
// "allocate from staging vs wait till binned" choice actually governs. Read-only.
function stagingDemand(clientId, orders, strategy) {
  if (!inventory.available()) return { units: 0, skus: [] };
  const demand = {}; // sku -> total ordered
  for (const o of (orders || [])) for (const l of (o.lines || [])) if (l.sku) demand[l.sku] = (demand[l.sku] || 0) + (Number(l.qty) || 0);
  const skus = [];
  let units = 0;
  for (const [sku, dem] of Object.entries(demand)) {
    const binned = inventory.binnedQty(clientId, sku);
    const staging = inventory.stagingQty(clientId, sku);
    const afterBins = Math.max(0, dem - binned);
    const fromStaging = Math.min(afterBins, staging);
    if (fromStaging > 0) { units += fromStaging; skus.push({ sku, units: fromStaging }); }
  }
  return { units, skus };
}

// ── Backorders — orders short on stock at reserve time ───────────────────────
// When an order reserves more of a SKU than was AVAILABLE (stock − reserved), the
// difference is a shortfall: the order is promised units that aren't physically
// here yet. We record that as a backorder so there's a visible "awaiting stock"
// queue, and auto-decrement it (FIFO) when matching stock arrives via an inbound
// receipt or a stock upload. This is a TRACKING layer only — it never blocks
// picking (a packer can still grab whatever is on the shelf) and never changes the
// reservation math the ZORT stock-sync depends on.
function backorders(db) { return db.backorders || (db.backorders = []); }

// A backorder is a tracking row hung off an ORDER. If that order goes away the
// backorder is meaningless and must go with it — otherwise the queue fills with
// rows pointing at nothing, which is exactly what happened: an uploaded batch
// was deleted and 335 backorders outlived their orders.
//
// Orders can disappear down several routes — Master delete, bulk approve of a
// deletion request, a client cancelling from the portal, a duplicate-order
// overwrite, a whole-batch delete, the Master reset, and the 12-month
// auto-archive. Hooking each one individually is how the gap appeared in the
// first place, so instead this RECONCILES against the live order list: any
// backorder whose order no longer exists is dropped, whatever removed it.
// Cheap (one Set build) and called on every read of the queue, so the list can
// never show a stale row again even if a future removal path forgets.
function pruneOrphanBackorders(db) {
  const list = db.backorders;
  if (!Array.isArray(list) || !list.length) return 0;
  const live = new Set();
  for (const b of db.batches || []) {
    for (const o of b.orders || []) live.add(String(o.order_number));
  }
  const before = list.length;
  const dropped = list.filter(bo => !live.has(String(bo.order_number)));
  if (!dropped.length) return 0;
  db.backorders = list.filter(bo => live.has(String(bo.order_number)));
  logAudit('backorders_pruned_orphaned', {
    count: dropped.length,
    orders: [...new Set(dropped.map(b => b.order_number))].slice(0, 200),
  });
  return before - db.backorders.length;
}
// A BACKORDER IS ONLY REAL WHILE THE WORK CANNOT BE DONE.
//
// Per the user: "if orders can be scanned, fulfilled and completed, then it's
// not considered a back order." A shortfall is recorded at UPLOAD time, from
// the system's own stock figures — which on a new account are often zero
// simply because the item master was loaded without quantities. The goods are
// on the shelf, the packer scans the order, and it ships. But nothing ever
// closed the backorder: `releaseBackorders` only fires when new stock is
// RECEIVED, so a row raised at upload outlived the order it belonged to, and
// months of that accumulate into thousands of open rows that are not real.
//
// This closes a backorder when its order is finished (or cancelled), and does
// it as a RECONCILE-ON-READ rather than a hook, for the same reason
// pruneOrphanBackorders reconciles: an order can be finished down several
// paths, and hooking each one is precisely how the original gap appeared.
function closeSettledBackorders(db) {
  const list = db.backorders;
  if (!Array.isArray(list) || !list.length) return 0;
  const settled = new Map();                 // order_number -> its final status
  for (const b of db.batches || []) {
    for (const o of b.orders || []) {
      const st = (b.orderStates || {})[o.order_number] || {};
      if (st.status === 'done' || st.status === 'unprocessed') settled.set(String(o.order_number), st.status);
    }
  }
  if (!settled.size) return 0;
  const now = new Date().toISOString();
  let closed = 0;
  const orders = new Set();
  for (const bo of list) {
    if (bo.status !== 'open') continue;
    const fate = settled.get(String(bo.order_number));
    if (!fate) continue;
    bo.status = fate === 'done' ? 'fulfilled' : 'cancelled';
    bo.remaining = 0;
    bo.closed_reason = fate === 'done' ? 'order completed' : 'order cancelled';
    bo.fulfilled_at = bo.fulfilled_at || now;
    bo.updated_at = now;
    closed++; orders.add(bo.order_number);
  }
  if (closed) {
    logAudit('backorders_closed_settled', {
      count: closed, orders: [...orders].slice(0, 200),
    });
  }
  return closed;
}

// A RESERVATION DIES WITH ITS ORDER.
//
// Reported from the floor: an order deleted in the office still showed its
// units as Reserved on the client portal — "7 reserved" against "0 orders in
// progress", a contradiction the client can see. Deleting an order removed the
// order but never released what it had reserved, so those units stayed locked
// out of `available` forever.
//
// Only ONE path released a reservation (a voided marketplace order). Orders
// disappear down at least eight routes — Master delete, single and bulk
// approval of a deletion request, portal self-cancel, duplicate overwrite,
// whole-batch delete, the Master reset, the client-data wipe and the 12-month
// archive — so this RECONCILES rather than hooking each one, exactly as
// pruneOrphanBackorders and pruneOrphanTransportJobs do, and for the same
// reason: hooking each site is precisely how the gap appeared.
function releaseOrphanReservations(db) {
  if (!inventory.available()) return 0;
  // A RESERVATION IS ONLY LEGITIMATE WHILE THE ORDER IS STILL OPEN.
  //
  // The first cut of this compared against orders that still EXIST, which
  // missed the case actually reported: an order CANCELLED in the office is
  // still on the books, so its units stayed Reserved on the client's screen
  // ("7 reserved" against "0 orders in progress") even though nobody was ever
  // going to pick it.
  //   • pending / processing → the reservation is real, leave it
  //   • unprocessed (cancelled) → nobody will pick it; give the units back
  //   • done → deductOrder already released it; anything left is stale, and
  //     releasing is safe because a done order that still holds a reservation
  //     never had its stock deducted either
  //   • gone entirely → nothing to hold it
  const live = new Set();
  for (const b of db.batches || []) {
    for (const o of b.orders || []) {
      const st = (b.orderStates || {})[o.order_number] || {};
      const status = st.status || 'pending';
      if (status === 'pending' || status === 'processing') live.add(String(o.order_number));
    }
  }
  const clients = new Set();
  for (const b of db.batches || []) if (b.client_name) clients.add(invClientId(b.client_name));
  for (const p of clientProfiles(db)) if (p.client) clients.add(invClientId(p.client));
  let released = 0;
  const freed = [];
  for (const cid of clients) {
    let open = [];
    try { open = inventory.openReservations(cid); } catch (e) { console.warn('[reservations]', cid, e.message); continue; }
    const byOrder = new Map();
    for (const r of open) {
      if (live.has(String(r.order_id))) continue;          // still open work — leave it alone
      if (!byOrder.has(r.order_id)) byOrder.set(r.order_id, []);
      byOrder.get(r.order_id).push({ sku: r.sku, qty: r.open_qty });
    }
    for (const [orderId, items] of byOrder) {
      try {
        inventory.releaseOrder(cid, { id: orderId, items });
        released += items.reduce((n, i) => n + i.qty, 0);
        freed.push(orderId);
      } catch (e) { console.warn('[reservations] release failed for', orderId, e.message); }
    }
  }
  if (released) {
    logAudit('reservations_released_orphaned', {
      units: released, orders: freed.slice(0, 200), count: freed.length,
    });
  }
  return released;
}

function recordBackorders(db, clientName, orderNumber, batchId, reserveResults) {
  const cid = invClientId(clientName);
  const list = backorders(db);
  const now = new Date().toISOString();
  let recorded = 0;
  for (const r of (reserveResults || [])) {
    if (!r || !r.ok || !(r.shortfall > 0)) continue;
    // One open backorder per (order, sku) — a re-upload updates it in place.
    let bo = list.find(x => x.order_number === orderNumber && x.sku === r.sku && x.status === 'open');
    if (bo) { bo.ordered = r.ordered; bo.shortfall = r.shortfall; bo.remaining = r.shortfall; bo.updated_at = now; }
    else {
      list.unshift({
        id: uuidv4().slice(0, 8), order_number: orderNumber, batch_id: batchId || null,
        client_name: clientName, client_id: cid, sku: r.sku,
        ordered: r.ordered, shortfall: r.shortfall, remaining: r.shortfall,
        status: 'open', created_at: now, updated_at: now, released_qty: 0,
      });
    }
    recorded++;
  }
  if (list.length > 5000) list.length = 5000; // cap
  return recorded;
}
// Stock arrived (additions = {sku: qty}) — pay down open backorders for this
// client, oldest first (FIFO), and mark them fulfilled when fully covered.
function releaseBackorders(db, clientId, additions) {
  const list = backorders(db);
  const now = new Date().toISOString();
  const fulfilled = [];
  for (const [sku, addQty] of Object.entries(additions || {})) {
    let avail = Number(addQty) || 0;
    if (avail <= 0) continue;
    // FIFO: oldest open backorders first (list is unshifted newest-first).
    const open = list.filter(b => b.client_id === clientId && b.sku === sku && b.status === 'open')
      .sort((a, b) => new Date(a.created_at) - new Date(b.created_at));
    for (const bo of open) {
      if (avail <= 0) break;
      const take = Math.min(avail, bo.remaining);
      bo.remaining -= take; bo.released_qty += take; avail -= take; bo.updated_at = now;
      if (bo.remaining <= 0) { bo.status = 'fulfilled'; bo.fulfilled_at = now; fulfilled.push(bo.id); }
    }
  }
  if (fulfilled.length) logAudit('backorders_fulfilled', { clientId, count: fulfilled.length, ids: fulfilled });
  return fulfilled;
}

// Import-time SKU normalization — convert each order line's identifier to the
// client's canonical in-house SKU. If a line arrives keyed by BARCODE (e.g. a
// ZORT feed that only carries barcodes), swap it to the in-house SKU using the
// client's item master so pick lists, scanning, stock deduction and the ZORT
// stock-push all key on one identifier. A line already keyed by in-house SKU is
// unchanged; an unrecognised code is left as-is (handled by teach/validation).
// Runs BEFORE bundle explosion so a barcode-keyed bundle resolves then explodes.
function normalizeOrderRowsToInhouseSku(rows, clientOf) {
  if (!inventory.available() || !Array.isArray(rows)) return rows;
  for (const r of rows) {
    if (!r || !r.sku) continue;
    try {
      const inhouse = inventory.resolveToInhouseSku(r.sku, clientOf(r));
      if (inhouse && inhouse !== r.sku) {
        r.source_code = r.sku;   // keep what the source (ZORT/file) sent, for reference
        r.sku = inhouse;
      }
    } catch (_) { /* inventory optional */ }
  }
  return rows;
}

// BOM explosion at import — IdealOne is the bundle master. Any order line whose
// SKU is a defined bundle for that client is REPLACED by its component lines
// (qty × qtyPerBundle), tagged from_bundle. Done once at import so everything
// downstream (pick list, scanning, deduction, reports) sees real components and
// needs no bundle awareness. `clientOf(row)` returns the owning client for a
// row. Rows are {sku, qty, ...}. No-op if inventory is unavailable.
function explodeBundleRows(rows, clientOf) {
  if (!inventory.available() || !Array.isArray(rows)) return rows;
  const out = [];
  for (const r of rows) {
    let bundle = null;
    try { bundle = r && r.sku ? inventory.getBundle(clientOf(r), r.sku) : null; } catch (_) {}
    // Only VIRTUAL bundles explode into components. A PHYSICAL kit is a real,
    // pre-built SKU on the shelf — it ships as itself, so leave the line alone.
    if (bundle && bundle.type === 'physical') bundle = null;
    if (bundle && bundle.components.length) {
      const bundleQty = Number(r.qty) || 0;
      for (const c of bundle.components) {
        out.push({ ...r, sku: c.sku, qty: bundleQty * c.qty, from_bundle: r.sku,
          description: (r.description ? '' : '') || c.sku });
      }
    } else out.push(r);
  }
  return out;
}

// Every /api/inventory route needs an explicit client. Reads take ?clientId=,
// writes take it in the body. Missing → 400 (never a 500 from the store guard).
function reqClientId(req) {
  const c = req.query?.clientId || req.body?.clientId || '';
  return String(c).trim();
}

// ── SORTING A STOCK LIST ───────────────────────────────────────────────────
// ONE implementation, used by the office list, the office export, the client
// portal's list and the client portal's export — so what someone sees on
// screen and what comes out of the spreadsheet can never be in a different
// order. Sorting a screen client-side and a file server-side is exactly how
// those two drift.
//
// A SKU REGISTERED WITH NO STOCK IS A ROW WITH 0, NEVER A MISSING ROW. It is
// part of the client's catalogue and its absence would read as "we lost it".
// `inventory.getAll()` already returns the whole catalogue; nothing here
// filters on quantity, and the export writes a numeric 0 rather than a blank.
const STOCK_SORT_KEYS = {
  sku:       r => String(r.sku || '').toUpperCase(),
  name:      r => String(r.name || '').toUpperCase(),
  available: r => Number(r.available_qty ?? r.available ?? 0),
  on_hand:   r => Number(r.stock_qty ?? r.on_hand ?? 0),
  reserved:  r => Number(r.reserved_qty ?? r.reserved ?? 0),
  moved:     r => String(r.last_movement_at || r._last_iso || ''),
};
function sortStockRows(rows, sort, dir) {
  const key = STOCK_SORT_KEYS[String(sort || '').toLowerCase()] || STOCK_SORT_KEYS.sku;
  const sign = String(dir || 'asc').toLowerCase() === 'desc' ? -1 : 1;
  return [...rows].sort((a, b) => {
    const x = key(a), y = key(b);
    if (x === y) return String(a.sku || '').localeCompare(String(b.sku || ''));  // stable tie-break
    if (typeof x === 'number' && typeof y === 'number') return (x - y) * sign;
    return String(x).localeCompare(String(y)) * sign;
  });
}

app.get('/api/inventory', requireAuth, (req, res) => {
  const clientId = reqClientId(req);
  if (!clientId) return res.status(400).json({ error: 'clientId query param is required' });
  const { category, search, lowStock, sort, dir } = req.query;
  const rows = inventory.getAll({ category, search, lowStock: lowStock === 'true', clientId });
  res.json(sortStockRows(rows, sort, dir));
});

// Office stock export. Registered BEFORE the /:sku routes — Express matches in
// order and ":sku" would otherwise swallow "export" (the same rule the
// transport routes document).
app.get('/api/inventory/export', requireAuth, (req, res) => {
  const clientId = reqClientId(req);
  if (!clientId) return res.status(400).json({ error: 'clientId query param is required' });
  const { category, search, lowStock, sort, dir } = req.query;
  let rows = [];
  let lastMove = new Map();
  try {
    rows = inventory.getAll({ category, search, lowStock: lowStock === 'true', clientId });
    lastMove = inventory.lastMovementBySku(clientId);
  } catch (e) { return res.status(503).json({ error: 'Inventory store unavailable' }); }
  const now = Date.now();
  rows = rows.map(r => {
    const last = lastMove.get(r.sku) || r.first_added_at || null;
    const iso = last ? String(last).replace(' ', 'T') + (String(last).endsWith('Z') ? '' : 'Z') : null;
    return { ...r, _last_iso: iso, _days: iso ? Math.floor((now - new Date(iso).getTime()) / 86400000) : null };
  });
  rows = sortStockRows(rows, sort, dir);
  const stamp = new Date().toLocaleString('en-GB', { timeZone: 'Asia/Singapore' });
  const aoa = [
    [`${clientId} — Stock on hand`],
    [`Position as at ${stamp} SGT`],
    [`Sorted by ${STOCK_SORT_KEYS[String(sort || '').toLowerCase()] ? sort : 'sku'} ${String(dir || 'asc').toLowerCase() === 'desc' ? 'descending' : 'ascending'}`],
    ['Every SKU in this client\u2019s item master is listed. One with no stock shows 0 \u2014 it is not left out.'],
    [],
    ['SKU', 'Product', 'Barcode', 'Brand', 'Category', 'UOM', 'On hand', 'Reserved', 'Available',
     'Reorder point', 'Status', 'Last movement', 'Days since movement'],
    ...rows.map(r => [
      r.sku, r.name || '', r.barcode || '', r.brand || '', r.category || '', r.uom || '',
      Number(r.stock_qty) || 0, Number(r.reserved_qty) || 0, Number(r.available_qty) || 0,
      r.reorder_point ?? 10,
      (Number(r.available_qty) || 0) <= 0 ? 'Out of stock'
        : ((Number(r.available_qty) || 0) <= (r.reorder_point ?? 10) ? 'Low' : 'OK'),
      r._days === null ? 'never moved' : (r._days === 0 ? 'today' : `${r._days}d ago`),
      r._days === null ? '' : r._days,
    ]),
    [], ['TOTAL', '', '', '', '', '',
      rows.reduce((s2, r) => s2 + (Number(r.stock_qty) || 0), 0),
      rows.reduce((s2, r) => s2 + (Number(r.reserved_qty) || 0), 0),
      rows.reduce((s2, r) => s2 + (Number(r.available_qty) || 0), 0)],
  ];
  const ws = XLSX.utils.aoa_to_sheet(aoa);
  ws['!cols'] = [{ wch: 24 }, { wch: 40 }, { wch: 16 }, { wch: 14 }, { wch: 14 }, { wch: 8 },
    { wch: 9 }, { wch: 10 }, { wch: 10 }, { wch: 13 }, { wch: 13 }, { wch: 15 }, { wch: 20 }];
  const wb = XLSX.utils.book_new();
  XLSX.utils.book_append_sheet(wb, ws, 'Stock');
  const safe = String(clientId).replace(/[^A-Za-z0-9_-]+/g, '_');
  res.setHeader('Content-Type', 'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet');
  res.setHeader('Content-Disposition', `attachment; filename="Stock_${safe}_${sgDateStr()}.xlsx"`);
  res.send(XLSX.write(wb, { type: 'buffer', bookType: 'xlsx' }));
});
app.get('/api/inventory/stats', requireAuth, (req, res) => {
  const clientId = reqClientId(req);
  if (!clientId) return res.status(400).json({ error: 'clientId query param is required' });
  res.json(inventory.getStats({ clientId }));
});
// Warehouse-wide landing view of the Inventory tab — capacity/occupancy,
// who's storing what, and by commodity. NOT client-scoped on purpose (every
// other inventory read requires a clientId); this is the 3PL operator's own
// view of their shed, so it deliberately spans all clients.
app.get('/api/inventory/overview', requireAuth, (req, res) => {
  if (!inventory.available()) return res.status(503).json({ error: 'Inventory store unavailable' });
  const data = inventory.warehouseOverview();
  if (!data) return res.status(503).json({ error: 'Inventory store unavailable' });
  res.json(data);
});
app.get('/api/inventory/velocity', requireAuth, (req, res) => {
  const clientId = reqClientId(req);
  if (!clientId) return res.status(400).json({ error: 'clientId query param is required' });
  const limit = Math.min(Number(req.query.limit) || 20, 50);
  res.json(inventory.velocity(clientId, limit));
});
app.post('/api/inventory/import', requireAuth, express.json(), (req, res) => {
  const { items = [], mode = 'upsert', clientId } = req.body || {};
  const cid = String(clientId || '').trim();
  if (!cid) return res.status(400).json({ error: 'clientId is required' });
  if (!Array.isArray(items)) return res.status(400).json({ error: 'items must be an array' });
  let imported = 0, skipped = 0; const errors = [];
  if (mode === 'replace') { try { inventory.getAll({ clientId: cid }).forEach(r => inventory.remove(r.sku, cid)); } catch (_) {} }
  for (const it of items) {
    try { inventory.upsert({ ...it, clientId: cid }); imported++; }
    catch (e) { skipped++; errors.push({ sku: it && it.sku, error: e.message }); }
  }
  res.json({ imported, skipped, errors });
});
app.post('/api/inventory/seed', requireAuth, (req, res) => {
  const cid = String(req.body?.clientId || '').trim();
  if (!cid) return res.status(400).json({ error: 'clientId is required' });
  const n = inventory.seedFromSkuMap(cid, _skuDescMap);
  res.json({ seeded: n, total: inventory.getAll({ clientId: cid }).length });
});

// Stock upload — the Inventory tab's file loader. Accepts CSV or XLSX with
// columns sku, name (optional), stock_qty (aliases qty/quantity/stock/on_hand).
// mode 'add' (default) ADDS the uploaded qty to current on-hand (a receiving/
// restock); mode 'set' makes it the exact on-hand (a stocktake). clientId is
// required (all stock is client-owned). If push_to_zort is set, the affected
// SKUs' new available levels are enqueued to that client's ZORT stock-sync
// store(s) after the load.
// ── UNDO AN UPLOAD MADE BEFORE THE TRANSACTION RECORD EXISTED ───────────────
// Per the user: staff loaded stock here bypassing Inbound, and that already
// happened — a fix that only covers FUTURE uploads does not answer the
// question. Those uploads left `type='upload'` movements carrying the delta per
// SKU, so the ledger says what to give back. Read-only listing; the undo is
// admin-or-master and confirmed.
app.get('/api/inventory/ledger-uploads', (req, res) => {
  const cid = String(req.query.clientId || '').trim();
  if (!cid) return res.status(400).json({ error: 'clientId is required' });
  if (!inventory.available()) return res.status(400).json({ error: 'Inventory store unavailable' });
  const _db = readDb();
  const dismissed = _db.dismissedLedgerUploads || {};
  const undone = _db.undoneLedgerPostings || {};
  res.json({ rows: inventory.ledgerUploads(cid, { days: Number(req.query.days) || 30 })
    .filter(r => !dismissed[`${cid}|${r.kind}|${r.key}`] && !dismissed[`${cid}|${r.key}`])
    // Already given back — shown, but as history, so nobody takes it off twice.
    .map(r => ({ ...r, undone: undone[`${cid}|${r.kind}|${r.key}`] || null })) });
});

app.post('/api/inventory/ledger-uploads/undo', express.json(), (req, res) => {
  if (!requireInboundAdmin(req, res)) return;
  const cid = String(req.body?.clientId || '').trim();
  const kind = String(req.body?.kind || 'upload').trim();
  const key = String(req.body?.key || req.body?.minute || '').trim();
  if (!cid || !key) return res.status(400).json({ error: 'clientId and key are required' });
  // ── ONCE PER POSTING ─────────────────────────────────────────────────────
  // Reported live: both postings were backed off one after the other and the
  // client's on-hand landed on ZERO. Each undo was individually correct — it
  // gave back exactly what its own posting added — but nothing stopped the
  // second one, and nothing said the first had already happened. A posting can
  // only be given back once; asking again is refused with when and by whom.
  if (kind !== 'takeoff') {
    const seen = (readDb().undoneLedgerPostings || {})[`${cid}|${kind}|${key}`];
    if (seen) {
      return res.status(409).json({
        error: `That posting was already taken back off on ${String(seen.at).slice(0, 16).replace('T', ' ')}`
          + `${seen.by ? ` by ${seen.by}` : ''} (${seen.units} pc(s)). Giving it back twice would remove stock that was only ever booked once.`,
        alreadyUndone: seen,
      });
    }
  }
  if (String(req.body?.confirm || '') !== 'yes') return res.status(409).json({ needsConfirm: true });
  const who = req.userId || _tokenUserId(req) || '';
  let out;
  try {
    out = inventory.reverseLedgerUpload(cid, { kind, key }, {
      operator: who,
      reason: kind === 'takeoff' ? `stock put back on (reversing: ${key})`
            : kind === 'inbound' ? `stock of ${key} backed out (booked twice)`
            : `stock upload of ${key} undone`,
    });
  } catch (e) { return res.status(400).json({ error: e.message }); }
  logAudit('inventory_upload_undone_from_ledger', {
    clientId: cid, kind, key, minute: kind === 'upload' ? key : undefined,
    skus: out.skus, units: out.units,
    floored: out.floored.length, createdSkus: (out.created || []).map(x => x.sku).slice(0, 50), by: who,
  });
  // THE UNDO IS ITSELF UNDOABLE, and listed as such. That is the way back from
  // the zero the floor landed on.
  const db = readDb();
  db.undoneLedgerPostings = db.undoneLedgerPostings || {};
  if (kind === 'takeoff') {
    // PUTTING A TAKE-OFF BACK RE-ARMS THE POSTING IT UNDID — the key is written
    // into the reason, which is the only record a pre-snapshot take-off left.
    // Without this the stock returns but the posting stays marked as
    // given-back, and the correction is a dead end.
    const m = /^stock upload of (.+) undone$/.exec(key) || /^stock of (.+) backed out/.exec(key);
    if (m) {
      const of = /^stock upload of /.test(key) ? 'upload' : 'inbound';
      delete db.undoneLedgerPostings[`${cid}|${of}|${m[1]}`];
    }
  } else {
    db.undoneLedgerPostings[`${cid}|${kind}|${key}`] = { at: new Date().toISOString(), by: who, units: out.units };
  }
  let undoTxnId = null;
  if (kind !== 'takeoff' && out.snapshot && (out.snapshot.skus || []).length) {
    db.stockImports = db.stockImports || [];
    undoTxnId = uuidv4();
    db.stockImports.unshift({
      id: undoTxnId, hash: `undo:${cid}|${kind}|${key}`, clientId: cid,
      filename: kind === 'inbound' ? `undo of ${key}` : `undo of the upload of ${key}`,
      at: new Date().toISOString(), by: who, mode: 'add', source: 'ledger-undo',
      lines: out.skus, units: out.units, snapshot: out.snapshot,
      undo_of: { kind, key },
      reversible_until: new Date(Date.now() + STOCK_IMPORT_REVERSE_HOURS * 3600000).toISOString(),
    });
    pruneStockImportSnapshots(db);
  }
  writeDb(db);
  zortNotifyStockChange(db, cid, []);
  res.json({
    ok: true, undoTxnId, ...out,
    note: (kind === 'takeoff' ? `Put ${out.units} pc(s) back on ${out.skus} SKU(s).` : `Took ${out.units} pc(s) back off ${out.skus} SKU(s).`)
      + (kind === 'inbound' ? ' The receipt itself, its GRN and its trail are untouched — only the stock posting was backed out.' : '')
      + (kind === 'takeoff' ? ' The posting it came from is available to take off again.' : ' This can be put back for 3 days from the same list.')
      + (out.floored.length ? ` ${out.floored.length} SKU(s) no longer held all of it — something shipped since, so those floored at what was there.` : '')
      + ((out.created || []).length ? ` ${(out.created || []).length} SKU(s) were CREATED by that upload and carry no movement row, so their quantity could not be worked out from the ledger — they are listed for you to set by hand.` : ''),
  });
});

app.post('/api/inventory/import-file', upload.single('file'), tenantMiddleware, (req, res) => {
  if (!req.file) return res.status(400).json({ error: 'No file uploaded' });
  const cid  = String(req.body?.clientId || '').trim();
  if (!cid) return res.status(400).json({ error: 'clientId is required (which client owns this stock?)' });
  const mode = String(req.body?.mode || 'add').toLowerCase() === 'set' ? 'set' : 'add';
  const pushToZort = String(req.body?.push_to_zort || '') === 'true' || req.body?.push_to_zort === true;
  if (!inventory.available()) return res.status(400).json({ error: 'Inventory store unavailable' });

  const buf = req.file.buffer;
  const name = (req.file.originalname || '').toLowerCase();
  let rows = [];
  try {
    const isXlsx = buf.length > 3 && buf[0] === 0x50 && buf[1] === 0x4b;
    const isXls  = buf.length > 7 && buf[0] === 0xd0 && buf[1] === 0xcf;
    if (isXlsx || isXls || name.endsWith('.xlsx') || name.endsWith('.xls')) {
      const wb = XLSX.read(buf, { type: 'buffer' });
      rows = XLSX.utils.sheet_to_json(wb.Sheets[wb.SheetNames[0]], { defval: '' })
        .map(r => { const o = {}; for (const [k, v] of Object.entries(r)) o[String(k).trim().toLowerCase().replace(/[^a-z0-9]/g, '')] = v; return o; });
    } else {
      const text = buf.toString('utf8').replace(/^﻿/, '');
      const lines = text.split(/\r?\n/).filter(l => l.trim());
      if (!lines.length) return res.status(400).json({ error: 'Empty file.' });
      const delim = (lines[0].includes(';') && !lines[0].includes(',')) ? ';' : ',';
      const cols = lines[0].split(delim).map(c => c.trim().toLowerCase().replace(/[^a-z0-9]/g, ''));
      rows = lines.slice(1).map(line => {
        const cells = line.split(delim); const o = {};
        cols.forEach((c, i) => { o[c] = (cells[i] || '').trim(); });
        return o;
      });
    }
  } catch (e) {
    return res.status(400).json({ error: 'Could not parse file: ' + e.message });
  }

  const qtyOf = r => Number(r.stockqty ?? r.qty ?? r.quantity ?? r.stock ?? r.onhand ?? r.available ?? 0) || 0;
  let applied = 0, skipped = 0; const errors = []; const affected = new Set();
  const additions = {}; // sku -> positive stock increase (for backorder release)
  // ── AN UPLOAD NOBODY CAN UNDO IS A TRAP ──────────────────────────────────
  // Reported: staff put stock straight in here instead of receiving it through
  // Inbound, and there was no way back — this route kept no snapshot and no
  // transaction record, only an audit line with counts. The mass putaway upload
  // has had a 3-day reversal all along; this one, which is the easier of the
  // two to reach by accident, had nothing. Same treatment, same window, same
  // Reverse button.
  const beforeStock = new Map();   // sku -> on-hand before (null = SKU did not exist)
  for (let i = 0; i < rows.length; i++) {
    const r = rows[i];
    const sku = String(r.sku ?? r.skucode ?? r.itemcode ?? '').trim();
    if (!sku) { skipped++; continue; }
    const qty = qtyOf(r);
    const nm  = String(r.name ?? r.description ?? sku).trim() || sku;
    try {
      const existing = inventory.get(sku, cid);
      if (!beforeStock.has(sku)) beforeStock.set(sku, existing ? Number(existing.stock_qty) || 0 : null);
      if (mode === 'set') {
        const delta = qty - (existing ? existing.stock_qty : 0);
        inventory.upsert({ sku, name: nm, clientId: cid, stock_qty: qty });
        if (delta > 0) additions[sku] = (additions[sku] || 0) + delta;
      } else { // add
        if (!existing) { inventory.upsert({ sku, name: nm, clientId: cid, stock_qty: qty }); if (qty > 0) additions[sku] = (additions[sku] || 0) + qty; }
        else if (qty !== 0) { inventory.adjust(sku, cid, qty, 'upload', 'Stock upload'); if (qty > 0) additions[sku] = (additions[sku] || 0) + qty; }
      }
      applied++; affected.add(sku);
    } catch (e) { skipped++; errors.push({ row: i + 2, sku, error: e.message }); }
  }
  // Uploaded stock can satisfy orders waiting on it → pay down backorders (FIFO).
  if (Object.keys(additions).length) {
    const bdb = readDb();
    releaseBackorders(bdb, cid, additions);
    writeDb(bdb);
  }

  let pushed = 0;
  if (pushToZort && affected.size) {
    const db = readDb();
    const before = (db.zortOutbox || []).length;
    zortNotifyStockChange(db, cid, [...affected]);
    pushed = ((readDb().zortOutbox || []).length) - before;
  }
  // The reversal record. `cells: []` because this route writes on-hand figures
  // directly and never touches bins — reverseStockPositions restores exactly
  // what it finds, so one implementation covers both kinds of upload.
  let txnId = null;
  if (beforeStock.size) {
    const rdb = readDb();
    rdb.stockImports = rdb.stockImports || [];
    txnId = uuidv4();
    rdb.stockImports.unshift({
      id: txnId, hash: `inv:${txnId}`, clientId: cid,
      filename: req.file.originalname || 'stock upload',
      at: new Date().toISOString(), by: req.userId || _tokenUserId(req) || '',
      mode, source: 'inventory', lines: applied,
      units: [...beforeStock.keys()].reduce((n, sku) => {
        const it = inventory.get(sku, cid); return n + (Number(it?.stock_qty) || 0);
      }, 0),
      snapshot: {
        at: new Date().toISOString(), cells: [],
        skus: [...beforeStock.entries()].map(([sku, before_stock]) => ({ sku, before_stock })),
        // TAKEN AFTER THE WRITES, not before — the ledger mark says "where
        // things stood when this import FINISHED", so that a later check for
        // "has anything moved since" does not count the import's own rows and
        // refuse to undo itself. (setStockPositions does the same; taking it
        // early made every undo ask to skip every SKU.)
        asOfMovementId: inventory.movementHighWater(),
      },
      reversible_until: new Date(Date.now() + STOCK_IMPORT_REVERSE_HOURS * 3600000).toISOString(),
    });
    pruneStockImportSnapshots(rdb);
    if (rdb.stockImports.length > 500) rdb.stockImports.length = 500;
    writeDb(rdb);
  }
  logAudit('inventory_stock_uploaded', { clientId: cid, mode, applied, skipped, pushedToZort: pushToZort, by: req.userId || '', txnId });
  res.json({ applied, skipped, mode, clientId: cid, pushedToZort: pushToZort, enqueued: pushed,
             txnId, reversibleHours: STOCK_IMPORT_REVERSE_HOURS, errors: errors.slice(0, 20) });
});

// ── Backorders — the "awaiting stock" queue ──────────────────────────────────
// Read by any signed-in internal user (warehouse cares "what am I waiting on").
app.get('/api/backorders', requireAuth, (req, res) => {
  const db = readDb();
  backorders(db);
  // Reconcile before answering, so the queue can never show a row whose order
  // has been deleted — whichever route removed it.
  const pruned = pruneOrphanBackorders(db);
  // …and never a row for an order that has since been picked and shipped. A
  // job that can be scanned and completed is not awaiting stock.
  const closed = closeSettledBackorders(db);
  if (pruned || closed) writeDb(db);
  const list = db.backorders;
  const status = req.query.status || 'open';
  const rows = (status === 'all' ? list : list.filter(b => b.status === status)).slice(0, 500);
  res.json({ open: list.filter(b => b.status === 'open').length, backorders: rows, pruned, closed });
});
// Manually clear a backorder (e.g. the order was cancelled, or resolved offline).
app.post('/api/backorders/:id/resolve', express.json(), requireAuth, (req, res) => {
  const db = readDb();
  const bo = backorders(db).find(x => x.id === req.params.id);
  if (!bo) return res.status(404).json({ error: 'Not found' });
  bo.status = 'resolved'; bo.remaining = 0; bo.resolved_at = new Date().toISOString(); bo.resolved_by = req.userId || '';
  writeDb(db);
  logAudit('backorder_resolved', { id: bo.id, order: bo.order_number, sku: bo.sku, by: req.userId || '' });
  res.json(bo);
});

// ── Product Master (ULD_Product_Master_Template.xlsx) ────────────────────────
const productMaster = require('./lib/product-master');

app.get('/api/inventory/product-master-template', requireAuth, (req, res) => {
  const buf = productMaster.buildProductMasterTemplateXlsx();
  res.setHeader('Content-Type', 'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet');
  res.setHeader('Content-Disposition', 'attachment; filename="Product_Master_Template.xlsx"');
  res.send(buf);
});

app.post('/api/inventory/import-product-master', upload.single('file'), tenantMiddleware, (req, res) => {
  if (!req.file) return res.status(400).json({ error: 'No file uploaded' });
  const cid = String(req.body?.clientId || '').trim();
  if (!cid) return res.status(400).json({ error: 'clientId is required (which client owns this stock?)' });
  let rawRows;
  try {
    const wb = XLSX.read(req.file.buffer, { type: 'buffer' });
    const sheetName = wb.SheetNames.find(n => /product master/i.test(n)) || wb.SheetNames[0];
    rawRows = XLSX.utils.sheet_to_json(wb.Sheets[sheetName], { defval: '' });
  } catch (e) {
    return res.status(400).json({ error: 'Could not read the file: ' + e.message });
  }
  const { rows, skipped } = productMaster.parseProductMasterRows(rawRows);
  let imported = 0;
  const errors = skipped.map(s => ({ row: s.row, error: s.reason }));
  for (const row of rows) {
    try { inventory.upsert({ ...row, clientId: cid }); imported++; }
    catch (e) { errors.push({ row: row.sku, error: e.message }); }
  }
  logAudit('product_master_imported', { imported, skipped: skipped.length, clientId: cid, by: req.userId || '' });
  // IS THERE A STORE THAT CARRIES THIS CLIENT? Only then is there anything to
  // offer. The push itself is NOT fired here — the operator is asked first,
  // because sending a catalogue outward is their decision, not a side effect of
  // loading a spreadsheet.
  let storeOffer = null;
  try {
    const st = zortStoresForClient(readDb(), cid, { requireStockSync: false })[0];
    if (st && imported) storeOffer = { storeId: st.id, storeName: st.clientName || st.storename || 'the store', skus: imported };
  } catch (_) { /* no store, nothing to offer */ }
  res.json({ imported, skipped: skipped.length, errors, storeOffer });
});
app.post('/api/inventory', requireAuth, express.json(), (req, res) => {
  try {
    const body = req.body || {};
    if (!String(body.clientId || '').trim()) return res.status(400).json({ error: 'clientId is required' });
    res.status(201).json(inventory.upsert(body));
  } catch (e) { res.status(400).json({ error: e.message }); }
});
app.get('/api/inventory/:sku/movements', requireAuth, (req, res) => {
  const clientId = reqClientId(req);
  if (!clientId) return res.status(400).json({ error: 'clientId query param is required' });
  res.json(inventory.movements(req.params.sku, clientId, Number(req.query.limit) || 50));
});
// ── ADJUST A STOCK QUANTITY BY HAND ────────────────────────────────────────
// Correcting a count, writing off a loss, or putting test data back. Per the
// user: the Administrator password and a reason, every time.
//
// It used to take any signed-in user, an optional reason, and — the real gap —
// it wrote NOTHING to the audit log. The movement landed in stock_movements,
// so the number changed, but nothing said WHO changed it or WHY. A hand
// adjustment is the one stock change with no document behind it (no receipt,
// no order), so it is the one that most needs a name against it.
app.post('/api/inventory/:sku/adjust', requireAuth, express.json(), (req, res) => {
  const { qty, type = 'adjustment', reason = '', clientId } = req.body || {};
  const cid = String(clientId || '').trim();
  if (!cid) return res.status(400).json({ error: 'clientId is required' });
  if (qty === undefined || Number.isNaN(Number(qty))) return res.status(400).json({ error: 'qty (number) is required' });
  // A length floor is a blunt instrument, but it blocks the classic
  // non-reasons — "oops", "test", "fix", "adj" — while "recount" and
  // "damaged" pass. Nothing can judge whether a reason is TRUE; this only
  // stops the box being waved through empty.
  const why = String(reason || '').trim();
  if (why.length < 6) {
    return res.status(400).json({ error: 'Give a real reason for this adjustment — it goes on the audit trail and is the only record of why the number changed.' });
  }
  // Admin's own password, or the Administrator key. 403 and never 401: the
  // session is valid, only this second check failed, and a 401 would trip the
  // client's session-expired handler and force a reload.
  const auth = verifyAdminReconfirm(req, { role: 'admin' });
  if (auth.error) return res.status(auth.code === 401 ? 403 : auth.code).json({ error: auth.error });

  const before = inventory.get(req.params.sku, cid);
  if (!before) return res.status(404).json({ error: `${req.params.sku} is not in ${cid}'s item master.` });
  try {
    const result = inventory.adjust(req.params.sku, cid, Number(qty), type, why);
    logAudit('inventory_adjusted', {
      sku: req.params.sku, clientId: cid, delta: Number(qty),
      from: Number(before.stock_qty) || 0, to: Number(result?.stock_qty ?? 0),
      movement: String(type || 'adjustment'), reason: why.slice(0, 200),
      viaMaster: !!auth.viaMaster, by: req.userId || '',
    });
    zortNotifyStockChange(readDb(), cid, [req.params.sku]);
    res.json({ ...result, from: Number(before.stock_qty) || 0, reason: why });
  }
  catch (e) { res.status(400).json({ error: e.message }); }
});

// ── Bundles / BOM (IdealOne is the master) — registered BEFORE /:sku so
// "bundles" isn't swallowed as a SKU param. Availability is DERIVED from
// component stock and pushed to any ZORT stock-sync store for the client.
app.get('/api/inventory/bundles', requireAuth, (req, res) => {
  const clientId = reqClientId(req);
  if (!clientId) return res.status(400).json({ error: 'clientId query param is required' });
  const bundles = inventory.getBundles(clientId).map(b => ({ ...b, available: inventory.bundleAvailable(clientId, b.bundle_sku) }));
  res.json(bundles);
});
app.post('/api/inventory/bundles', requireAuth, express.json(), (req, res) => {
  try {
    const { clientId, bundle_sku, name, components, type } = req.body || {};
    const cid = String(clientId || '').trim();
    if (!cid) return res.status(400).json({ error: 'clientId is required' });
    const bundle = inventory.upsertBundle(cid, bundle_sku, name, components, type);
    logAudit('bundle_upsert', { clientId: cid, bundle: bundle.bundle_sku, bundleType: bundle.type, components: bundle.components.length, by: req.userId || '' });
    // Only a virtual bundle's availability tracks its components; a physical
    // kit's sellable number is its own (built) stock.
    if (bundle.type === 'virtual') zortNotifyStockChange(readDb(), cid, bundle.components.map(c => c.sku));
    res.json({ ...bundle, available: inventory.bundleAvailable(cid, bundle.bundle_sku) });
  } catch (e) { res.status(400).json({ error: e.message }); }
});
// PHYSICAL KITTING — build N units: consume components, inbound the bundle SKU
// as real stock, then sync both the consumed components AND the new bundle
// stock up to ZORT.
app.post('/api/inventory/bundles/:sku/build', requireAuth, express.json(), (req, res) => {
  try {
    const cid = String(req.body?.clientId || '').trim();
    if (!cid) return res.status(400).json({ error: 'clientId is required' });
    const result = inventory.buildBundle(cid, req.params.sku, req.body?.qty);
    logAudit('bundle_built', { clientId: cid, bundle: req.params.sku, built: result.built, by: req.userId || '' });
    // Components dropped, the kit SKU rose — push all of them to ZORT.
    zortNotifyStockChange(readDb(), cid, [req.params.sku, ...result.consumed.map(c => c.sku)]);
    res.json({ ok: true, ...result });
  } catch (e) { res.status(400).json({ error: e.message }); }
});
app.delete('/api/inventory/bundles/:sku', requireAuth, (req, res) => {
  const clientId = reqClientId(req);
  if (!clientId) return res.status(400).json({ error: 'clientId query param is required' });
  inventory.deleteBundle(clientId, req.params.sku);
  logAudit('bundle_deleted', { clientId, bundle: req.params.sku, by: req.userId || '' });
  res.json({ ok: true });
});

// NOTE: the single-segment /api/inventory/:sku GET/PUT/DELETE routes are
// registered LAST (just below the analytics routes) — they would otherwise
// shadow every specific single-segment route here (locations, suppliers,
// reorder-suggestions, alerts), matching them as :sku='locations' etc. Express
// matches in registration order, so all named routes must precede :sku.

// ── Warehouse Locations & Stock Distribution ────────────────────────────────
app.get('/api/inventory/locations', requireAuth, (req, res) => {
  res.json(inventory.getLocations({
    zone: req.query.zone,
    active: req.query.active !== 'false'
  }));
});
app.post('/api/inventory/locations', requireAuth, express.json(), (req, res) => {
  try {
    const { zone, aisle, shelf, bin, capacity, environment, length_cm, width_cm, height_cm, kind } = req.body || {};
    if (!zone || !aisle || !shelf || !bin) return res.status(400).json({ error: 'zone, aisle, shelf, bin required' });
    let loc = inventory.createLocation(zone, aisle, shelf, bin, capacity, environment);
    // Physical dimensions + role (optional) are set via updateLocation so
    // createLocation's signature stays stable.
    if (length_cm || width_cm || height_cm || capacity || kind) {
      loc = inventory.updateLocation(loc.location_id, { length_cm, width_cm, height_cm, capacity, environment, kind });
    }
    logAudit('warehouse_location_created', { location: `${zone}-${aisle}-${shelf}-${bin}`, capacity, environment, by: req.userId || '' });
    res.status(201).json(loc);
  } catch (e) { res.status(400).json({ error: e.message }); }
});
// ── Warehouse setup: bulk bin locations ─────────────────────────────────────
// Blank spreadsheet for setting up (or re-mapping) racking. Downloading,
// filling in and re-uploading is the round trip; re-uploading an edited copy
// UPDATES the bins it names, so this doubles as a bulk edit.
app.get('/api/inventory/locations/template', requireAuth, (req, res) => {
  const headers = ['zone', 'aisle', 'shelf', 'bin', 'capacity', 'environment', 'kind', 'length_cm', 'width_cm', 'height_cm', 'active'];
  const sample = [
    ['A', '01', '01', '01', 1000, 'dry',    'pick', 120, 80, 150, 'yes'],
    ['A', '01', '01', '02', 1000, 'dry',    'pick', 120, 80, 150, 'yes'],
    ['B', '01', '01', '01', 5000, 'dry',    'bulk', 240, 120, 200, 'yes'],
    ['C', '01', '01', '01', 800,  'chilled','pick', 120, 80, 150, 'yes'],
  ];
  const notes = [
    ['Bin locations — upload guide'], [],
    ['zone / aisle / shelf / bin', 'Together these form the bin id (e.g. A-01-01-01). All four required.'],
    ['capacity', 'Max units the bin holds. Blank keeps the current value (default 1000 for new bins).'],
    ['environment', 'dry / chilled / frozen — whatever your site uses.'],
    ['kind', 'pick = pick face, bulk = reserve/overstock. Defaults to pick.'],
    ['length_cm / width_cm / height_cm', 'Physical bin size. Optional.'],
    ['active', 'yes/no. Blank keeps the current setting; new bins default to active.'], [],
    ['Re-uploading an edited sheet UPDATES existing bins (matched on the bin id) and creates any new ones.'],
    ['Nothing is ever deleted by an upload — deactivate a bin with active = no instead.'],
  ];
  const wb = XLSX.utils.book_new();
  XLSX.utils.book_append_sheet(wb, XLSX.utils.aoa_to_sheet([headers, ...sample]), 'Locations');
  XLSX.utils.book_append_sheet(wb, XLSX.utils.aoa_to_sheet(notes), 'Instructions');
  const buf = XLSX.write(wb, { type: 'buffer', bookType: 'xlsx' });
  res.setHeader('Content-Type', 'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet');
  res.setHeader('Content-Disposition', 'attachment; filename="IDEALONE_Bin_Locations_Template.xlsx"');
  res.send(buf);
});

// multer strips the tenant context (see the note on every other multipart
// route), so tenantMiddleware is re-applied after upload.single().
app.post('/api/inventory/locations/import-file', upload.single('file'), tenantMiddleware, (req, res) => {
  if (!req.file) return res.status(400).json({ error: 'No file uploaded' });
  if (!inventory.available()) return res.status(503).json({ error: 'Inventory store unavailable' });
  try {
    const ext = path.extname(req.file.originalname || '').toLowerCase();
    let records;
    if (ext === '.csv') {
      records = parse(req.file.buffer.toString('utf8'), { columns: true, skip_empty_lines: true, trim: true, bom: true });
    } else {
      const wb = XLSX.read(req.file.buffer, { type: 'buffer' });
      const ws = wb.Sheets[wb.SheetNames[0]];
      records = XLSX.utils.sheet_to_json(ws, { defval: '' });
    }
    // normalise header names ("Zone", "AISLE ", "Length (cm)" → zone/aisle/length_cm)
    const rows = records.map(r => {
      const o = {};
      for (const k of Object.keys(r)) {
        let n = normalizeKey(k);
        if (n === 'length' || n === 'length_cm' || n === 'l_cm') n = 'length_cm';
        if (n === 'width'  || n === 'width_cm'  || n === 'w_cm' || n === 'breadth' || n === 'b_cm') n = 'width_cm';
        if (n === 'height' || n === 'height_cm' || n === 'h_cm') n = 'height_cm';
        if (n === 'max_units' || n === 'cap') n = 'capacity';
        if (n === 'env' || n === 'temperature' || n === 'temp') n = 'environment';
        if (n === 'type' || n === 'bin_kind') n = 'kind';
        if (n === 'location' || n === 'location_id' || n === 'locationid' || n === 'bin_id') n = 'location_id';
        o[n] = r[k];
      }
      return o;
    }).filter(r => String(r.location_id || '').trim() || String(r.zone || '').trim() || String(r.aisle || '').trim() || String(r.bin || '').trim());
    if (!rows.length) return res.status(400).json({ error: 'No location rows found — the sheet needs zone, aisle, shelf and bin columns.' });
    const result = inventory.bulkUpsertLocations(rows);
    logAudit('warehouse_locations_imported', {
      filename: req.file.originalname || '', created: result.created, updated: result.updated,
      skipped: result.skipped, by: req.userId || '',
    });
    res.json(result);
  } catch (e) { res.status(400).json({ error: e.message }); }
});

// Fast path for regular racking: generate a block of bins from ranges instead
