// ── Daily replenishment runs ────────────────────────────────────────────────
// A run is a per-client, per-SGT-day snapshot of what each pick face needs. It's
// GENERATED DAILY (scheduler below) so there's a standing task the user can act
// on or skip. Acting is optional; a run is never carried forward — each day is
// recomputed from CURRENT state, so anything still short simply reappears in the
// new day's run with fresh numbers, and anything since satisfied drops off.
function replenishmentRuns(db) { return db.replenishmentRuns || (db.replenishmentRuns = []); }
function generateReplenishmentRun(db, clientId, day, daysCover = 7) {
  const items = inventory.replenishmentSuggestions(clientId, { daysCover, lookbackDays: 28 }).map(x => ({ ...x, applied: false }));
  const runs = replenishmentRuns(db);
  const now = new Date().toISOString();
  let run = runs.find(r => r.clientId === clientId && r.day === day);
  const status = items.length ? 'open' : 'empty';
  if (run) { run.items = items; run.generatedAt = now; run.daysCover = daysCover; run.status = status; }
  else { run = { id: uuidv4().slice(0, 8), clientId, day, generatedAt: now, daysCover, items, status }; runs.unshift(run); }
  if (runs.length > 400) runs.length = 400; // keep recent runs only
  return run;
}
function runDailyReplenishment() {
  try {
    if (!inventory.available()) return;
    const db = readDb();
    const day = sgDateStr();
    if (db.lastReplenishDay === day) return; // already generated today
    const clients = Object.keys(inventory.stockByClientTotals());
    for (const cid of clients) { try { generateReplenishmentRun(db, cid, day, 7); } catch (_) {} }
    db.lastReplenishDay = day;
    writeDb(db);
    console.log(`[IdealOne] Daily replenishment runs generated for ${clients.length} client(s) — ${day}`);
  } catch (e) { console.error('[IdealOne] daily replenishment failed:', e.message); }
}
setTimeout(runDailyReplenishment, 120 * 1000);        // shortly after boot
setInterval(runDailyReplenishment, 6 * 3600 * 1000);  // re-check every 6h (rolls over at the SGT day boundary)

// Photo retention — inbound photos for jobs ENDED more than 12 months ago are
// deleted from disk (metadata keeps a purged flag, so the GRN still shows how
// many photos existed). Mirrors the 12-month retention every other record uses.
function runInboundPhotoPurge() {
  try {
    const cutoff = new Date(Date.now() - 365 * 86400000).toISOString();
    const db = readDb();
    let purged = 0;
    for (const rec of db.inbound || []) {
      const ended = rec.state?.endTime;
      if (!ended || ended >= cutoff || !(rec.photos || []).length || rec.photos_purged) continue;
      try { fs.rmSync(path.join(INBOUND_PHOTO_DIR, rec.id), { recursive: true, force: true }); } catch (_) {}
      purged += rec.photos.length;
      rec.photo_count_before_purge = rec.photos.length;
      rec.photos = [];
      rec.photos_purged = true;
    }
    if (purged) { writeDb(db); console.log(`[IdealOne] Inbound photo purge: removed ${purged} photo(s) older than 12 months`); }
  } catch (e) { console.error('[IdealOne] photo purge failed:', e.message); }
}
setTimeout(runInboundPhotoPurge, 180 * 1000);
setInterval(runInboundPhotoPurge, 24 * 3600 * 1000);

// Today's replenishment run for a client (generates it on first access of the day
// if the scheduler hasn't yet). daysCover query overrides the default for the day.
app.get('/api/inventory/replenishment/run', requireAuth, (req, res) => {
  const clientId = reqClientId(req);
  if (!clientId) return res.status(400).json({ error: 'clientId query param is required' });
  const day = sgDateStr();
  const db = readDb();
  let run = replenishmentRuns(db).find(r => r.clientId === clientId && r.day === day);
  if (!run) { run = generateReplenishmentRun(db, clientId, day, Number(req.query.daysCover) || 7); writeDb(db); }
  res.json(run);
});
// Force-regenerate today's run (e.g. after changing days-of-cover).
app.post('/api/inventory/replenishment/run/generate', requireAuth, express.json(), (req, res) => {
  const clientId = String(req.body?.clientId || '').trim();
  if (!clientId) return res.status(400).json({ error: 'clientId required' });
  const db = readDb();
  const run = generateReplenishmentRun(db, clientId, sgDateStr(), Number(req.body?.daysCover) || 7);
  writeDb(db);
  res.json(run);
});

// Live (unstored) suggestions — kept for ad-hoc use.
app.get('/api/inventory/replenishment', requireAuth, (req, res) => {
  const clientId = reqClientId(req);
  if (!clientId) return res.status(400).json({ error: 'clientId query param is required' });
  res.json({
    daysCover: Number(req.query.daysCover) || 7,
    suggestions: inventory.replenishmentSuggestions(clientId, { daysCover: Number(req.query.daysCover) || 7, lookbackDays: Number(req.query.lookbackDays) || 28 }),
  });
});
// Apply one replenishment move (bulk → pick face). A transfer with an audit tag;
// capacity on the destination pick face still applies (override supported).
app.post('/api/inventory/replenishment/apply', requireAuth, express.json(), (req, res) => {
  try {
    const { sku, from_location, to_location, qty, clientId } = req.body || {};
    const cid = String(clientId || '').trim();
    if (!cid || !sku || !from_location || !to_location || !qty) return res.status(400).json({ error: 'clientId, sku, from_location, to_location, qty required' });
    const cap = inventory.binCapacityCheck(to_location, Number(qty));
    if (cap.exceeds && req.body?.override !== true) {
      return res.status(409).json({ needsCapacityOverride: true, location: to_location, ...cap, message: `${to_location} holds ${cap.occupied}/${cap.capacity}; adding ${cap.adding} exceeds by ${cap.over}.` });
    }
    const db = readDb();
    const result = inventory.transferStock(cid, sku, from_location, to_location, Number(qty), req.userId || '');
    logAudit('replenishment', { sku, clientId: cid, from: from_location, to: to_location, qty: Number(qty), by: req.userId || '' });
    // Refresh today's run so the applied SKU drops off (it's now at target) and
    // the checklist reflects what's still needed.
    const run = generateReplenishmentRun(db, cid, sgDateStr(), Number(req.body?.daysCover) || 7);
    writeDb(db);
    res.json({ ...result, run });
  } catch (e) { res.status(400).json({ error: e.message }); }
});
// Counts due — bins worth cycle-counting: never/staly counted, or repeat
// bin-empty discrepancies in the last 30 days (a repeat offender usually means
// a process problem at that location).
app.get('/api/inventory/count-suggestions', requireAuth, (req, res) => {
  const clientId = reqClientId(req);
  if (!clientId) return res.status(400).json({ error: 'clientId query param is required' });
  const bins = inventory.countDueBins(clientId, Number(req.query.staleDays) || 30);
  const cutoff = new Date(Date.now() - 30 * 86400000).toISOString();
  const discCount = {};
  for (const d of (readDb().stockDiscrepancies || [])) {
    if (d.clientId === clientId && (d.reportedAt || '') >= cutoff) discCount[d.location] = (discCount[d.location] || 0) + 1;
  }
  const out = [];
  const covered = new Set();
  for (const b of bins) {
    covered.add(b.location_id);
    const reasons = [];
    if ((discCount[b.location_id] || 0) >= 2) reasons.push(`${discCount[b.location_id]} bin-empty reports in 30d`);
    if (!b.last_counted) reasons.push('never counted');
    else if (b.stale) reasons.push(`last counted ${String(b.last_counted).slice(0, 10)}`);
    if (reasons.length) out.push({ location_id: b.location_id, qty: b.qty, reasons });
  }
  // Repeat-offender bins that currently hold NO stock (often BECAUSE a bin-empty
  // report just zeroed them) are exactly the ones to verify — include them too.
  for (const [loc, n] of Object.entries(discCount)) {
    if (n >= 2 && !covered.has(loc)) out.push({ location_id: loc, qty: 0, reasons: [`${n} bin-empty reports in 30d`] });
  }
  // Repeat-discrepancy bins first, then never-counted, then stale.
  out.sort((a, b) => (discCount[b.location_id] || 0) - (discCount[a.location_id] || 0));
  res.json({ suggestions: out.slice(0, 30) });
});

// ── Quarantine — damaged/KIV units from receiving, awaiting disposition ─────
app.get('/api/inventory/quarantine', requireAuth, (req, res) => {
  const list = readDb().quarantine || [];
  const status = req.query.status || 'open';
  res.json({
    open: list.filter(q => q.status === 'open').length,
    quarantine: (status === 'all' ? list : list.filter(q => q.status === status)).slice(0, 200),
  });
});
// Disposition: release (units passed inspection → sellable stock, ZORT told),
// dispose (scrapped) or return_to_client — the latter two just close the entry,
// since quarantined units never entered sellable stock in the first place.
app.post('/api/inventory/quarantine/:id/resolve', requireAuth, express.json(), (req, res) => {
  const db = readDb();
  const q = (db.quarantine || []).find(x => x.id === req.params.id);
  if (!q) return res.status(404).json({ error: 'Not found' });
  if (q.status !== 'open') return res.status(409).json({ error: 'Already resolved' });
  const action = String(req.body?.action || '').toLowerCase();
  const note = String(req.body?.note || '').slice(0, 500);
  if (!['release', 'dispose', 'return_to_client'].includes(action)) return res.status(400).json({ error: "action must be 'release', 'dispose' or 'return_to_client'" });
  const qty = Math.min(Math.max(1, Number(req.body?.qty) || q.qty), q.qty); // partial allowed
  if (action === 'release') {
    try {
      if (!inventory.get(q.sku, q.clientId)) inventory.upsert({ sku: q.sku, name: q.sku, clientId: q.clientId });
      inventory.adjust(q.sku, q.clientId, qty, 'quarantine_release', `Quarantine ${q.id} released (${q.condition})${note ? ' — ' + note : ''}`);
      zortNotifyStockChange(db, q.clientId, [q.sku]);
    } catch (e) { return res.status(400).json({ error: 'Release failed: ' + e.message }); }
  }
  if (qty < q.qty) { // partial: shrink the open entry, log the resolved part
    q.qty -= qty;
    (db.quarantine = db.quarantine || []).unshift({ ...q, id: uuidv4().slice(0, 8), qty, status: 'resolved', resolution: action, note, resolvedBy: req.userId || '', resolvedAt: new Date().toISOString() });
  } else {
    q.status = 'resolved'; q.resolution = action; q.note = note; q.resolvedBy = req.userId || ''; q.resolvedAt = new Date().toISOString();
  }
  writeDb(db);
  logAudit('quarantine_resolved', { id: q.id, sku: q.sku, condition: q.condition, action, qty, note, by: req.userId || '' });
  res.json({ ok: true });
});

// ── Stock discrepancies — every bin-empty report must be resolved ───────────
app.get('/api/inventory/discrepancies', requireAuth, (req, res) => {
  const list = readDb().stockDiscrepancies || [];
  const status = req.query.status || 'open';
  res.json({
    open: list.filter(d => d.status === 'open').length,
    discrepancies: (status === 'all' ? list : list.filter(d => d.status === status)).slice(0, 200),
  });
});
// Resolve one: 'found' (stock located/recounted — bin records were corrected by
// hand, sellable total is fine) or 'write_off' (units are genuinely gone —
// deduct them from the sellable total so ZORT stops offering ghosts).
app.post('/api/inventory/discrepancies/:id/resolve', requireAuth, express.json(), (req, res) => {
  const db = readDb();
  const d = (db.stockDiscrepancies || []).find(x => x.id === req.params.id);
  if (!d) return res.status(404).json({ error: 'Not found' });
  if (d.status !== 'open') return res.status(409).json({ error: 'Already resolved' });
  const action = String(req.body?.action || '').toLowerCase();
  const note = String(req.body?.note || '').slice(0, 500);
  if (!['found', 'write_off'].includes(action)) return res.status(400).json({ error: "action must be 'found' or 'write_off'" });
  const qty = Math.min(Number(req.body?.qty) || d.qty, d.qty); // allow partial write-off
  if (action === 'write_off') {
    try {
      inventory.adjust(d.sku, d.clientId, -qty, 'write_off', `Discrepancy ${d.id}: bin ${d.location} empty${note ? ' — ' + note : ''}`);
      zortNotifyStockChange(db, d.clientId, [d.sku]); // channels stop selling the ghosts
    } catch (e) { return res.status(400).json({ error: 'Write-off failed: ' + e.message }); }
  }
  d.status = 'resolved'; d.resolution = action; d.resolvedQty = action === 'write_off' ? qty : 0;
  d.note = note; d.resolvedBy = req.userId || ''; d.resolvedAt = new Date().toISOString();
  writeDb(db);
  logAudit('stock_discrepancy_resolved', { id: d.id, sku: d.sku, location: d.location, action, qty: d.resolvedQty, note, by: req.userId || '' });
  res.json(d);
});
