// ─────────────────────────────────────────────────────────────────────────────
//  WAVE PICKING — consolidate multiple pending orders into one location-sorted
//  pick list (lib/wave-pick.js). Waves live in db.waves (same readDb()/
//  writeDb() every other business record uses), so they're automatically
//  tenant-isolated. Additive: does not touch the existing Scan & Check
//  pack-verification flow — a wave answers "what do I walk and grab, in what
//  order, across N orders" (the picking phase); Scan & Check remains the
//  per-order pack/verify phase that happens afterwards.
// ─────────────────────────────────────────────────────────────────────────────
const { buildWave, _naturalCompare: waveNaturalCompare } = require('./lib/wave-pick');

function _findOrder(db, orderNumber) {
  for (const b of db.batches || []) {
    const o = (b.orders || []).find(x => x.order_number === orderNumber);
    if (o) return o;
  }
  return null;
}

function findWave(db, id) { return (db.waves || []).find(w => w.id === id); }

// Reverses a wave out of its orders — run when a completed wave's
// cancellation is approved (either the per-wave Master approval, or the
// Admin bulk-cancel below). Two paths, matched to what the wave actually
// did to its orders:
// - NEW-STYLE waves (wave.applied_to_orders === false — see
//   /api/waves/:id/complete) never wrote a single scanned piece; closing
//   only stamped state.wave_id. Reversal here is symmetric: just clear it.
// - LEGACY waves (field absent/true — completed before this redesign,
//   corrected per user: a wave used to auto-fill each order's scanned
//   totals at completion, which was wrong) genuinely wrote quantities via
//   the old apply-on-complete logic, so those get subtracted back out.
// Both paths skip (and report) any order already 'done' by the time
// reversal runs — never regress completed work. The legacy path also
// reverts status back to 'pending' only if the order's TOTAL scanned qty
// across ALL SKU lines is genuinely back to zero — an order with scans
// from OUTSIDE this wave (a packer's own manual scan) correctly keeps its
// 'processing' status instead of being wrongly reset.
function reverseWaveFromOrders(db, wave, req) {
  const reversedOrders = [];
  const skippedDone = [];
  if (wave.applied_to_orders === false) {
    for (const orderNumber of wave.order_numbers || []) {
      const batch = findBatchForOrder(db, orderNumber);
      const state = batch && (batch.orderStates || {})[orderNumber];
      if (!state) continue;
      if (state.status === 'done') { skippedDone.push(orderNumber); continue; }
      if (state.wave_id === wave.id) {
        delete state.wave_id;
        state.updated_at = new Date().toISOString();
        journalOrderState(orderNumber, state);
        reversedOrders.push(orderNumber);
      }
    }
    return { reversedOrders, skippedDone: [...new Set(skippedDone)] };
  }
  for (const pick of wave.picks) {
    if (pick.picked_qty < pick.total_qty) continue; // never applied in the first place
    for (const o of pick.orders) {
      const batch = findBatchForOrder(db, o.order_number);
      if (!batch || !batch.orderStates) continue;
      const state = batch.orderStates[o.order_number];
      if (!state) continue;
      if (state.status === 'done') { skippedDone.push(o.order_number); continue; }
      state.scanned[pick.sku] = Math.max(0, (state.scanned[pick.sku] || 0) - o.qty);
      addToActiveCarton(state, pick.sku, -o.qty);
      state.updated_at = new Date().toISOString();
      appendScanLog(state, { kind: 'wave_cancel_reversal', sku: pick.sku, location: pick.location || '', qty: -o.qty, waveId: wave.id, by: req.userId || 'master' });
      const totalScanned = Object.values(state.scanned).reduce((s, q) => s + q, 0);
      if (totalScanned === 0 && state.status === 'processing') state.status = 'pending';
      if (state.wave_id === wave.id) delete state.wave_id;
      journalOrderState(o.order_number, state);
      if (!reversedOrders.includes(o.order_number)) reversedOrders.push(o.order_number);
    }
  }
  return { reversedOrders, skippedDone: [...new Set(skippedDone)] };
}

// ?detail=1 adds each wave's per-order scan progress — for Wave Management
// (how far along is each order that this wave touched). Resolved through
// globalOrdersWithState() on demand only; the plain list stays cheap.
app.get('/api/waves', requireAuth, (req, res) => {
  const db = readDb();
  let waves = (db.waves || []).slice().sort((a, b) => b.created_at.localeCompare(a.created_at));
  waves.forEach(waveLocationStats);   // recount unlocated lines against the resolved bins
  if (req.query.detail === '1') {
    const byOrderNumber = new Map(globalOrdersWithState().map(o => [o.order_number, o]));
    waves = waves.map(w => ({
      ...w,
      orders: (w.order_numbers || []).map(on => {
        const o = byOrderNumber.get(on);
        const scannedTotal = o ? Object.values(o.scanned || {}).reduce((s, v) => s + v, 0) : 0;
        return { order_number: on, status: o?.scan_status || 'missing', scannedTotal, totalQty: o?.total_qty || 0 };
      }),
    }));
  }
  res.json(waves);
});

app.get('/api/waves/:id', requireAuth, (req, res) => {
  const db = readDb();
  const wave = findWave(db, req.params.id);
  if (!wave) return res.status(404).json({ error: 'Wave not found' });
  res.json(waveLocationStats(wave));
});

// Enrich a wave's consolidated pick rows with the ACTUAL bins to pick from
// (FEFO/FIFO over bin lots), and re-sort the walk by bin location. Display only —
// the physical decrement still happens later when each order is re-scanned and
// completed (so a wave never double-decrements bins). Falls back to the printed
// location code for any SKU with no binned stock.
function enrichWaveWithBins(db, wave) {
  if (!inventory.available()) return;
  // Same ledger, same reason. A SKU printed at two locations becomes two pick
  // rows, and without this each row re-allocates from the top of the bin list
  // and both point at the same bin.
  const claim = inventory.newPickClaim();
  // order_number -> {clientId, strategy} from its batch.
  const meta = {};
  for (const b of db.batches || []) {
    const clientId = b.inventory_client || invClientId(b.client_name);
    const strategy = b.pick_strategy || 'fefo';
    for (const o of b.orders || []) meta[o.order_number] = { clientId, strategy };
  }
  for (const row of wave.picks || []) {
    const first = (row.orders || [])[0];
    const m = first && meta[first.order_number];
    if (!m || !m.clientId) continue;
    try {
      const upc = Number((inventory.get(row.sku, m.clientId) || {}).units_per_carton) || 1;
      row.units_per_carton = upc;
      const a = inventory.allocatePick(m.clientId, row.sku, row.total_qty, m.strategy, upc, claim);
      // Aggregate lot picks into one row per bin for display.
      const byLoc = []; const bidx = {};
      for (const p of a.picks) { if (bidx[p.location_id] === undefined) { bidx[p.location_id] = byLoc.length; byLoc.push({ location_id: p.location_id, qty: 0, expiry_date: p.expiry_date || null }); } const e = byLoc[bidx[p.location_id]]; e.qty += p.qty; if (p.expiry_date && (!e.expiry_date || p.expiry_date < e.expiry_date)) e.expiry_date = p.expiry_date; }
      row.bins = byLoc;
      row.bin_shortfall = a.shortfall;
      row.bin_location = a.picks.length ? a.picks[0].location_id : '';
    } catch (_) { /* leave printed location as the guide */ }
  }
  // Re-sort the walk by real bin (natural order); rows with a bin come first,
  // then rows still relying on the printed code, then unlocated.
  wave.picks.sort((x, y) => {
    const xl = x.bin_location || x.location || '';
    const yl = y.bin_location || y.location || '';
    if (!xl && yl) return 1;
    if (xl && !yl) return -1;
    const c = waveNaturalCompare(xl, yl);
    return c !== 0 ? c : x.sku.localeCompare(y.sku);
  });
  waveLocationStats(wave);
}

// A ROW WITH A BIN IS NOT AN UNLOCATED ROW. `buildWave` counts
// `stats.unlocatedLines` from the PRINTED location on the order line, which is
// blank for every order that arrives without one — and that count was never
// revisited after `enrichWaveWithBins` resolved the real bins. So a wave whose
// every row showed a bin still announced "6 line(s) have no location"
// (reported from the floor, with all six bins visible on screen).
//
// Recounted here, and called on every READ as well as at creation, so waves
// built before this fix heal themselves instead of needing a migration. A row
// is unlocated only when it has NEITHER a resolved bin nor a printed code.
function waveLocationStats(wave) {
  if (!wave || !wave.stats) return wave;
  wave.stats.unlocatedLines = (wave.picks || [])
    .filter(p => !String(p.bin_location || p.location || '').trim()).length;
  return wave;
}

app.post('/api/waves', requireAuth, express.json(), (req, res) => {
  const { name, order_numbers } = req.body || {};
  if (!Array.isArray(order_numbers) || !order_numbers.length) {
    return res.status(400).json({ error: 'order_numbers (non-empty array) is required' });
  }
  const db = readDb();
  const orders = [];
  const notFound = [];
  for (const num of order_numbers) {
    const o = _findOrder(db, num);
    if (o) orders.push(o); else notFound.push(num);
  }
  if (!orders.length) return res.status(404).json({ error: 'None of the given orders were found', notFound });

  const { picks, stats } = buildWave(orders);
  const wave = {
    id: uuidv4(),
    code: nextWaveCode(db),
    name: String(name || `Wave-${new Date().toISOString().slice(0, 16).replace('T', ' ')}`).trim(),
    status: 'created',
    created_at: new Date().toISOString(),
    created_by: req.userId || '',
    order_numbers: orders.map(o => o.order_number),
    picks,
    stats,
  };
  enrichWaveWithBins(db, wave); // stamp each pick row with its real FEFO/FIFO bins + re-sort the walk
  db.waves = db.waves || [];
  db.waves.unshift(wave);
  writeDb(db);
  logAudit('wave_created', { id: wave.id, orders: wave.order_numbers, lineCount: stats.lineCount, by: req.userId || '' });
  res.status(201).json({ ...wave, notFound: notFound.length ? notFound : undefined });
});

// Mark qty picked for one (location, sku) line — additive: qty accumulates,
// so a hardware scanner incrementing by 1 per scan works the same as a
// packer typing the full quantity at once.
app.post('/api/waves/:id/pick', requireAuth, express.json(), (req, res) => {
  const { sku, location, qty } = req.body || {};
  const pickedQty = Number(qty);
  if (!sku || !Number.isFinite(pickedQty) || pickedQty <= 0) {
    return res.status(400).json({ error: 'sku and a positive qty are required' });
  }
  const db = readDb();
  const wave = (db.waves || []).find(w => w.id === req.params.id);
  if (!wave) return res.status(404).json({ error: 'Wave not found' });
  const row = wave.picks.find(p => p.sku === sku && (p.location || '') === (location || ''));
  if (!row) return res.status(404).json({ error: 'No such (sku, location) line in this wave' });
  row.picked_qty = Math.min(row.total_qty, row.picked_qty + pickedQty);
  if (wave.status === 'created') wave.status = 'picking';
  writeDb(db);
  journalWaveState(wave.id, wave);  // keyed-in quantities are as losable as scans
  res.json(wave);
});

// Which inventory account a wave's products belong to — needed only for the
// item-master barcode cross-reference in matchScannedSku. Taken from the
// batch of the wave's first order, the same way enrichWaveWithBins resolves
// its client. A wave spanning two clients falls back to the first one's
// catalogue; SKU/alias matching is unaffected either way.
function waveClientId(db, wave) {
  const first = (wave.order_numbers || [])[0];
  if (!first) return '';
  const b = findBatchForOrder(db, first);
  return b ? (b.inventory_client || invClientId(b.client_name)) : '';
}

// SCAN a code against the wave's consolidated pick list. One scan = one piece,
// the same convention as outbound item scanning, so a gun works with no typing
// at all — this is what makes wave picking usable on the floor instead of
// tapping "Pick" and keying a number per line.
//
// Deliberately NOT folded into /pick above: that endpoint takes an explicit
// (sku, location, qty) that the caller already knows, whereas this one has to
// work out WHICH line an arbitrary barcode belongs to and pick the right one
// of several. Both funnel into the same picked_qty field.
app.post('/api/waves/:id/scan', requireAuth, express.json(), (req, res) => {
  const raw = String((req.body || {}).code || '').trim();
  if (!raw) return res.status(400).json({ error: 'code required' });
  const qty = (req.body || {}).qty === undefined ? 1 : Number(req.body.qty);
  if (!Number.isFinite(qty) || qty <= 0) return res.status(400).json({ error: 'qty must be a positive number' });

  const db = readDb();
  const wave = findWave(db, req.params.id);
  if (!wave) return res.status(404).json({ error: 'Wave not found' });
  if (wave.status === 'completed' || wave.status === 'cancelled') {
    return res.status(409).json({ error: `This wave is ${wave.status} — scanning is closed.`, waveClosed: true });
  }

  // Idempotent scans — same rule and same reason as /api/scan/increment: a
  // scan whose response was lost is retried with the SAME eventId and must not
  // count the piece twice.
  const eventId = String((req.body || {}).eventId || '').slice(0, 64);
  if (eventId && wave.scanEventIds?.includes(eventId)) {
    return res.json({ wave, matched: null, dedup: true });
  }

  const sku = resolveBeTimeCode2(raw);
  const clientId = waveClientId(db, wave);
  // picks are already in walk order, so the first row of this product that
  // still needs pieces is the one the picker is standing at. A SKU stocked in
  // two locations therefore fills in the order they walk, not arbitrarily.
  const outstanding = (wave.picks || []).filter(p => p.picked_qty < p.total_qty);
  const row = matchScannedSku(raw, sku, outstanding, p => p.sku, clientId);

  if (!row) {
    // "Already fully picked" is a different thing from "not on this wave", and
    // the picker needs to be told which: an extra piece in hand for a finished
    // line is a routine floor event, not an unknown barcode.
    const done = matchScannedSku(raw, sku, wave.picks || [], p => p.sku, clientId);
    if (done) {
      return res.status(409).json({
        error: `${done.sku} is already fully picked (${done.picked_qty}/${done.total_qty}).`,
        alreadyComplete: true, sku: done.sku,
      });
    }
    return res.status(404).json({
      error: `"${raw}" is not on this wave's pick list.`,
      notInWave: true, code: raw, resolved: sku !== raw ? sku : null,
    });
  }

  const before = row.picked_qty;
  row.picked_qty = Math.min(row.total_qty, row.picked_qty + qty);
  const applied = row.picked_qty - before;
  if (wave.status === 'created') wave.status = 'picking';
  // Registered only now that a piece has actually been counted, so the 404/409
  // refusals above never burn the id for a legitimate retry.
  if (eventId) {
    if (!wave.scanEventIds) wave.scanEventIds = [];
    wave.scanEventIds.push(eventId);
    if (wave.scanEventIds.length > 100) wave.scanEventIds.splice(0, wave.scanEventIds.length - 100);
  }
  writeDb(db);
  journalWaveState(wave.id, wave);  // crash-proof: db.json persistence is deferred
  logAudit('wave_pick_scanned', {
    id: wave.id, code: raw, sku: row.sku, location: row.location || '',
    qty: applied, by: req.userId || '',
  });
  res.json({
    wave,
    matched: {
      sku: row.sku, description: row.description || '',
      location: row.location || '', bin_location: row.bin_location || '',
      picked_qty: row.picked_qty, total_qty: row.total_qty, applied,
      complete: row.picked_qty >= row.total_qty,
    },
  });
});

// CLOSING A WAVE WRITES NOTHING INTO THE ORDERS (corrected per user — the
// previous design auto-filled each order's scanned totals at completion,
// which was wrong). A wave covers ONLY the consolidated floor pick — each
// (location, SKU) visited once for the wave's total. Sub-picking that pile
// back down to order level is the normal per-order scan flow: the packer
// opens each order and scans every piece from zero, so per-order
// verification is a real physical count, not a pre-filled number. The only
// mark left on each order is state.wave_id, driving the "Scan to Pack" pill.
app.post('/api/waves/:id/complete', requireAuth, express.json(), (req, res) => {
  const db = readDb();
  const wave = findWave(db, req.params.id);
  if (!wave) return res.status(404).json({ error: 'Wave not found' });
  if (wave.status === 'completed') return res.status(409).json({ error: 'Wave already completed' });
  const incomplete = wave.picks.filter(p => p.picked_qty < p.total_qty).length;
  if (incomplete && req.body?.force !== true) {
    return res.status(409).json({ needsForceComplete: true, incomplete, message: `${incomplete} pick line(s) are not fully picked yet. Close the wave anyway?` });
  }
  const appliedOrders = [];
  const skippedDone = [];
  for (const orderNumber of wave.order_numbers || []) {
    const batch = findBatchForOrder(db, orderNumber);
    if (!batch) continue;
    if (!batch.orderStates) batch.orderStates = {};
    const state = batch.orderStates[orderNumber] || { status: 'pending', scanned: {} };
    if (state.status === 'done') { skippedDone.push(orderNumber); continue; }
    state.wave_id = wave.id;
    state.updated_at = new Date().toISOString();
    batch.orderStates[orderNumber] = state;
    journalOrderState(orderNumber, state);
    appliedOrders.push(orderNumber);
  }
  wave.status = 'completed';
  wave.completed_at = new Date().toISOString();
  wave.applied_to_orders = false; // legacy waves (field absent) DID write quantities — see reverseWaveFromOrders
  writeDb(db);
  logAudit('wave_completed', { id: wave.id, forced: !!incomplete, appliedOrders: appliedOrders.length, by: req.userId || '' });
  res.json({ ...wave, appliedOrders, skippedDone });
});

// Instant cancel — only for a wave that hasn't been completed yet, so
// nothing has been applied to any order's real state to undo.
app.post('/api/waves/:id/cancel', requireAuth, express.json(), (req, res) => {
  const db = readDb();
  const wave = findWave(db, req.params.id);
  if (!wave) return res.status(404).json({ error: 'Wave not found' });
  if (wave.status === 'completed') return res.status(409).json({ error: 'This wave is already completed — use the cancellation request flow (requires Master approval) instead.' });
  wave.status = 'cancelled';
  wave.cancelled_at = new Date().toISOString();
  writeDb(db);
  logAudit('wave_cancelled', { id: wave.id, by: req.userId || '' });
  res.json(wave);
});

// Cancelling a COMPLETED wave needs Master approval — same admin-request +
// Master-approve pattern as order/inbound deletion (reason + the admin's own
// password re-confirmed). Approval REVERSES what the wave applied rather
// than deleting the wave record.
app.post('/api/waves/:id/cancel-request', requireAuth, express.json(), (req, res) => {
  const { reason, password } = req.body || {};
  const reasonTrim = String(reason || '').trim();
  if (!reasonTrim) return res.status(400).json({ error: 'A reason is required to request cancellation.' });
  const auth = verifyAdminReconfirm(req);   // own login password OR the Administrator key
  if (auth.error) return res.status(auth.code).json({ error: auth.error, authFailed: auth.code === 403 });
  const db = readDb();
  const wave = findWave(db, req.params.id);
  if (!wave) return res.status(404).json({ error: 'Wave not found' });
  if (wave.status !== 'completed') return res.status(400).json({ error: 'Only a completed wave needs a cancellation request — an in-progress wave can be cancelled instantly.' });
  if (wave.pending_cancellation) return res.status(409).json({ error: 'A cancellation request is already pending for this wave.' });
  wave.pending_cancellation = { reason: reasonTrim, requestedBy: req.userId, requestedAt: new Date().toISOString() };
  writeDb(db);
  logAudit('wave_cancellation_requested', { id: wave.id, by: req.userId || '', reason: reasonTrim });
  res.json({ ok: true });
});

app.get('/api/master/wave-pending-cancellations', (req, res) => {
  if (!checkMaster(req, res)) return;
  const db = readDb();
  const byId = new Map(readUsers().map(u => [u.id, u.name || u.id]));
  const out = (db.waves || [])
    .filter(w => w.pending_cancellation)
    .map(w => ({
      id: w.id, name: w.name, orderNumbers: w.order_numbers, stats: w.stats,
      reason: w.pending_cancellation.reason,
      requestedBy: w.pending_cancellation.requestedBy,
      requestedByName: byId.get(w.pending_cancellation.requestedBy) || w.pending_cancellation.requestedBy,
      requestedAt: w.pending_cancellation.requestedAt,
    }))
    .sort((a, b) => String(a.requestedAt).localeCompare(String(b.requestedAt)));
  res.json(out);
});

// Shared by the per-wave Master approval above and the Admin bulk-cancel
// below: reverses the wave out of its orders (reverseWaveFromOrders — which
// itself branches new-style vs legacy) and marks it cancelled. Does NOT
// persist (writeDb) or clear pending_cancellation/pending_purge — callers do
// that themselves, since they differ (one clears pending_cancellation, the
// other sets pending_purge).
function reverseWaveAndCancel(db, wave, req) {
  const { reversedOrders, skippedDone } = reverseWaveFromOrders(db, wave, req);
  wave.status = 'cancelled';
  wave.cancelled_at = new Date().toISOString();
  return { reversedOrders, skippedDone };
}

app.post('/api/master/wave-pending-cancellations/:id/approve', (req, res) => {
  if (!checkMaster(req, res)) return;
  const db = readDb();
  const wave = findWave(db, req.params.id);
  if (!wave || !wave.pending_cancellation) return res.status(404).json({ error: 'No pending cancellation request for this wave.' });
  const pending = wave.pending_cancellation;
  const { reversedOrders, skippedDone } = reverseWaveAndCancel(db, wave, req);
  delete wave.pending_cancellation;
  writeDb(db);
  logAudit('wave_cancellation_approved', {
    id: wave.id, by: req.userId || 'master', reason: pending.reason, requestedBy: pending.requestedBy,
    reversedOrders: reversedOrders.length, skippedDone: skippedDone.length,
  });
  res.json({ ok: true, reversedOrders, skippedDone });
});

app.post('/api/master/wave-pending-cancellations/:id/reject', (req, res) => {
  if (!checkMaster(req, res)) return;
  const note = String(req.body?.note || '').trim();
  const db = readDb();
  const wave = findWave(db, req.params.id);
  if (!wave || !wave.pending_cancellation) return res.status(404).json({ error: 'No pending cancellation request for this wave.' });
  const pending = wave.pending_cancellation;
  delete wave.pending_cancellation;
  writeDb(db);
  logAudit('wave_cancellation_rejected', { id: wave.id, by: req.userId || 'master', requestedBy: pending.requestedBy, reason: pending.reason, note });
  res.json({ ok: true });
});

// ADMIN bulk-cancel (select-all): takes effect IMMEDIATELY — legacy waves
// that prefilled quantities are reversed on the spot (orders back to 0
// scanned/pending so packers can re-scan them piece by piece), new-style
// waves just lose their wave_id pill, in-progress waves cancel outright
// (nothing was ever written). The cancelled wave RECORD then stays in
// db.waves flagged pending_purge until Master approves deleting it clean
// from the data (Administrator → Pending Deletions → Wave Deletion
// Requests) — the operational effect never waits on that approval.
app.post('/api/waves/bulk-cancel', requireAuth, express.json(), (req, res) => {
  const auth = verifyAdminReconfirm(req);   // own login password OR the Administrator key
  if (auth.error) return res.status(auth.code).json({ error: auth.error, authFailed: auth.code === 403 });
  const db  = readDb();
  const ids = req.body?.all === true
    ? (db.waves || []).filter(w => w.status !== 'cancelled').map(w => w.id)
    : [...new Set((req.body?.ids || []).map(String))];
  if (!ids.length) return res.status(400).json({ error: 'No waves selected' });
  const results = [];
  for (const id of ids) {
    const wave = findWave(db, id);
    if (!wave || wave.status === 'cancelled') continue;
    if (wave.status !== 'completed') {
      // Still created/picking — nothing was ever written to any order
      wave.status = 'cancelled';
      wave.cancelled_at = new Date().toISOString();
      delete wave.pending_cancellation;
      results.push({ id, reversed: 0, skippedDone: [] });
    } else {
      const { reversedOrders, skippedDone } = reverseWaveAndCancel(db, wave, req);
      delete wave.pending_cancellation;
      results.push({ id, reversed: reversedOrders.length, skippedDone });
    }
    findWave(db, id).pending_purge = { requestedBy: req.userId, requestedAt: new Date().toISOString() };
  }
  writeDb(db);
  logAudit('wave_bulk_cancelled', { waves: results.map(r => r.id), count: results.length, by: req.userId || '' });
  res.json({ ok: true, cancelled: results });
});

// Master purge queue — cancelled waves an Admin already asked to have
// deleted clean from the data. Approve = the wave record is removed from
// db.waves for good; Reject = the record stays (as cancelled history) and
// the request is cleared. Neither touches any order — the operational
// reversal already happened at cancel time.
app.get('/api/master/wave-pending-purges', (req, res) => {
  if (!checkMaster(req, res)) return;
  const byId = new Map(readUsers().map(u => [u.id, u.name || u.id]));
  const db = readDb();
  const out = (db.waves || [])
    .filter(w => w.pending_purge)
    .map(w => ({
      id: w.id, name: w.name, orderNumbers: w.order_numbers,
      cancelledAt: w.cancelled_at || null,
      requestedBy: w.pending_purge.requestedBy,
      requestedByName: byId.get(w.pending_purge.requestedBy) || w.pending_purge.requestedBy,
      requestedAt: w.pending_purge.requestedAt,
    }))
    .sort((a, b) => String(a.requestedAt).localeCompare(String(b.requestedAt)));
  res.json(out);
});

app.post('/api/master/wave-pending-purges/:id/approve', (req, res) => {
  if (!checkMaster(req, res)) return;
  const db  = readDb();
  const idx = (db.waves || []).findIndex(w => w.id === req.params.id && w.pending_purge);
  if (idx === -1) return res.status(404).json({ error: 'No pending purge request for this wave.' });
  const wave = db.waves[idx];
  db.waves.splice(idx, 1);
  writeDb(db);
  logAudit('wave_purge_approved', { id: wave.id, orders: wave.order_numbers, requestedBy: wave.pending_purge.requestedBy, by: req.userId || 'master' });
  res.json({ ok: true });
});

app.post('/api/master/wave-pending-purges/:id/reject', (req, res) => {
  if (!checkMaster(req, res)) return;
  const db = readDb();
  const wave = findWave(db, req.params.id);
  if (!wave || !wave.pending_purge) return res.status(404).json({ error: 'No pending purge request for this wave.' });
  const pending = wave.pending_purge;
  delete wave.pending_purge;
  writeDb(db);
  logAudit('wave_purge_rejected', { id: wave.id, requestedBy: pending.requestedBy, by: req.userId || 'master' });
  res.json({ ok: true });
});

const PORT = process.env.PORT || 3000;
// ── Last line of defence: a route that THREW ────────────────────────────────
// There was no error middleware at all, so an uncaught throw fell to Express's
// default handler — a bare 500 with the stack swallowed. This records the real
// message first (the /api/portal finish hook picks it up out of res.locals, so
// a client-facing failure reaches System Outages with something diagnosable in
// it), then answers in the shape the caller expects. Registered last, after
// every route, which is what makes Express treat it as the error handler.
app.use((err, req, res, next) => {
  const detail = String(err?.message || err || 'Unknown error').slice(0, 500);
  console.error('[unhandled]', req.method, req.originalUrl, '—', detail);
  res.locals._errDetail = detail;
  res.locals._errStack  = String(err?.stack || '').slice(0, 4000);
  // Anything outside the portal has no finish hook, so file it here instead.
  if (!String(req.path || '').startsWith('/api/portal')) {
    try {
      recordSystemError({
        app: 'office', context: 'Server error',
        message: `${req.method} ${req.path} — ${detail}`,
        stack: res.locals._errStack, page: req.path,
        userAgent: req.headers['user-agent'], user: req.userId || '',
      });
    } catch (_) { /* recording a fault must never raise one */ }
  }
  if (res.headersSent) return next(err);
  res.status(500).json({ error: 'Something went wrong at our end. It has been reported.' });
});

app.listen(PORT, () => console.log(`Fulfillment Scanner on port ${PORT}`))
  .on('error', err => {
    if (err.code === 'EADDRINUSE') {
      // A second copy is already running — exit cleanly instead of crashing
      console.error(`[IdealOne] Port ${PORT} is already in use — another instance is running. Exiting.`);
      process.exit(1);
    }
    throw err;
  });

// Initialize MySQL in the background (non-blocking)
initMysqlPool().catch(err => console.error('[Startup] MySQL init failed:', err.message));

// UNCLEAN RESTART → a System Outage row. Same fixed wording every time so
// repeats COUNT on one row instead of spamming the list; the previous boot
// time rides in `page` so each occurrence is still traceable. This is what
// turns "I keep receiving crash emails" into evidence: rows here = the
// process really is dying (crash / out-of-memory kill); no rows = the emails
// are the platform misreading ordinary redeploy handoffs.
if (PERSISTENCE.lastStopClean === false) {
  setTimeout(() => {
    try {
      recordSystemError({
        app: 'office', context: 'server-restart',
        message: 'Server restarted without a clean shutdown — a real crash, an out-of-memory kill, or a forced stop. If crash emails from the host line up with this row\'s times, the restarts are genuine.',
        page: `previous boot ${PERSISTENCE.lastUncleanBootAt || 'unknown'} → restarted ${SERVER_BOOTED_AT}`,
      });
      logAudit('server_unclean_restart', { previousBootAt: PERSISTENCE.lastUncleanBootAt || '', restartedAt: SERVER_BOOTED_AT, uncleanStops: PERSISTENCE.uncleanStops });
    } catch (e) { console.error('[persistence] could not record unclean restart:', e.message); }
  }, 5000);
}
